// Canvas-drawn axis colors (tick text, axis titles, tick marks, grid) — CSS can't reach
// these, so they're injected as FUNCTIONS into every plot's axes by the uPlot wrapper
// below; uPlot re-resolves function-valued strokes on every redraw, so a dark-mode
// toggle only needs refreshAllPlotThemes(). Light values mirror uPlot's own defaults
// so light mode renders unchanged.
function plotAxisTextColor() { return document.body.classList.contains('dark-mode') ? '#d0d0d0' : 'black'; }
function plotGridColor() { return document.body.classList.contains('dark-mode') ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.07)'; }
function plotTickColor() { return document.body.classList.contains('dark-mode') ? 'rgba(255,255,255,0.35)' : 'rgba(0,0,0,0.07)'; }

// Quantize every Y-axis gutter so sub-pixel re-measures stop shivering the X ticks.
(function stabilizeUPlotAxisSizes() {
    if (typeof uPlot === 'undefined' || uPlot.__shiverWrapped) return;
    const _origUPlot = uPlot;
    const _measureCtx = document.createElement('canvas').getContext('2d');
    let _fontFamily = null;

    function quantizedAxisSize(hasLabel) {
        const QUANTUM = 8;
        const GAP     = 10;
        const LABELPX = hasLabel ? 30 : 0;  // uPlot labelSize default
        return (u, values) => {
            // uPlot calls size() with values=null on its first sizing pass (before ticks
            // exist); guard so we don't deref null and throw, which would halt page init.
            if (!values || !values.length) return Math.ceil((GAP + LABELPX + 4) / QUANTUM) * QUANTUM;
            if (_fontFamily === null) {
                try { _fontFamily = getComputedStyle(u.root).fontFamily || 'sans-serif'; }
                catch (e) { _fontFamily = 'sans-serif'; }
            }
            _measureCtx.font = '12px ' + _fontFamily;
            let maxW = 0;
            for (let i = 0; i < values.length; i++) {
                const w = _measureCtx.measureText(String(values[i])).width;
                if (w > maxW) maxW = w;
            }
            const raw = maxW + GAP + LABELPX + 4;
            return Math.ceil(raw / QUANTUM) * QUANTUM;
        };
    }

    const Wrapped = function (opts, data, el) {
        if (opts && Array.isArray(opts.axes)) {
            // Phones: a rotated Y-axis title costs 30px of plot width per side (60px on
            // dual-axis plots) — drop the titles below 600px; units already live in the
            // legends. Only explicit side 1/3 axes: the side-undefined labeled Y axes
            // (bode, field-decay) have no legend and already run tuned 22-24px labels.
            // Decided per-plot at build time; a later rotation only setSize()s.
            const compact = document.documentElement.clientWidth <= 600;
            opts.axes.forEach(ax => {
                if (!ax) return;
                // Theme injection — only fills in what the plot didn't specify, so the
                // scope/bode plots that hardcode their own axis colors keep them.
                if (ax.stroke === undefined) ax.stroke = plotAxisTextColor;
                ax.grid = ax.grid || {};
                if (ax.grid.stroke === undefined) ax.grid.stroke = plotGridColor;
                ax.ticks = ax.ticks || {};
                if (ax.ticks.stroke === undefined) ax.ticks.stroke = plotTickColor;
                if (ax.side !== 1 && ax.side !== 3) return;   // Y axes only below
                if (compact) delete ax.label;
                if (ax.size === undefined) ax.size = quantizedAxisSize(!!ax.label);
            });
        }
        const u = new _origUPlot(opts, data, el);
        (window._allUPlots = window._allUPlots || new Set()).add(u);   // refreshAllPlotThemes() redraw registry
        return u;
    };
    Object.assign(Wrapped, _origUPlot);   // preserve uPlot.rangeNum/assign/etc.
    Wrapped.__shiverWrapped = true;
    uPlot = Wrapped;
    try { window.uPlot = Wrapped; } catch (e) {}
})();


// STALENESS DISPLAY THRESHOLDS
// These control when sensor readings gray out in the UI only.
// They have zero effect on the regulator or field control logic —
// that staleness is governed by the hardcoded 20s temp-stale threshold
// and the hardcoded 30s in buildTickSnapshot() on the ESP32.
//
// The timestamp payload sends every 3s, so any threshold below
// ~6s will cause false stale flashes even with healthy sensors.
const STALE_THRESHOLD_DEFAULT_MS = 6000;   // All sensors except temperature
const STALE_THRESHOLD_TEMP_MS = 12000;  // Alternator/thermistor temp read every 5s — allows one failed read
// BMP388 board temp + barometric pressure run a 4s forced-conversion cycle. Set to the ESP32's
// DATA_TIMEOUT so the gray appears exactly when firmware stops trusting the value (drops the
// battery-temp gain derate, skips the cold-charge lockout) — not on some unrelated UI number.
// 4s cycle means one missed read (8s) still reads fresh; two (12s) gray, same as firmware.
const STALE_THRESHOLD_BOARD_MS = 10000;

// Numerical-gauge render throttle. CSV1 LiveStream arrives every webgaugesinterval (~100ms)
// for smooth plots, but rendering noisy gauges that fast makes the last digit unreadable.
// Plots, setting echoes, alignment indicators, and field-status banner are NOT affected —
// only the criticalFields DOM writes (battery V/A, alt amps, RPM, dutyCycle, PID, IMU live).
const GAUGE_RENDER_INTERVAL_MS = 500;


// PID Tuning Plot 
let yyMin = -5;    // Default until CSVData3 updates it
let yyMax = 105;
let xTime = 30;
let cachedYyMin = null;
let cachedYyMax = null;
let cachedXTime = null;

// Temperature unit preference — 0=°F (default), 1=°C. Echoed from CSV3.
let displayTempUnit = 0;

function toDisplayTemp(val_f) {
    return displayTempUnit === 1 ? (val_f - 32) * 5 / 9 : val_f;
}
function toDisplayTempDelta(delta_f) {
    return displayTempUnit === 1 ? delta_f * 5 / 9 : delta_f;
}
function fromDisplayTemp(val_disp) {  // inverse of toDisplayTemp: display unit → native °F
    return displayTempUnit === 1 ? val_disp * 9 / 5 + 32 : val_disp;
}

// Re-bake unit-dependent plot state after a display-unit flip. The live temp plot buffer
// holds DISPLAY units — remap it in place; the thermal ring and LT store stay native °F
// and re-convert at render, so those plots only need tearing down so labels regenerate.
function retargetTempPlotsForUnit(prevUnit) {
    const remap = prevUnit === 1 ? (v => v * 9 / 5 + 32) : (v => (v - 32) * 5 / 9);
    if (typeof temperatureData !== 'undefined' && temperatureData && temperatureData[1]) {
        const s = temperatureData[1];
        for (let i = 0; i < s.length; i++) if (s[i] != null && Number.isFinite(s[i])) s[i] = remap(s[i]);
        if (typeof plotInterp !== 'undefined' && plotInterp.temperature) {
            const p = plotInterp.temperature;
            if (p.prevY && Number.isFinite(p.prevY[0])) p.prevY[0] = remap(p.prevY[0]);
            if (p.nextY && Number.isFinite(p.nextY[0])) p.nextY[0] = remap(p.nextY[0]);
        }
    }
    if (typeof temperaturePlot !== 'undefined' && temperaturePlot) {
        temperaturePlot.destroy();
        initTemperaturePlot();
        if (typeof recomputeAutoScales === 'function' && typeof autoScaleTemp !== 'undefined' && autoScaleTemp) recomputeAutoScales(true);
    }
    if (typeof thermalY !== 'undefined' && thermalY.p0 && thermalY.p0.temp) {  // session-local pin, typed in display units
        thermalY.p0.temp = [remap(thermalY.p0.temp[0]), remap(thermalY.p0.temp[1])];
    }
    if (typeof thermalLogPlots !== 'undefined' && thermalLogPlots[0]) {
        thermalLogPlots[0].destroy(); thermalLogPlots[0] = null;
        thermalRenderAll();
    }
    if (typeof window.ltOnTempUnitChanged === 'function') window.ltOnTempUnitChanged(prevUnit);
}
let _plotsTempUnit = 0;   // unit currently baked into plot buffers/labels; updateAllTempUnitLabels reconciles
function tempUnitLabel() {
    return displayTempUnit === 1 ? '°C' : '°F';
}
function updateAllTempUnitLabels() {
    const lbl = tempUnitLabel();
    document.querySelectorAll('.temp-unit-label').forEach(el => { el.textContent = lbl; });
    document.querySelectorAll('.temp-rate-label').forEach(el => { el.textContent = lbl + '/s'; });
    // Retarget HTML min/max validation to the display unit — the browser validates the
    // display-unit value BEFORE onsubmit converts it, so °F-authored bounds mis-gate °C
    // entries (e.g. min="0" blocked every sub-zero °C low-alarm). Bounds are authored in
    // °F via data-tmin-f/data-tmax-f (data-tdelta="1" for spans: scale only, no -32 shift).
    document.querySelectorAll('input[data-tmin-f], input[data-tmax-f]').forEach(inp => {
        const conv = inp.dataset.tdelta === '1' ? toDisplayTempDelta : toDisplayTemp;
        if (inp.dataset.tminF !== undefined) inp.min = Math.floor(conv(parseFloat(inp.dataset.tminF)));
        if (inp.dataset.tmaxF !== undefined) inp.max = Math.ceil(conv(parseFloat(inp.dataset.tmaxF)));
    });
    document.querySelectorAll('input[data-tmin-c], input[data-tmax-c]').forEach(inp => {  // °C-native (capTempRef)
        if (inp.dataset.tminC !== undefined) inp.min = Math.floor(toDisplayTempFromC(parseFloat(inp.dataset.tminC)));
        if (inp.dataset.tmaxC !== undefined) inp.max = Math.ceil(toDisplayTempFromC(parseFloat(inp.dataset.tmaxC)));
    });
    if (_plotsTempUnit !== displayTempUnit) {
        const prev = _plotsTempUnit;
        _plotsTempUnit = displayTempUnit;
        retargetTempPlotsForUnit(prev);
    }
    const fBtn = document.getElementById('tempUnitF_btn');
    const cBtn = document.getElementById('tempUnitC_btn');
    if (fBtn && cBtn) {                              // segmented-control active pill
        fBtn.classList.toggle('on', displayTempUnit === 0);
        cBtn.classList.toggle('on', displayTempUnit === 1);
    }
    if (typeof renderBattTempDerate === 'function') renderBattTempDerate();  // re-convert commission/battery temps
    if (typeof renderBattTempReadouts === 'function' && g_lastCsv2) renderBattTempReadouts(g_lastCsv2);
    if (typeof owRender === 'function' && _owLast) owRender(_owLast);
}

function setTempUnit(unit) {
    displayTempUnit = unit;
    updateAllTempUnitLabels();
    // buildURL is mandatory: a bare /get resolves to the app's own localhost origin under
    // Capacitor, so the write never lands and the next CSV3 echo snaps the pill back to °F.
    fetch(buildURL(`/get?displayTempUnit=${unit}`)).catch(() => {});
}

// Fuel volume unit preference — 0=US gallons (default), 1=litres. Echoed from CSV3.
// Display only: the fuel table stays GPH x100 on the wire and in NVS, and the used-fuel
// totals stay litres, exactly as the firmware accumulates them.
let displayVolUnit = 0;
const LITRES_PER_US_GAL = 3.785411784;

function toDisplayVol(litres) {            // used-fuel totals are litres-native
    return displayVolUnit === 1 ? litres : litres / LITRES_PER_US_GAL;
}
function gphToDisplayFlow(gph) {           // fuel table + live flow are gallons-native
    return displayVolUnit === 1 ? gph * LITRES_PER_US_GAL : gph;
}
function displayFlowToGph(v) {
    return displayVolUnit === 1 ? v / LITRES_PER_US_GAL : v;
}
function nmpgToDisplayEcon(nmpg) {         // nautical miles per gallon -> per litre
    return displayVolUnit === 1 ? nmpg / LITRES_PER_US_GAL : nmpg;
}
function volUnitLabel()     { return displayVolUnit === 1 ? 'L' : 'gal'; }
function volFlowUnitLabel() { return displayVolUnit === 1 ? 'L/hr' : 'gal/hr'; }
function volEconUnitLabel() { return displayVolUnit === 1 ? 'naut mi/L' : 'naut mi/gal'; }

let _fuelCurveVolUnit = 0;   // unit baked into the economy plot's axis label and data
function updateAllVolUnitLabels() {
    document.querySelectorAll('.fuelvol-unit-label').forEach(el => { el.textContent = volUnitLabel(); });
    document.querySelectorAll('.fuelflow-unit-label').forEach(el => { el.textContent = volFlowUnitLabel(); });
    document.querySelectorAll('.fuelecon-unit-label').forEach(el => { el.textContent = volEconUnitLabel(); });

    // The 200 gal/hr ceiling is authored in gallons; the browser validates what is typed.
    document.querySelectorAll('#fuel-table-body input[id^="fuelTableGPH"]').forEach(inp => {
        inp.max = displayVolUnit === 1 ? Math.ceil(200 * LITRES_PER_US_GAL) : 200;
    });

    const gBtn = document.getElementById('volUnitGal_btn');
    const lBtn = document.getElementById('volUnitL_btn');
    if (gBtn && lBtn) {
        gBtn.classList.toggle('on', displayVolUnit === 0);
        lBtn.classList.toggle('on', displayVolUnit === 1);
    }

    if (_fuelCurveVolUnit !== displayVolUnit) {
        const prev = _fuelCurveVolUnit;
        _fuelCurveVolUnit = displayVolUnit;
        // Axis label and y values are both unit-bearing, and uPlot bakes the label at
        // construction — tear the plot down so the next CSV4 frame rebuilds it.
        if (typeof window.fuelCurveOnUnitChange === 'function') window.fuelCurveOnUnitChange(prev);
    }

    refreshFuelTableDisplayValues();
}

function setVolUnit(unit) {
    displayVolUnit = unit;
    updateAllVolUnitLabels();
    // buildURL is mandatory under Capacitor — see setTempUnit.
    fetch(buildURL(`/get?displayVolUnit=${unit}`)).catch(() => {});
}

// The GPH cells hold display units but are submitted as gallons. _fuelGphShadow is the
// gallons truth for every cell, so a unit flip re-renders without a round trip to the device.
const _fuelGphShadow = new Array(10).fill(null);

function fuelSetCellFromGph(i, gph) {
    _fuelGphShadow[i] = gph;
    const el = document.getElementById(`fuelTableGPH${i}_input`);
    if (el) el.value = gphToDisplayFlow(gph).toFixed(2);
}

function refreshFuelTableDisplayValues() {
    for (let i = 0; i < 10; i++) {
        if (_fuelGphShadow[i] === null) continue;
        const el = document.getElementById(`fuelTableGPH${i}_input`);
        if (el && el !== document.activeElement) el.value = gphToDisplayFlow(_fuelGphShadow[i]).toFixed(2);
    }
    if (typeof drawFuelCurve === 'function') drawFuelCurve();
}

// Convert a form input value from display unit back to °F before GET submission.
// Temporarily rewrites the input value, lets the form submit, then restores the display value.
function convertTempFormIfNeeded(form, inputName, isDelta, zeroMeansOff) {
    if (displayTempUnit !== 1) return true;
    const input = form.querySelector(`[name="${inputName}"]`);
    if (!input) return true;
    const displayVal = parseFloat(input.value);
    if (isNaN(displayVal)) return true;
    if (zeroMeansOff && displayVal === 0) return true;  // 0 = firmware disable sentinel, never a temperature
    const nativeVal = isDelta
        ? (displayVal * 9 / 5)           // delta: °C span → °F span
        : (displayVal * 9 / 5 + 32);     // absolute: °C → °F
    input.value = Math.round(nativeVal * 10) / 10;  // round to 1 decimal
    // Restore on the next tick — the browser serializes the form synchronously right after this
    // handler returns; a longer window let a second Set re-convert the visible °F value as °C.
    const originalDisplay = String(displayVal);
    setTimeout(() => { input.value = originalDisplay; }, 0);
    return true;
}

// capTempRef is the one °C-native setting (capTempRefC in firmware) — the mirror of the two
// helpers above: convert °C→display for readouts, display→°C on submit when in °F mode.
function toDisplayTempFromC(val_c) {
    return displayTempUnit === 1 ? val_c : val_c * 9 / 5 + 32;
}
function convertTempFormCNative(form, inputName) {
    if (displayTempUnit === 1) return true;  // display already °C
    const input = form.querySelector(`[name="${inputName}"]`);
    if (!input) return true;
    const displayVal = parseFloat(input.value);
    if (isNaN(displayVal)) return true;
    input.value = Math.round((displayVal - 32) / 1.8 * 10) / 10;
    const originalDisplay = String(displayVal);
    setTimeout(() => { input.value = originalDisplay; }, 0);
    return true;
}

