function buildURL(path) {

    if (!path.startsWith('/')) {
        path = '/' + path;
    }
    return `${API_BASE_URL}${path}`;
}

// Capacitor serves the page from the app's own localhost origin, so a form's relative
// action (/get) submits to the app bundle server — the write never reaches the regulator,
// and the SPA fallback answers with index.html, booting a second app copy inside the
// hidden form-target iframe (stray SSE stream + duplicate location prompt). Point every
// device-bound form at the regulator's absolute base; re-run whenever discovery moves
// API_BASE_URL. Browsers are same-origin with the regulator and never need this.
function syncFormActionsToDevice() {
    if (!IS_CAPACITOR) return;
    document.querySelectorAll('form').forEach(f => {
        if (!f.dataset.devicePath) {
            const attr = f.getAttribute('action') || '';
            if (!attr.startsWith('/')) return;   // already absolute (built via buildURL) or empty
            f.dataset.devicePath = attr;
        }
        f.setAttribute('action', buildURL(f.dataset.devicePath));
    });
}
document.addEventListener('DOMContentLoaded', syncFormActionsToDevice);

// =====================================================================
// Device discovery — Capacitor only (mDNS name → subnet probe)
// =====================================================================
// The regulator answers GET /identify passwordless with
// {"device":"xreg-010",...} — built for this probe. Browsers never run
// discovery (same-origin page) and can't subnet-scan anyway; the Connection
// Lost dialog names that limitation instead of hiding it.

let discoveryInProgress = false;

function setSplashText(msg) {
    const wfr = document.getElementById('waiting-for-regulator');
    if (!wfr || wfr._wfrHidden) return;
    const t = wfr.querySelector('.bl-text');
    if (t) t.textContent = msg;
}

async function probeIdentify(base, timeoutMs) {
    // Plain setTimeout: a /24 sweep fires hundreds of these, so they must not
    // pile up in the activeTimers cleanup list.
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
        const resp = await fetch(base + '/identify', { signal: ctrl.signal, cache: 'no-store' });
        if (!resp.ok) return null;
        const info = await resp.json();
        if (!info || info.device !== 'xreg-010') return null;
        const str = v => (typeof v === 'string' && v) ? v : null;
        // uid is the identity everything downstream pins to. Firmware older than the two-unit
        // work answers without uid/name/host; those fields stay null and the app degrades to
        // its old address-only behaviour rather than refusing to connect.
        return {
            base: base,
            fw: str(info.fw),
            uid: str(info.uid),
            name: str(info.name),
            host: str(info.host),
            ap: str(info.ap)
        };
    } catch (e) {
        return null;
    } finally {
        clearTimeout(timer);
    }
}

// Probe a list in parallel and resolve with EVERY regulator that identified, not just the
// first. First-hit-wins is what let a second unit on the same LAN take the connection over
// silently: the winner was decided by a few ms of RTT and nothing downstream ever checked
// which board it was. wantUid short-circuits the wait — a pinned unit answering is never
// ambiguous, so the common single-regulator launch is as fast as it ever was.
const DISCOVERY_STRAGGLER_MS = 450;   // after the first answer, how long to keep listening for a second unit
const isIpBase = b => /^https?:\/\/\d{1,3}(\.\d{1,3}){3}/.test(b || '');

function probeRound(bases, timeoutMs, wantUid) {
    return new Promise((resolve) => {
        let pending = bases.length;
        const hits = [];
        let done = false, straggler = null;
        if (!pending) { resolve(hits); return; }
        const finish = () => {
            if (done) return;
            done = true;
            if (straggler) clearTimeout(straggler);
            resolve(hits);
        };
        bases.forEach(base => {
            probeIdentify(base, timeoutMs).then(hit => {
                if (hit) {
                    // One unit answers on several bases (its mDNS name, its IP, the remembered
                    // base). Fold them by uid, and keep the numeric address: a .local name can
                    // resolve to the OTHER regulator, an IP cannot.
                    const dup = hit.uid ? hits.find(h => h.uid === hit.uid) : null;
                    if (dup) {
                        if (isIpBase(hit.base) && !isIpBase(dup.base)) dup.base = hit.base;
                    } else {
                        hits.push(hit);
                        if (wantUid && hit.uid === wantUid) { finish(); return; }
                        if (!straggler) straggler = setTimeout(finish, DISCOVERY_STRAGGLER_MS);
                    }
                }
                if (--pending === 0) finish();
            });
        });
    });
}

async function getPhoneIPv4() {
    const plugin = IS_CAPACITOR && window.Capacitor.Plugins && window.Capacitor.Plugins.CapacitorWifi;
    if (!plugin || !plugin.getIpAddress) return null;
    try {
        const r = await plugin.getIpAddress();
        const ip = r && r.ipAddress;
        // The plugin reads en0 only and returns the FIRST address family it finds,
        // which can be IPv6 — only a dotted-quad can seed a /24 sweep.
        return (typeof ip === 'string' && /^\d{1,3}(\.\d{1,3}){3}$/.test(ip)) ? ip : null;
    } catch (e) {
        return null;
    }
}

// ── Android network helpers (XEngNet native plugin) ─────────────────────────
// Android-only; absent on iOS and in browsers, where both calls are no-ops.
// bindWifi(): Android keeps routing app traffic to cellular when the joined WiFi has no
// internet (the regulator's AP never does), while still showing WiFi connected — every
// request then leaves the phone and fails. This pins this app's sockets to the WiFi net.
async function bindWifiNetwork() {
    const P = IS_CAPACITOR && window.Capacitor.Plugins && window.Capacitor.Plugins.XEngNet;
    if (!P || !P.bindWifi) return false;
    try { const r = await P.bindWifi(); return !!(r && r.bound); } catch (e) { return false; }
}

// Android's resolver generally will not answer .local, so the native side does the mDNS
// query and hands back an address to probe instead. Rejection = fall through unchanged.
// Android only, and only in an app built since the two-regulator work: one mDNS browse returns
// every regulator by its own per-unit name. Beats asking for a shared name that either unit can
// answer to. Absent plugin or older APK → empty list, and discovery falls through to the probes
// exactly as it did before.
async function browseRegulatorHosts() {
    const P = IS_CAPACITOR && window.Capacitor.Plugins && window.Capacitor.Plugins.XEngNet;
    if (!P || !P.browseRegulators) return [];
    try {
        const r = await P.browseRegulators();
        return (r && Array.isArray(r.units)) ? r.units : [];
    } catch (e) {
        return [];
    }
}

async function resolveLocalHost(host) {
    const P = IS_CAPACITOR && window.Capacitor.Plugins && window.Capacitor.Plugins.XEngNet;
    if (!P || !P.resolveLocal) return null;
    try { const r = await P.resolveLocal({ host: host }); return (r && r.ip) || null; } catch (e) { return null; }
}

// Returns EVERY regulator that answered, so the caller can pin one instead of taking whichever
// replied first. wantUid (the remembered unit) ends a round early and keeps the LAN sweep going
// past a batch that only found its neighbour.
async function discoverDeviceBase(wantUid, exhaustive) {
    await bindWifiNetwork();   // every discovery path lands here — bind before the first probe
    // Round 1: mDNS name, the regulator's own access-point gateway, and the last
    // address that worked, all probed in parallel — extra candidates cost no time.
    // 192.168.4.1 is fixed by the firmware's softAP, so an AP-mode phone lands on
    // the device in round 1 instead of falling through to the /24 sweep. In WiFi
    // CONFIG mode that address serves the setup portal, which has no /identify, so
    // the probe misses and the hotspot hint banner still wins that case.
    // A pinned unit's own mDNS name is tried FIRST and resolves past the alternator.local
    // race entirely: two regulators both answer to alternator.local, only one answers to
    // xreg-<uid6>.local.
    const first = [];
    const wantHost = localStorage.getItem('xregDeviceHost');
    if (wantUid && wantHost) {
        const ownIp = await resolveLocalHost(wantHost);
        first.push(ownIp ? 'http://' + ownIp : 'http://' + wantHost);
    }
    // Android: every unit, by name, in one browse — so a two-regulator boat is seen as two in
    // round 1 rather than discovered one batch at a time in the LAN sweep.
    (await browseRegulatorHosts()).forEach(u => {
        const b = u && u.ip ? 'http://' + u.ip : (u && u.host ? 'http://' + u.host : null);
        if (b && first.indexOf(b) === -1) first.push(b);
    });
    const mdnsIP = await resolveLocalHost('alternator.local');
    first.push(mdnsIP ? 'http://' + mdnsIP : 'http://alternator.local', 'http://192.168.4.1');
    const last = localStorage.getItem('xregDeviceBase');
    if (last && first.indexOf(last) === -1) first.push(last);
    const found = [];
    const merge = list => list.forEach(h => {
        const dup = h.uid ? found.find(f => f.uid === h.uid) : null;
        if (dup) { if (isIpBase(h.base) && !isIpBase(dup.base)) dup.base = h.base; }
        else found.push(h);
    });
    // exhaustive (Switch Regulator): every round runs to its end and no probe stops on the pinned
    // unit — the point is the list, not the first answer. Otherwise a pinned unit ends the search the
    // moment it answers, and an unpinned launch takes the first unit that does.
    const probeUid = exhaustive ? null : wantUid;
    const settled = () => !exhaustive && (wantUid ? found.some(h => h.uid === wantUid) : found.length > 0);
    merge(await probeRound(first, 2500, probeUid));
    if (settled()) return found;

    setSplashText('Searching for regulator');

    // Round 2: iPhone-hotspot subnet — DHCP hands clients 172.20.10.2–.14.
    // Deliberately NOT gated on the phone's own IP: the wifi plugin reads en0
    // only, which carries no IPv4 while this phone is HOSTING the hotspot
    // (the hotspot side lives on ap1/bridge interfaces).
    const hotspot = [];
    for (let h = 2; h <= 14; h++) hotspot.push('http://172.20.10.' + h);
    merge(await probeRound(hotspot, 1500, probeUid));
    if (settled()) return found;

    // Round 3: router LAN — needs our own IPv4 to pick the /24. ~11 s worst case.
    const ownIP = await getPhoneIPv4();
    console.log('[DISCOVERY] phone IPv4: ' + (ownIP || 'unavailable'));
    if (!ownIP || ownIP.indexOf('172.20.10.') === 0) return found;
    const prefix = ownIP.slice(0, ownIP.lastIndexOf('.') + 1);
    for (let start = 1; start <= 254; start += 25) {
        const batch = [];
        for (let h = start; h < start + 25 && h <= 254; h++) {
            const cand = prefix + h;
            if (cand !== ownIP) batch.push('http://' + cand);
        }
        merge(await probeRound(batch, 1000, probeUid));
        // A pinned unit keeps the sweep running past a batch that only held its neighbour.
        if (settled()) return found;
    }
    return found;
}


// ── Which regulator are we talking to? ──────────────────────────────────────────────
// The address is not the identity: DHCP moves it, and alternator.local can resolve to a
// different board between one launch and the next. The uid from /identify is the identity,
// and it is what gets remembered.

function rememberedUid() { return localStorage.getItem('xregDeviceUid') || null; }

function unitWhere(hit) {
    return (hit && (hit.host || (hit.base || '').replace(/^https?:\/\//, ''))) || '';
}
function unitLabel(hit) {
    return (hit && hit.name) || 'Regulator';
}

// Everything the UI needs to say WHICH unit this is. Called on every connect, in the app and
// in a browser, so a wrong-regulator session is visible instead of silent.
function applyConnectedIdentity(hit) {
    if (!hit) return;
    window.xregUnit = hit;
    if (hit.name) localStorage.setItem('xregDeviceName', hit.name);
    // The AP SSID is per-unit now, so the Join button has to learn it from the device it is
    // actually connected to. A name the user typed themselves still wins (xregApSsid).
    if (hit.ap) localStorage.setItem('xregApSsidDev', hit.ap);
    const where = unitWhere(hit), label = unitLabel(hit);
    document.querySelectorAll('.conn-dot').forEach(d => {
        d.title = where ? label + ' \u2014 ' + where : label;
    });
    const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    set('unitNameOut', label);
    set('unitUidOut', hit.uid || '\u2014');
    set('unitAddrOut', where || '\u2014');
    const apEl = document.getElementById('regApSsid');
    if (apEl && !localStorage.getItem('xregApSsid') && hit.ap) apEl.value = hit.ap;
}

function connectToRegulator(hit) {
    console.log('[DISCOVERY] regulator ' + (hit.uid || 'unknown-uid') + ' at ' + hit.base + ' (fw ' + (hit.fw || 'unknown') + ')');
    API_BASE_URL = hit.base;
    localStorage.setItem('xregDeviceBase', hit.base);
    if (hit.uid) localStorage.setItem('xregDeviceUid', hit.uid);
    if (hit.host) localStorage.setItem('xregDeviceHost', hit.host);
    syncFormActionsToDevice();
    sseReconnectAttempts = 0;
    setSplashText('Connecting to regulator');
    lastDiscoveredFw = hit.fw;
    lastDiscoveredBase = hit.base;
    applyConnectedIdentity(hit);
    matchAppBundleToDevice(hit.fw, hit.base);
}

// One unit, or the one we already use → connect. Anything else is a question for the user:
// picking silently is the bug this whole path exists to fix.
async function resolveRegulatorChoice(hits, wantUid) {
    if (!hits.length) return null;
    if (wantUid) {
        const mine = hits.find(h => h.uid === wantUid);
        if (mine) return mine;
    }
    // Pre-identity firmware answers with no uid at all; there is nothing to disambiguate with,
    // so keep the old behaviour rather than trapping the user behind an unanswerable dialog.
    if (hits.length === 1 && (!wantUid || !hits[0].uid)) return hits[0];
    return await chooseRegulator(hits, wantUid);
}

// Picker. Resolves with the chosen hit, or null if dismissed.
function chooseRegulator(hits, wantUid, forced) {
    return new Promise((resolve) => {
        // A picker already up belongs to an earlier caller: settle it with null rather than orphan its await.
        const old = document.getElementById('regPickerDialog');
        if (old) { if (old._dismiss) old._dismiss(); else old.remove(); }
        const missing = wantUid && !hits.some(h => h.uid === wantUid);
        const lastName = localStorage.getItem('xregDeviceName');
        let lead;
        if (forced) lead = 'Choose which regulator this app should use.';
        else if (missing) lead = 'The regulator this app was using' + (lastName ? ' (' + lastName + ')' : '') +
            ' did not answer. These did:';
        else lead = 'More than one regulator answered on this network. Choose the one this app should use.';

        const rows = hits.map((h, i) => {
            const isCur = h.uid && h.uid === wantUid;
            return '<button data-idx="' + i + '" class="reg-pick-row" style="display:block; width:100%; text-align:left; background:#2a2a2a; border:1px solid ' +
                (isCur ? '#35d6c7' : '#484848') + '; color:#ddd; border-radius:6px; padding:10px 12px; margin-bottom:8px; cursor:pointer; font-size:13px;">' +
                '<span style="font-weight:600; color:#fff;"></span>' +
                '<span style="display:block; color:#8a8a8a; font-size:11px; margin-top:3px;"></span></button>';
        }).join('');

        const div = document.createElement('div');
        div.id = 'regPickerDialog';
        div.innerHTML = '<div id="regPickBackdrop" style="position:fixed; inset:0; background:rgba(0,0,0,0.55); z-index:10001; display:flex; align-items:center; justify-content:center;">' +
            '<div style="background:#1e1e1e; color:#ddd; width:430px; max-width:calc(100vw - 40px); border-radius:8px; box-shadow:0 6px 32px rgba(0,0,0,0.8); border:1px solid #444; box-sizing:border-box;">' +
            '<div style="padding:10px 16px 9px; border-bottom:1px solid #333; background:#252525; border-radius:8px 8px 0 0; font-weight:600; font-size:13px; color:#aaa; letter-spacing:0.03em; display:flex; align-items:center; justify-content:space-between;">' +
            '<span>Choose Regulator</span>' +
            '<button id="regPickClose" type="button" aria-label="Close" style="background:none; border:none; color:#888; cursor:pointer; font-size:18px; padding:0 4px; line-height:1;">&#10005;</button></div>' +
            '<div style="padding:16px 18px 18px; font-size:0.92em; line-height:1.5;">' +
            '<p id="regPickLead" style="margin:0 0 12px; color:#bbb;"></p>' +
            '<div id="regPickRows">' + rows + '</div>' +
            '<p style="font-size:11px; color:#777; margin:10px 0 0;">The app remembers this unit and reconnects to it by identity, not by address, so a new IP or a second regulator on the network cannot swap it out.</p>' +
            '<div style="display:flex; justify-content:flex-end; margin-top:12px;">' +
            '<button id="regPickCancel" type="button" style="background:#3a3a3a; border:1px solid #555; color:#ddd; border-radius:6px; padding:8px 16px; cursor:pointer; font-size:0.9em;">Not now</button></div>' +
            '</div></div></div>';
        document.body.appendChild(div);
        // Every exit — a row, the X, Not now, the backdrop, Escape, or a newer picker — goes through
        // finish(), so the promise always settles and the key listener never outlives the dialog.
        let settled = false;
        const onKey = (e) => { if (e.key === 'Escape') finish(null); };
        const finish = (h) => {
            if (settled) return;
            settled = true;
            document.removeEventListener('keydown', onKey);
            div.remove();
            resolve(h);
        };
        div._dismiss = () => finish(null);
        document.addEventListener('keydown', onKey);
        div.querySelector('#regPickClose').onclick = () => finish(null);
        div.querySelector('#regPickCancel').onclick = () => finish(null);
        const backdrop = div.querySelector('#regPickBackdrop');
        backdrop.addEventListener('click', e => { if (e.target === backdrop) finish(null); });
        // Device-supplied text goes in with textContent — a unit name is user input.
        div.querySelector('#regPickLead').textContent = lead;
        div.querySelectorAll('.reg-pick-row').forEach(btn => {
            const h = hits[Number(btn.dataset.idx)];
            const spans = btn.querySelectorAll('span');
            spans[0].textContent = unitLabel(h) + (h.uid && h.uid === wantUid ? '  (current)' : '');
            spans[1].textContent = [unitWhere(h), h.uid ? 'ID ' + h.uid.slice(-6) : '', h.fw ? 'fw ' + h.fw : '']
                .filter(Boolean).join('  ·  ');
            btn.onclick = () => finish(h);
        });
    });
}

// Explicit "I want the other one". Always asks, even when the remembered unit answered.
async function switchRegulator() {
    if (discoveryInProgress) return;
    if (!IS_CAPACITOR) {
        xAlert('In a browser the regulator is whatever address you opened. Browse to the other unit directly \u2014 each one answers at its own xreg-<id>.local address, shown under Setup \u25b8 System on that unit.', 'Switch Regulator');
        return;
    }
    discoveryInProgress = true;
    // The only feedback on the settings page while the full sweep runs (up to ~15 s on a router LAN).
    const btn = document.querySelector('button[onclick="switchRegulator()"]');
    const btnLabel = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'Scanning...'; }
    let hits = [];
    setSplashText('Searching for regulators');
    try { hits = await discoverDeviceBase(rememberedUid(), true); }
    finally { discoveryInProgress = false; if (btn) { btn.disabled = false; btn.textContent = btnLabel; } }
    if (!hits.length) { xAlert('No regulator answered on this network.', 'Switch Regulator'); return; }
    const hit = await chooseRegulator(hits, rememberedUid(), true);
    if (!hit) return;
    connectToRegulator(hit);
    initializeEventSource();
}

// Browsers do not discover — the address bar picked the unit. Ask it who it is anyway, so the
// UI can name it and the AP fields are right for THIS board.
async function initUnitIdentity() {
    if (IS_CAPACITOR || DEMO_MODE) return;
    const hit = await probeIdentify(API_BASE_URL || '', 4000);
    if (hit) applyConnectedIdentity(hit);
}
document.addEventListener('DOMContentLoaded', initUnitIdentity);

// Resolve where the regulator is, then open SSE. Browsers connect directly
// (same-origin). Called at launch and from manualReconnect().
async function discoverAndConnect() {
    if (!IS_CAPACITOR || DEMO_MODE) { initializeEventSource(); return; }
    if (discoveryInProgress) return;
    discoveryInProgress = true;
    try {
        const hits = await discoverDeviceBase(rememberedUid());
        const hit = await resolveRegulatorChoice(hits, rememberedUid());
        if (hit) connectToRegulator(hit);
        else if (hits.length) console.log('[DISCOVERY] ' + hits.length + ' regulators answered, none chosen');
        else console.log('[DISCOVERY] no regulator found');
    } finally {
        discoveryInProgress = false;
    }
    // Connect even after a failed scan: SSE retries keep running and the
    // demo-mode / Connection-Lost paths take over from there.
    initializeEventSource();
}

// SSE exhausted its retries: expected after a hotspot bounce (new IP), so
// re-scan once before surrendering to the Connection Lost dialog. The
// _rediscoveryTried latch (cleared on SSE open / foreground / manual retry)
// bounds this to one scan per loss so a half-dead link can't loop forever.
// quiet=true suppresses the Connection Lost dialog on failure — used by the
// network-change watcher, which fires before the app has ever had a packet (an
// App Review phone changing networks must still reach demo mode, not a dialog).
async function rediscoverAfterLoss(quiet) {
    if (discoveryInProgress || DEMO_MODE) return;
    discoveryInProgress = true;
    let hits = [];
    try {
        hits = await discoverDeviceBase(rememberedUid());
    } finally {
        discoveryInProgress = false;
    }
    if (DEMO_MODE) return;
    const hit = await resolveRegulatorChoice(hits, rememberedUid());
    if (hit) {
        connectToRegulator(hit);
        initializeEventSource();
        return hit;
    }
    console.log('[DISCOVERY] re-scan found nothing');
    if (!quiet) {
        showRecoveryOptions();
        const reconnectBtn = document.getElementById('reconnect-button');
        if (reconnectBtn) reconnectBtn.style.display = 'none';
    }
    return null;
}

// =====================================================================
// Join the regulator's own hotspot from inside the app — Capacitor only
// =====================================================================
// NEHotspotConfiguration (via @capgo/capacitor-wifi) asks iOS to join a named
// network; iOS shows its own one-time Join/Cancel alert and the join persists.
// Without it an access-point user has to leave the app for Settings > Wi-Fi.
// The AP name and password live only in the regulator's NVS and are never in the
// telemetry echo, so the app keeps its own copy: firmware defaults until edited.
const AP_SSID_DEFAULT = 'ALTERNATOR_WIFI';
const AP_PASS_DEFAULT = 'alternator123';

function wifiJoinPlugin() {
    const p = IS_CAPACITOR && window.Capacitor.Plugins && window.Capacitor.Plugins.CapacitorWifi;
    return (p && typeof p.connect === 'function') ? p : null;
}

function getRegulatorApCreds() {
    // Priority: what the user typed, then what THIS unit reported over /identify, then the
    // compile-time name. The firmware default is per-unit (ALTERNATOR_WIFI-<id>), so the bare
    // constant is a last resort that only fits a pre-identity build.
    return {
        ssid: (localStorage.getItem('xregApSsid') || localStorage.getItem('xregApSsidDev') || AP_SSID_DEFAULT).trim(),
        password: (localStorage.getItem('xregApPass') || AP_PASS_DEFAULT)
    };
}

function saveRegulatorApCreds() {
    const ssidEl = document.getElementById('regApSsid');
    const passEl = document.getElementById('regApPass');
    if (ssidEl) localStorage.setItem('xregApSsid', ssidEl.value.trim() || AP_SSID_DEFAULT);
    if (passEl) localStorage.setItem('xregApPass', passEl.value || AP_PASS_DEFAULT);
    setApJoinStatus('regApJoinStatus', 'Saved on this phone.');
}

function setApJoinStatus(elId, msg) {
    const el = document.getElementById(elId);
    if (el) el.textContent = msg;
}

// Join, then re-resolve the regulator. Discovery round 1 already probes
// 192.168.4.1, so the normal re-scan path finds it with no special casing.
async function joinRegulatorHotspot(statusElId) {
    const plugin = wifiJoinPlugin();
    if (!plugin) {
        setApJoinStatus(statusElId, 'Joining a network from inside the app needs the phone app.');
        return;
    }
    const creds = getRegulatorApCreds();
    if (!creds.ssid) {
        setApJoinStatus(statusElId, 'Enter the regulator hotspot name first.');
        return;
    }
    setApJoinStatus(statusElId, 'Asking this phone to join ' + creds.ssid + '…');
    try {
        await plugin.connect({ ssid: creds.ssid, password: creds.password });
    } catch (e) {
        const msg = (e && (e.message || e.errorMessage)) ? String(e.message || e.errorMessage) : String(e);
        // iOS rejects an apply() for the network it is already on; that is a success here.
        if (!/already/i.test(msg)) {
            setApJoinStatus(statusElId, /cancel|denied/i.test(msg)
                ? 'Join cancelled.'
                : 'Could not join ' + creds.ssid + ': ' + msg);
            return;
        }
    }
    // Demo mode is a deliberate hard latch — API_BASE_URL is severed to
    // demo.invalid and rediscoverAfterLoss() refuses to run — so it cannot be
    // unwound in place. Tapping this button IS an explicit "take me to the real
    // regulator", and a user who was never on its network is exactly who demo
    // mode catches, so reload: the fresh page life finds 192.168.4.1 in round 1.
    if (DEMO_MODE) {
        setApJoinStatus(statusElId, 'Joined ' + creds.ssid + '. Reloading to leave demo mode…');
        setTrackedTimeout(() => location.reload(), 2000);
        return;
    }
    setApJoinStatus(statusElId, 'Joined ' + creds.ssid + '. Looking for the regulator…');
    // The association needs a moment before the interface will route. If the
    // network-change watcher already started a scan, let it finish first —
    // rediscoverAfterLoss() no-ops while one is in flight and would report a
    // false miss.
    await new Promise(r => setTrackedTimeout(r, 1500));
    for (let i = 0; i < 30 && discoveryInProgress; i++) {
        await new Promise(r => setTrackedTimeout(r, 500));
    }
    // Data actually flowing right now — readyState alone lies after an iOS network
    // switch, so the freshness test is the real check (same rule as visibilitychange).
    if (source && source.readyState === EventSource.OPEN && (Date.now() - lastEventTime) < 5000) {
        setApJoinStatus(statusElId, 'Connected to the regulator at ' + API_BASE_URL + '.');
        closeRecovery();
        return;
    }
    sseReconnectAttempts = 0;
    sseConnectingErrors = 0;
    window._rediscoveryTried = false;
    if (source) { source.close(); source = null; }
    const hit = await rediscoverAfterLoss(true);   // quiet: this button owns the messaging
    if (hit) {
        setApJoinStatus(statusElId, 'Connected to the regulator at ' + hit.base + '.');
        closeRecovery();
    } else {
        setApJoinStatus(statusElId, 'On ' + creds.ssid + ', but the regulator did not answer. Check that it is powered and running in access-point mode.');
    }
}

// Reveal the app-only hotspot card and seed it from what this phone remembers.
function initRegulatorApUi() {
    const card = document.getElementById('regApCard');
    if (!card) return;
    if (!wifiJoinPlugin()) return;      // browsers cannot join a network; card stays hidden
    card.style.display = '';
    const creds = getRegulatorApCreds();
    const ssidEl = document.getElementById('regApSsid');
    const passEl = document.getElementById('regApPass');
    if (ssidEl) ssidEl.value = creds.ssid;
    if (passEl) passEl.value = creds.password;
}
document.addEventListener('DOMContentLoaded', initRegulatorApUi);

// =====================================================================
// Network-change watch — Capacitor only (@capacitor/network)
// =====================================================================
// Without it the app learns a WiFi switch only after SSE burns its retry budget:
// ~20 s of dead stream before rediscovery fires. The plugin reports the change
// immediately, so joining the regulator's hotspot (or walking off the boat's
// network onto cellular) is acted on at once instead of waited out.
let lastNetStatus = null;

async function bindNetworkStatusWatch() {
    const plugin = IS_CAPACITOR && window.Capacitor.Plugins && window.Capacitor.Plugins.Network;
    if (!plugin || !plugin.addListener) return;
    try { lastNetStatus = await plugin.getStatus(); } catch (e) { lastNetStatus = null; }
    plugin.addListener('networkStatusChange', async (status) => {
        const was = lastNetStatus;
        lastNetStatus = status;
        if (DEMO_MODE || isOfflineMode) return;
        if (!status.connected) {
            console.log('[NETWORK] phone lost its connection');
            updateInlineStatus(false);
            return;
        }
        await bindWifiNetwork();   // a new WiFi net needs a fresh bind before anything is probed
        // A blip that lands back on the same network usually heals itself; only
        // a genuine change, or a stream that is already dead, is worth a re-scan.
        const changed = !was || !was.connected || was.connectionType !== status.connectionType;
        const dead = !source || source.readyState !== EventSource.OPEN || (Date.now() - lastEventTime > 5000);
        if (!changed && !dead) return;
        if (discoveryInProgress) return;
        console.log('[NETWORK] now on ' + status.connectionType + ' - re-scanning for the regulator');
        sseReconnectAttempts = 0;
        sseConnectingErrors = 0;
        window._rediscoveryTried = false;
        if (source) { source.close(); source = null; }
        rediscoverAfterLoss(!window._firstCsvPacketReceived);
    });
}
document.addEventListener('DOMContentLoaded', bindNetworkStatusWatch);

// True when the phone itself reports no connection — the Connection Lost dialog
// says that instead of blaming the regulator.
function phoneIsOffline() {
    return !!(lastNetStatus && lastNetStatus.connected === false);
}

// Match-on-connect: make the app's stored interface identical to the one the connected
// regulator serves. The regulator is the source of truth — it holds the byte-exact bundle for
// its own firmware and serves it over the link the app is already on, so this works in AP mode
// and offshore with no internet. The signed OTA zip (web_<fw>.zip) is only the fallback when the
// device pull fails. Content is compared by hash on the native side, so a re-flashed device
// carrying the same version number with different files still syncs. A staged bundle is applied
// in place (applyDownloaded re-points the WebView, then location.reload() — nothing here relies
// on a cold relaunch). Keyed per firmware string, not once per launch, so a firmware update taken
// mid-session syncs on reconnect too.
let webBundleMatchedFw = null;      // fw string already reconciled (or given up on) this page load
let webBundleSyncRunning = false;
let lastDiscoveredFw = null;
let lastDiscoveredBase = null;
const WEB_APPLY_STAMP_KEY = 'xregWebApplyStamp';
const WEB_APPLY_LOOP_GUARD_MS = 120000;

async function matchAppBundleToDevice(fw, base) {
    if (!IS_CAPACITOR || DEMO_MODE) return;
    if (typeof fw !== 'string' || !/^\d+\.\d+\.\d+$/.test(fw)) return;
    if (webBundleMatchedFw === fw || webBundleSyncRunning) return;
    const plugin = window.Capacitor.Plugins && window.Capacitor.Plugins.LiveUpdate;
    if (!plugin || !plugin.getCurrentVersion) return;
    if (!base) base = lastDiscoveredBase || API_BASE_URL;
    localStorage.removeItem('xregPendingWebVersion');   // pre-08-28 key, no longer consulted
    webBundleSyncRunning = true;
    let outcome = null;   // 'ready' = pending bundle waiting, 'unchanged', 'failed'
    try {
        if (plugin.syncFromDevice && base && /^https?:\/\//.test(base)) {
            try {
                const r = await plugin.syncFromDevice({ version: fw, base: base });
                outcome = (r && r.applyReady) ? 'ready' : 'unchanged';
                console.log('[LiveUpdate] Device sync ' + fw + ': ' + (r ? r.status : '?') + (r && r.isActive ? ' (active)' : ''));
            } catch (err) {
                console.log('[LiveUpdate] Device pull failed (' + (err && err.message ? err.message : err) + ') — trying OTA');
            }
        }
        if (outcome === null) {
            const cur = await plugin.getCurrentVersion();
            if (cur && !cur.isBundled && cur.version === fw) {
                outcome = 'unchanged';
            } else if (plugin.downloadVersion) {
                console.log('[LiveUpdate] Active interface ' + (cur ? cur.version : 'unknown') + ', device fw ' + fw + ' — downloading matching bundle from OTA');
                await plugin.downloadVersion({ version: fw });
                outcome = 'ready';
            } else {
                outcome = 'failed';
            }
        }
    } catch (err) {
        outcome = 'failed';
        console.log('[LiveUpdate] Match-on-connect failed (non-fatal): ' + (err && err.message ? err.message : err));
    } finally {
        webBundleSyncRunning = false;
    }
    webBundleMatchedFw = fw;   // failures too: no automatic hammering; the mismatch dialog's Sync button clears this
    if (outcome === 'ready') {
        await applyWebBundleNow(fw);
        return;
    }
    if (outcome === 'unchanged') localStorage.removeItem(WEB_APPLY_STAMP_KEY);
    flushDeferredSchemaMismatch();
}

// Promote the pending bundle and reload onto it. The stamp is a reload-loop guard: if this same
// version was applied moments ago and a sync is asking again, something is wrong with the
// comparison and the page must not bounce forever — fall back to the relaunch banner instead.
async function applyWebBundleNow(fw) {
    const plugin = window.Capacitor.Plugins && window.Capacitor.Plugins.LiveUpdate;
    let stamp = null;
    try { stamp = JSON.parse(localStorage.getItem(WEB_APPLY_STAMP_KEY) || 'null'); } catch (e) { stamp = null; }
    if (stamp && stamp.version === fw && (Date.now() - stamp.ts) < WEB_APPLY_LOOP_GUARD_MS) {
        console.log('[LiveUpdate] ' + fw + ' was applied ' + Math.round((Date.now() - stamp.ts) / 1000) + 's ago and is being staged again — not reloading');
        showWebMatchBanner(fw);
        flushDeferredSchemaMismatch();
        return;
    }
    try {
        localStorage.setItem(WEB_APPLY_STAMP_KEY, JSON.stringify({ version: fw, ts: Date.now() }));
        setSplashText('Updating interface to match regulator');
        await plugin.applyDownloaded();
        console.log('[LiveUpdate] Applied ' + fw + ' — reloading');
        location.reload();
    } catch (err) {
        console.log('[LiveUpdate] Apply failed (' + (err && err.message ? err.message : err) + ') — relaunch will apply');
        showWebMatchBanner(fw);
        flushDeferredSchemaMismatch();
    }
}

function retryWebBundleSync() {
    webBundleMatchedFw = null;
    const fw = lastDiscoveredFw || document.getElementById('current-version-display').textContent.trim();
    matchAppBundleToDevice(fw, lastDiscoveredBase || API_BASE_URL);
}

function showWebMatchBanner(fw) {
    if (document.getElementById('web-match-banner')) return;
    const banner = document.createElement('div');
    banner.id = 'web-match-banner';
    banner.style.cssText = 'position:fixed;top:0;left:0;right:0;background:#0a84ff;color:#fff;padding:calc(12px + env(safe-area-inset-top)) 44px 12px 14px;text-align:center;z-index:10000;font-weight:600;font-size:14px;line-height:1.45;';
    banner.textContent = 'Interface version ' + fw + ' is ready to match your regulator — close and reopen the app to apply.';
    const close = document.createElement('button');
    close.textContent = '×';
    close.setAttribute('aria-label', 'Dismiss');
    close.style.cssText = 'position:absolute;top:calc(8px + env(safe-area-inset-top));right:6px;width:34px;height:34px;background:none;border:none;color:#fff;font-size:22px;line-height:34px;padding:0;';
    close.onclick = () => { banner.remove(); document.body.style.paddingTop = ''; };
    banner.appendChild(close);
    document.body.insertBefore(banner, document.body.firstChild);
    document.body.style.paddingTop = 'calc(72px + env(safe-area-inset-top))';
}

// Interface/firmware skew notice. Every positional CSV channel hard-drops frames whose field
// count differs from this build's array, so a version gap shows as blank gauges and dead settings
// echoes under a green connection — this dialog is the only thing that says why. Once per page
// load. In the app it holds until the bundle sync settles, because the sync normally closes the
// gap by reloading before anyone would see it.
let schemaMismatchInfo = null;
let schemaMismatchShown = false;

function noteSchemaMismatch(channel, declared, expected) {
    if (DEMO_MODE || schemaMismatchShown) return;
    if (!schemaMismatchInfo) schemaMismatchInfo = { channel: channel, declared: declared, expected: expected };
    if (IS_CAPACITOR && (webBundleSyncRunning || (lastDiscoveredFw && webBundleMatchedFw !== lastDiscoveredFw))) return;
    showSchemaMismatchDialog();
}

function flushDeferredSchemaMismatch() {
    if (schemaMismatchInfo && !schemaMismatchShown) showSchemaMismatchDialog();
}

function showSchemaMismatchDialog() {
    if (schemaMismatchShown) return;
    schemaMismatchShown = true;
    const info = schemaMismatchInfo || {};
    const detail = info.channel
        ? `\n\nTelemetry channel ${String(info.channel).toUpperCase()}: the regulator sends ${info.declared} fields, this interface expects ${info.expected}.`
        : '';
    console.log('[UI] Interface mismatch dialog shown' + detail.replace(/\n+/g, ' '));
    if (IS_CAPACITOR) {
        xConfirm(`This app's interface does not match the regulator's firmware, so some readings and settings will stay blank. The app normally copies the matching interface from the regulator when it connects; that has not happened yet.${detail}`,
            { title: 'Interface Out of Date', okText: 'Sync Interface', cancelText: 'Not Now' })
            .then(ok => { if (ok) retryWebBundleSync(); });
    } else {
        xConfirm(`This page was loaded from a different version of the regulator's interface than the firmware now running, so some readings and settings will stay blank. Reload the page to get the matching interface.${detail}`,
            { title: 'Interface Out of Date', okText: 'Reload Page', cancelText: 'Not Now' })
            .then(ok => { if (ok) location.reload(); });
    }
}

// =====================================================================
// Phone GPS + time backup poster
// =====================================================================
// When the boat's NMEA2K GPS is unavailable (transducer fault, bus issue,
// or just not installed), the device falls back to phone-provided location
// and time (POST every 60s; firmware ignores it while NMEA is fresh). Speed
// and course are different: never a fallback — they come from the phone only
// when the user selects it (speedSourceMode), which switches this client to a
// continuous GNSS watch posting every ~2 s. See /set_phone_data handler in
// 3_functions.ino and consumePhoneGps() / applyPhoneSpeed() /
// syncTimeFromPhone().

const PHONE_DATA_POST_INTERVAL_MS = 60000;  // every 60 sec when foregrounded
let phoneDataPosterTimer = null;

async function getPhoneLocation() {
    // Returns { latitude, longitude } or null. Works in both browser
    // (navigator.geolocation) and Capacitor (Geolocation plugin).
    if (IS_CAPACITOR) {
        if (window.Capacitor.Plugins && window.Capacitor.Plugins.Geolocation) {
            try {
                const pos = await window.Capacitor.Plugins.Geolocation.getCurrentPosition({
                    enableHighAccuracy: true,
                    timeout: 10000,
                    maximumAge: 60000
                });
                // speed (m/s) and heading (deg) ride along when the GNSS fix has them:
                // iOS reports -1 for "not determinable" (stationary), browsers report null.
                return { latitude: pos.coords.latitude, longitude: pos.coords.longitude,
                         speed: pos.coords.speed, heading: pos.coords.heading };
            } catch (e) {
                console.warn('[PhoneGPS] Capacitor Geolocation failed:', e && e.message);
                return null;
            }
        }
        // App build without the native Geolocation plugin: never fall through to
        // navigator.geolocation — WKWebView re-prompts "localhost would like to use your
        // location" on every page life. Location is a backup source; skip silently.
        return null;
    }
    if (typeof navigator !== 'undefined' && navigator.geolocation) {
        // Browser geolocation requires a secure context (HTTPS / localhost). The
        // ESP32 serves over plain HTTP on the LAN, so a desktop browser will always
        // be refused — skip the call (and the guaranteed console error) outright.
        // Capacitor uses the native plugin branch above and isn't affected.
        if (typeof window !== 'undefined' && window.isSecureContext === false) {
            diagLog('[PhoneGPS] insecure origin — skipping browser geolocation');
            return null;
        }
        return new Promise(resolve => {
            navigator.geolocation.getCurrentPosition(
                pos => resolve({ latitude: pos.coords.latitude, longitude: pos.coords.longitude,
                                 speed: pos.coords.speed, heading: pos.coords.heading }),
                err => { diagWarn('[PhoneGPS] navigator.geolocation failed:', err && err.message); resolve(null); },
                { enableHighAccuracy: true, timeout: 10000, maximumAge: 60000 }
            );
        });
    }
    return null;  // no geolocation API available
}

async function postPhoneFix(loc) {
    // Shared POST for both the 60 s poll and the fast speed watch. epochMs always rides
    // along (the device's primary clock on NMEA-less boats in AP mode).
    const params = new URLSearchParams();
    params.set('epochMs', String(Date.now()));
    if (loc) {
        params.set('lat', loc.latitude.toFixed(6));
        params.set('lon', loc.longitude.toFixed(6));
        // Speed/heading are optional per-fix: null and -1 both mean "not determinable"
        // (Number(null) is 0, so null must be screened before the numeric checks —
        // 0 is a REAL speed, at anchor). Unknown values are simply omitted.
        const spd = (loc.speed === null || loc.speed === undefined) ? NaN : Number(loc.speed);
        if (Number.isFinite(spd) && spd >= 0) params.set('spd', spd.toFixed(2));
        const hdg = (loc.heading === null || loc.heading === undefined) ? NaN : Number(loc.heading);
        if (Number.isFinite(hdg) && hdg >= 0 && hdg <= 360) params.set('hdg', hdg.toFixed(1));
    }
    try {
        await fetch(buildURL('/set_phone_data') + '?' + params.toString(), { method: 'GET' });
    } catch (e) {
        // Device unreachable — fine, we'll try again on the next tick.
    }
}

// The boat already knows where it is, so the phone has nothing to add. currentGpsSource
// rides CSV2: 1 = NMEA 2000 GPS live, 3 = coordinates the owner typed in Setup > Solar.
// Unknown (no CSV2 heard yet) counts as known — never read location on a guess.
function boatPositionAlreadyKnown() {
    const src = Number(window.currentGpsSource);
    if (!Number.isFinite(src)) return true;
    return src === 1 || src === 3;
}

// True when this phone's position is actually of use to the regulator right now. Backup is
// the DEFAULT (opted in), so this is normally true on a boat with no GPS of its own and
// false on a boat that has one — the phone is never read when the bus already answers the
// question. Selecting "NMEA 2000 only" is the opt-out and makes this false always.
function phonePositionWanted() {
    if (Number(window.speedSourceMode) === 1) return true;   // phone owns speed/course outright
    const src = Number(window.gpsPositionSource);
    if (src === 2) return true;                              // phone forced as the position source
    if (src === 0 && !boatPositionAlreadyKnown()) return true;  // backup, and the boat has nothing
    return false;                                            // NMEA 2000 only — owner opted out
}

// Ask for location, in context, at the moment the owner switches on a feature that needs
// it. Apple's HIG wants an explainer to carry ONE button that leads to the system alert —
// the decline belongs to iOS, not to us — so this is xAlert, not a confirm. Returns true
// only if authorization ended up granted. Keep the explainer SHORT: a purpose string long
// enough to overflow the system alert collapses it to a single "Allow Once" button
// (measured 2026-08-24: 517 chars fine, 556 collapses), and the same restraint applies here.
async function requestPhoneLocationPermission(whyLine) {
    if (!IS_CAPACITOR || !window.Capacitor.Plugins || !window.Capacitor.Plugins.Geolocation) return false;
    if (await phoneLocationGranted()) return true;
    try {
        const p = await window.Capacitor.Plugins.Geolocation.checkPermissions();
        if (p && p.location === 'denied') {
            const where = (window.Capacitor.getPlatform && window.Capacitor.getPlatform() === 'android')
                ? 'Android Settings > Apps > XREG-010 > Permissions > Location, then choose Allow'
                : 'iOS Settings > Privacy & Security > Location Services > XREG-010, then choose While Using the App';
            await xAlert('Location is turned off for XREG-010. Turn it on in ' + where + '.', 'Location is off');
            return false;
        }
    } catch (e) { /* services off system-wide — the request below will fail harmlessly */ }
    await xAlert(whyLine, 'Share this phone\'s position?', { okText: 'Continue' });
    try {
        const r = await window.Capacitor.Plugins.Geolocation.requestPermissions();
        return r && r.location === 'granted';
    } catch (e) {
        return false;
    }
}

// Defer to Solar reads the forecast for the boat's coordinates, so switching it on is the
// third and last thing that can need this phone's location — and only when the boat has no
// NMEA GPS of its own to supply them. Called from the toggle's onchange after it submits.
async function weatherModeToggled(isOn) {
    if (!isOn) return;
    if (boatPositionAlreadyKnown()) return;   // boat's own GPS (or typed coordinates) already answers this
    if (Number(window.gpsPositionSource) === 1) {
        // Owner opted the phone out of position entirely, so the forecast has no coordinates
        // to work from and would silently never run. Say so instead of asking for location.
        await xAlert('The solar forecast needs the boat\'s position, and this boat has no GPS ' +
                     'of its own. Set Setup > Boat > Position Source to use this phone as a ' +
                     'backup, or type coordinates in Setup > Solar.', 'No position available');
        return;
    }
    await requestPhoneLocationPermission(
        'The solar forecast is looked up for your position. XREG-010 can take it from this ' +
        'phone when the boat has no GPS of its own. It goes only to your regulator.');
}

// Backup position is on by default, so the app has to ask for authorization at some point.
// It asks HERE — the first time this phone actually reaches a regulator — and never at
// launch: at launch nothing has explained why, and a reviewer running the app with no
// hardware would meet an unexplained prompt before seeing the product. On this path a
// reviewer in demo mode never connects, so no prompt is ever raised for them.
// Fires once per install; the flag survives app restarts but not a delete.
async function maybeAskLocationOnFirstConnect() {
    if (!IS_CAPACITOR || DEMO_MODE) return;
    try { if (localStorage.getItem('locPermAsked') === '1') return; } catch (e) { return; }
    if (Number(window.gpsPositionSource) === 1) return;   // owner already chose NMEA 2000 only
    try { localStorage.setItem('locPermAsked', '1'); } catch (e) { }
    await requestPhoneLocationPermission(
        'XREG-010 can use this phone as a backup GPS for your boat, so distance run, ' +
        'anchorages and the solar forecast still work when the boat has no GPS of its own. ' +
        'Position goes to your regulator on your local network. You can turn this off under ' +
        'Setup > Boat > Position Source.');
}

// Position source selector. Both modes that can read this phone ask for authorization if it
// isn't already held; "NMEA 2000 only" is the opt-out and asks nothing. A refusal at the
// system alert reverts the dropdown rather than leaving a setting that cannot work.
// Capacitor only: the setting is DEVICE-global while the permission is THIS-client, so a plain
// browser (where requestPhoneLocationPermission returns false unconditionally) must still submit —
// otherwise a laptop can never select Backup or Phone, including switching back after an opt-out;
// the phone app aboard raises its own prompt when it actually starts posting.
async function gpsPositionSourceChanged(sel) {
    const v = Number(sel.value);
    if ((v === 0 || v === 2) && IS_CAPACITOR) {
        const ok = await requestPhoneLocationPermission(
            v === 2
              ? 'XREG-010 will use this phone as the boat\'s position source, ignoring NMEA 2000. ' +
                'Position goes to your regulator on your local network.'
              : 'XREG-010 will use this phone as a backup position source when the boat\'s own ' +
                'GPS is unavailable, so distance run, anchorages and the solar forecast keep working. ' +
                'Position goes to your regulator on your local network.');
        if (!ok) { sel.value = String(window.gpsPositionSource ?? 0); return; }
    }
    sel.form.submit();
    submitMessage();
}

// Authorization state WITHOUT prompting. Capacitor's checkPermissions() reads the state;
// getCurrentPosition() is what triggers the system alert when the state is notDetermined,
// so it must never be used as the test. Throws if Location Services are off system-wide.
async function phoneLocationGranted() {
    if (!IS_CAPACITOR || !window.Capacitor.Plugins || !window.Capacitor.Plugins.Geolocation) return false;
    try {
        const p = await window.Capacitor.Plugins.Geolocation.checkPermissions();
        return p && p.location === 'granted';
    } catch (e) {
        return false;   // services disabled, or the plugin can't answer — treat as no
    }
}

async function postPhoneDataToDevice() {
    // Time goes on every tick and needs no permission — in AP mode the phone is the only
    // clock the device has. Position rides along ONLY when the owner turned on a feature
    // that uses it AND authorization already exists; postPhoneFix(null) sends time alone.
    // Never call getPhoneLocation() before that check: it prompts.
    let loc = null;
    if (phonePositionWanted() && await phoneLocationGranted()) {
        loc = await getPhoneLocation();
    }
    await postPhoneFix(loc);
}

// ── Fast speed path ──
// When the user selects the phone as the speed/course source (speedSourceMode = 1, echoed
// on CSV3), a continuous GNSS watch replaces the 60 s poll for cadence: fixes stream in at
// ~1 Hz and post every PHONE_SPEED_POST_INTERVAL_MS, giving the device's record chain
// NMEA-like sample density (its sustained-speed window rejects gaps > 8 s). The 60 s
// poller keeps running for time/position backup; its extra posts are harmless. The watch
// stops the moment the mode leaves phone.
const PHONE_SPEED_POST_INTERVAL_MS = 2000;
let phoneSpeedWatchId = null;      // Capacitor CallbackID string or browser watch number; 'pending' while starting
let phoneSpeedWatchIsCap = false;
let phoneSpeedLastPostMs = 0;

function phoneSpeedWatchFix(pos) {
    if (!pos || !pos.coords) return;   // Capacitor delivers (null, err) on errors
    const nowMs = Date.now();
    if (nowMs - phoneSpeedLastPostMs < PHONE_SPEED_POST_INTERVAL_MS) return;
    phoneSpeedLastPostMs = nowMs;
    postPhoneFix({ latitude: pos.coords.latitude, longitude: pos.coords.longitude,
                   speed: pos.coords.speed, heading: pos.coords.heading });
}

// True when the app binary carries the BackgroundSpeed native plugin (build 17+):
// CLLocationManager + native posting that keeps speed flowing with the app backgrounded
// or the screen locked. Older binaries and browsers fall back to the JS foreground watch.
function phoneSpeedNativePlugin() {
    return (typeof IS_CAPACITOR !== 'undefined' && IS_CAPACITOR &&
            window.Capacitor.Plugins && window.Capacitor.Plugins.BackgroundSpeed) || null;
}
let phoneSpeedNativeActive = false;
let phoneSpeedNativeStopTried = false;   // false until this session has issued one unconditional bs.stop()
let speedNotifPermTried = false;         // one notification prompt per session, not one per CSV3 echo

// Tear down the JS fallback GNSS watch. Idempotent and safe with nothing running; the
// 'pending' case leaves null behind so the in-flight starter cancels its own orphan.
function stopPhoneSpeedJsWatch() {
    const id = phoneSpeedWatchId;
    if (id === null) return;
    phoneSpeedWatchId = null;
    if (id === 'pending') return;
    if (phoneSpeedWatchIsCap) {
        try { window.Capacitor.Plugins.Geolocation.clearWatch({ id: id }); } catch (e) { }
    } else {
        try { navigator.geolocation.clearWatch(id); } catch (e) { }
    }
}

// Text for the phone-speed dialog, shared by the selector and by the disclosure gate below
// so both say exactly the same thing. The first bullet reflects what THIS client can
// actually do: with the native BackgroundSpeed plugin the stream survives backgrounding;
// without it (older app binary, or a browser) it is foreground-only. The background
// sentence is fixed word-for-word by Google Play's prominent-disclosure rule — do not reword.
function phoneSpeedModeDialogText() {
    const runLine = phoneSpeedNativePlugin()
        ? '- XREG-010 collects location data to enable speed and course logging even when the app is closed or not in use. ' +
          'It keeps running for as long as the phone allows. Battery drain is substantial ' +
          'with GPS running full-time; keep the phone on a charger underway. The phone ' +
          'shows its location indicator while this is active.\n'
        : '- Works only while the app is open in the foreground on a phone aboard; ' +
          'speed greys out about 10 seconds after posting stops. Continuous GPS ' +
          'use increases phone battery drain.\n';
    return 'Speed and course will come from this phone instead of NMEA 2000.\n\n' +
        runLine +
        '- Speed records set in this mode are flagged in cloud uploads and are ' +
        'excluded from the speed leaderboard. If a phone-sourced run becomes your ' +
        'best ever, your boat stays off the board until an NMEA-sourced record beats it.';
}

const BG_SPEED_DISCLOSED_KEY = 'bgSpeedDisclosed';
let bgSpeedDisclosurePending = null;    // in-flight dialog — the CSV3 echo re-enters this every few seconds
let bgSpeedDisclosureDeclined = false;  // session-only, so a decline is not re-asked on every echo
function markPhoneSpeedDisclosed() { try { localStorage.setItem(BG_SPEED_DISCLOSED_KEY, '1'); } catch (e) { } }

// The disclosure must be shown before the first call that can start background location, and
// the speed source is a DEVICE setting: a laptop browser can turn it on for a phone that has
// never seen the dialog, so this phone shows it here before its own first native start.
// Declining leaves the foreground-only JS watch, which needs no such disclosure.
async function phoneSpeedBgDisclosed() {
    let seen = false;
    try { seen = localStorage.getItem(BG_SPEED_DISCLOSED_KEY) === '1'; } catch (e) { }
    if (seen) return true;
    if (bgSpeedDisclosureDeclined) return false;
    if (!bgSpeedDisclosurePending) {
        bgSpeedDisclosurePending = xConfirm(phoneSpeedModeDialogText(),
            { title: 'Use phone GPS for speed?', okText: 'Use Phone GPS' })
            .then(ok => {
                if (ok) markPhoneSpeedDisclosed(); else bgSpeedDisclosureDeclined = true;
                bgSpeedDisclosurePending = null;
                return ok;
            });
    }
    return bgSpeedDisclosurePending;
}

// Android 13+ posts nothing for a foreground service unless POST_NOTIFICATIONS is held: the
// speed stream still runs and GNSS still reads, but the shade stays empty, so the owner cannot
// see that their location is in use or stop it from there. Asked at the first native start
// rather than at launch, for the same reason the location prompt is. iOS has no equivalent
// permission and its plugin does not implement this method, so the call rejects and is swallowed.
async function ensureSpeedNotificationPermission() {
    if (speedNotifPermTried) return false;
    speedNotifPermTried = true;
    const P = phoneSpeedNativePlugin();
    if (!P || !P.requestNotifications) return false;
    try { const r = await P.requestNotifications(); return !!(r && r.granted); } catch (e) { return false; }
}

async function updatePhoneSpeedPoster(mode) {
    const wantFast = Number(mode) === 1;
    const bs = phoneSpeedNativePlugin();
    if (wantFast && bs && await phoneSpeedBgDisclosed()) {
        // Re-called on every CSV3 echo; the plugin treats a repeat start as a config
        // refresh, so a changed device IP is picked up within a minute.
        if (!phoneSpeedNativeActive) await ensureSpeedNotificationPermission();
        try {
            await bs.start({ postUrl: buildURL('/set_phone_data') });
            phoneSpeedNativeActive = true;
            phoneSpeedNativeStopTried = false;
            // An earlier failed start may have left the JS watch running: two streams would
            // post concurrently, so the native path always owns the teardown of the fallback.
            stopPhoneSpeedJsWatch();
            return;
        } catch (e) {
            console.warn('[PhoneGPS] BackgroundSpeed start failed, falling back to JS watch:', e && e.message);
        }
    }
    if (!wantFast && bs && (phoneSpeedNativeActive || !phoneSpeedNativeStopTried)) {
        // Stop once even when this session never started it: a native stream started before a
        // webview reload is invisible to the flag and would run GPS until the app process dies.
        phoneSpeedNativeActive = false;
        phoneSpeedNativeStopTried = true;
        try { bs.stop(); } catch (e) { }
    }
    if (wantFast && phoneSpeedWatchId === null) {
        if (IS_CAPACITOR) {
            if (!(window.Capacitor.Plugins && window.Capacitor.Plugins.Geolocation)) return;
            phoneSpeedWatchId = 'pending';   // re-entry guard while the start promise resolves
            phoneSpeedWatchIsCap = true;
            try {
                const id = await window.Capacitor.Plugins.Geolocation.watchPosition(
                    { enableHighAccuracy: true, timeout: 10000 },
                    p => phoneSpeedWatchFix(p));
                if (phoneSpeedWatchId === 'pending') {
                    phoneSpeedWatchId = id;
                } else {
                    // Mode flipped off while the watch was starting — kill the orphan.
                    try { window.Capacitor.Plugins.Geolocation.clearWatch({ id }); } catch (e2) { }
                }
            } catch (e) {
                console.warn('[PhoneGPS] watchPosition failed:', e && e.message);
                if (phoneSpeedWatchId === 'pending') phoneSpeedWatchId = null;
            }
        } else if (typeof navigator !== 'undefined' && navigator.geolocation &&
                   !(typeof window !== 'undefined' && window.isSecureContext === false)) {
            phoneSpeedWatchIsCap = false;
            phoneSpeedWatchId = navigator.geolocation.watchPosition(
                p => phoneSpeedWatchFix(p),
                err => diagWarn('[PhoneGPS] watch failed:', err && err.message),
                { enableHighAccuracy: true, timeout: 10000 });
        }
    } else if (!wantFast) {
        stopPhoneSpeedJsWatch();
    }
}
window.updatePhoneSpeedPoster = updatePhoneSpeedPoster;

// Selection-time warning: switching to phone speed has real tradeoffs, so the select
// submits only after an explicit acknowledgment. Cancel reverts the dropdown to NMEA
// (binary setting, so a change to phone always came from NMEA; the CSV3 echo re-syncs
// it regardless on the next frame).
async function speedSourceModeChanged(sel) {
    if (Number(sel.value) === 1) {
        const ok = await xConfirm(phoneSpeedModeDialogText(),
            { title: 'Use phone GPS for speed?', okText: 'Use Phone GPS' });
        if (!ok) { sel.value = '0'; return; }
        markPhoneSpeedDisclosed();   // this dialog IS the disclosure — the poster must not raise a second copy
        // Ask for authorization here rather than at launch: this is the moment the feature
        // is switched on, which is what guideline 5.1.1(ii) and the HIG both want.
        // Capacitor only — the setting is device-global while the permission is this-client's,
        // so a browser must still submit (its own geolocation prompt fires when posting starts,
        // and the foreground-only bullet above already told the user the browser tradeoff).
        if (IS_CAPACITOR) {
            const granted = await requestPhoneLocationPermission(
                'XREG-010 needs this phone\'s location to use it as the vessel speed source. ' +
                'Speed and course go to your regulator on your local network.');
            if (!granted) { sel.value = '0'; return; }
        }
    }
    sel.form.submit();
    submitMessage();
}

function startPhoneDataPoster() {
    if (phoneDataPosterTimer) return;  // already running
    // Fire immediately so the device gets the client clock within ~1s of connecting (AP mode has
    // no other time source), then refresh on interval.
    postPhoneDataToDevice();
    phoneDataPosterTimer = setInterval(postPhoneDataToDevice, PHONE_DATA_POST_INTERVAL_MS);
}

// Kick off poster on page load. Runs regardless of lock state — both fields
// are trusted backup sources the device accepts unconditionally.
document.addEventListener('DOMContentLoaded', startPhoneDataPoster);

// ===== CRITICAL MOBILE FIXES (Required for iOS) =====

function manualReconnect() {
    sseReconnectAttempts = 0;
    isAppInBackground = false;
    window._rediscoveryTried = false;
    discoverAndConnect();
    document.getElementById('reconnect-button').style.display = 'none';
    closeRecovery(); // Dismiss the Connection Lost dialog if user used the in-page button instead
}

// ===== DIAGNOSTIC LOGGING SYSTEM =====
let SHOW_DIAGNOSTIC_MESSAGES = false; // Initial value (gets overridden below)

/**
 * Enable or disable diagnostic logging globally
 * @param {boolean} enabled - True to show diagnostic messages
 */
function setDiagnosticMode(enabled) {
    SHOW_DIAGNOSTIC_MESSAGES = enabled;
    console.log(`[DIAGNOSTIC MODE] ${enabled ? 'ENABLED' : 'DISABLED'}`);
}

/**
 * Check if diagnostic mode is currently enabled
 * @returns {boolean} Current diagnostic mode state
 */
function isDiagnosticMode() {
    return SHOW_DIAGNOSTIC_MESSAGES;
}

/**
 * Replacement for console.log - only logs if diagnostic mode enabled
 * @param {...any} args - Arguments to log
 */
function diagLog(...args) {
    if (SHOW_DIAGNOSTIC_MESSAGES) {
        console.log('[DIAG]', ...args);
    }
}

/**
 * Replacement for console.warn - only logs if diagnostic mode enabled
 * @param {...any} args - Arguments to log
 */
function diagWarn(...args) {
    if (SHOW_DIAGNOSTIC_MESSAGES) {
        console.warn('[DIAG WARN]', ...args);
    }
}

/**
 * Replacement for console.error - ALWAYS logs errors
 * In diagnostic mode, adds [DIAG ERROR] prefix
 * @param {...any} args - Arguments to log
 */
function diagError(...args) {
    if (SHOW_DIAGNOSTIC_MESSAGES) {
        console.error('[DIAG ERROR]', ...args);
    } else {
        console.error(...args);
    }
}

/**
 * Development logging - ALWAYS logs regardless of diagnostic mode
 * Use sparingly - only for critical debugging
 * @param {...any} args - Arguments to log
 */
function devLog(...args) {
    console.log('[DEV]', ...args);
}

// ===== TOGGLE DIAGNOSTIC MODE HERE - SET TO false FOR APP STORE SUBMISSION =====
setDiagnosticMode(false); // ← CHANGE THIS LINE: true=ON, false=OFF
//What gets hidden when false:
//diagLog() - YES, hidden when false
//diagWarn() - YES, hidden when false
//diagError() - NO, always shows (even when false)


// ===== END DIAGNOSTIC LOGGING SYSTEM =====


// 1. Fetch with timeout - prevents infinite hangs. On timeout the fetch is ABORTED so its socket
// returns to the ESP32 (it has very few); callers still see the legacy Error('Request timeout'),
// never an AbortError — Promise.race already settled with the timeout rejection by the time the
// aborted fetch rejects, and race subscribes to both so nothing is unhandled. On settle the timer
// is cleared (a won race used to leave a dead timer running to its full timeout).
function fetchWithTimeout(url, options = {}, timeout = 8000) {
    const ctrl = new AbortController();
    let timerId = null;
    return Promise.race([
        fetch(url, { ...options, signal: ctrl.signal }),
        new Promise((_, reject) => {
            timerId = setTrackedTimeout(() => {
                timerId = null;   // fired — self-pruned, nothing to clear
                ctrl.abort();
                reject(new Error('Request timeout'));
            }, timeout);
        })
    ]).finally(() => { if (timerId !== null) clearTrackedTimeout(timerId); });
}

// The 4 registration/profile endpoints stage an async cloud op on the firmware (the old synchronous
// handlers blocked every other endpoint for up to ~45 s on a dead uplink) and answer
// 202 {"state":"pending","op":N}. Poll /cloudOpState until that op is done, then synthesize the
// legacy response (its code + JSON body) so callers keep their old parse logic untouched. Non-202
// replies (403 not armed, sync short-circuits like {"registered":false}) pass through as-is.
async function cloudOpPost(url, options, timeout) {
    const staged = await fetchWithTimeout(url, options, timeout || 8000);
    if (staged.status !== 202) return staged;
    let stagedData = null;
    try { stagedData = await staged.clone().json(); } catch (e) { return staged; }
    if (!stagedData || stagedData.state !== 'pending') return staged;
    const op = stagedData.op;
    const deadline = Date.now() + 90000;   // worst case on-device is ~45 s connect+read, plus retry slack
    while (Date.now() < deadline) {
        await new Promise(resolve => setTrackedTimeout(resolve, 1000));
        let st = null;
        try {
            const poll = await fetchWithTimeout(buildURL('/cloudOpState'), { cache: 'no-store' }, 5000);
            if (!poll.ok) continue;
            st = await poll.json();
        } catch (e) { continue; }   // transient poll failure — keep waiting
        if (st.state === 'done' && st.op === op) {
            return new Response(JSON.stringify(st.body === undefined ? null : st.body), {
                status: st.code || 200,
                headers: { 'Content-Type': 'application/json' }
            });
        }
        if (st.state === 'idle' || (st.op !== undefined && st.op !== op)) {
            throw new Error('cloud operation was lost or superseded (device restarted?)');
        }
    }
    throw new Error('cloud operation timed out');
}



// 2. Cleanup function - prevents memory leaks

function setTrackedInterval(callback, delay) {
    const id = setInterval(callback, delay);
    activeTimers.push({ type: 'interval', id });
    return id;
}

function setTrackedTimeout(callback, delay) {
    // Self-pruning: fired entries were never removed, so the array grew for the life of the
    // page (every fetchWithTimeout, debounce keystroke, and button pulse pushed one forever).
    const id = setTimeout(() => {
        const i = activeTimers.findIndex(t => t.type === 'timeout' && t.id === id);
        if (i !== -1) activeTimers.splice(i, 1);
        callback();
    }, delay);
    activeTimers.push({ type: 'timeout', id });
    return id;
}

// Cancel a tracked timeout BEFORE it fires: a bare clearTimeout leaves the entry in activeTimers
// forever (the self-prune above only runs when the callback fires).
function clearTrackedTimeout(id) {
    clearTimeout(id);
    const i = activeTimers.findIndex(t => t.type === 'timeout' && t.id === id);
    if (i !== -1) activeTimers.splice(i, 1);
}

// Same for an interval stopped before cleanupResources runs.
function clearTrackedInterval(id) {
    clearInterval(id);
    const i = activeTimers.findIndex(t => t.type === 'interval' && t.id === id);
    if (i !== -1) activeTimers.splice(i, 1);
}

function cleanupResources() {
    diagLog("Cleaning up resources");

    activeTimers.forEach(timer => {
        if (timer.type === 'interval') {
            clearInterval(timer.id);
        } else {
            clearTimeout(timer.id);
        }
    });
    activeTimers = [];

    if (source) {
        source.close();
        source = null;
    }

    if (sseReconnectTimer) {
        clearTimeout(sseReconnectTimer);
        sseReconnectTimer = null;
    }

    // Clear the adaptive log-relay poll timer (self-rescheduling, not in activeTimers)
    if (g_logPollTimer) {
        clearTimeout(g_logPollTimer);
        g_logPollTimer = null;
    }

    // The ripple-map poll's interval died with activeTimers above; drop its id or rippleMapPollSync
    // still believes it is running and never restarts it.
    rippleMapPollId = null;

    if (typeof currentTempPlot !== 'undefined' && currentTempPlot) {
        currentTempPlot.destroy();
        currentTempPlot = null;
    }
    if (typeof voltagePlot !== 'undefined' && voltagePlot) {
        voltagePlot.destroy();
        voltagePlot = null;
    }
    if (typeof rpmPlot !== 'undefined' && rpmPlot) {
        rpmPlot.destroy();
        rpmPlot = null;
    }
    if (typeof temperaturePlot !== 'undefined' && temperaturePlot) {
        temperaturePlot.destroy();
        temperaturePlot = null;
    }

    // Clear data arrays (CRITICAL for memory management)
    if (typeof currentTempData !== 'undefined') currentTempData.length = 0;
    if (typeof voltageData !== 'undefined') voltageData.length = 0;
    if (typeof rpmData !== 'undefined') rpmData.length = 0;
    if (typeof temperatureData !== 'undefined') temperatureData.length = 0;
}
// Dark-mode toggle repaint: axis/grid/tick colors are theme-resolving functions injected
// at construction (see stabilizeUPlotAxisSizes), so a bare redraw() recolors every plot.
// Plots whose root left the DOM (rebuilt/replaced) are pruned here.
function refreshAllPlotThemes() {
    if (!window._allUPlots) return;
    window._allUPlots.forEach(u => {
        if (!u.root || !u.root.isConnected) { window._allUPlots.delete(u); return; }
        try { u.redraw(); } catch (e) { }
    });
}

// 3. Cleanup on page unload
window.addEventListener('beforeunload', cleanupResources);

// Foregrounding fires BOTH @capacitor/app's appStateChange and visibilitychange, and one
// reconnect is all that is wanted: a second would close the EventSource the first just
// opened. Single entry point, one reconnect per 3 s. A stream can read OPEN while dead
// (backgrounded sockets), so an event drought counts as dead too.
let lastForegroundReconnectMs = 0;
function foregroundReconnect() {
    isAppInBackground = false;
    sseReconnectAttempts = 0;
    window._rediscoveryTried = false;  // each foreground gets a fresh network re-scan chance
    const now = Date.now();
    if (now - lastForegroundReconnectMs < 3000) return;
    const dead = !source || source.readyState === EventSource.CLOSED || (now - lastEventTime > 5000);
    if (!dead || discoveryInProgress) { diagLog("Connection still alive, resuming normal operation"); return; }
    lastForegroundReconnectMs = now;
    diagLog("Connection was closed, reconnecting...");
    initializeEventSource();
}

// 4. Handle app lifecycle (Capacitor-specific)
if (IS_CAPACITOR && window.Capacitor.Plugins && window.Capacitor.Plugins.App) {
    window.Capacitor.Plugins.App.addListener('appStateChange', ({ isActive }) => {
        if (isActive) {
            diagLog("App foregrounded");
            foregroundReconnect();
        } else {
            diagLog("App backgrounded - keeping connection alive");
            isAppInBackground = true;

            // Stop auto-reconnect attempts while backgrounded
            if (sseReconnectTimer) {
                clearTimeout(sseReconnectTimer);
                sseReconnectTimer = null;
            }

            // DON'T call cleanupResources() - let SSE connection persist
            // iOS may close it after ~30 seconds, but we'll reconnect when foregrounded
        }
    });
    // Android hardware/gesture Back (never fires on iOS).
    window.Capacitor.Plugins.App.addListener('backButton', () => {
        try { handleAndroidBack(); } catch (e) { console.warn('[BACK]', e && e.message); }
    });
}

// Back precedence: themed dialog, Connection Lost, settings search, then the topmost open
// modal, then the Live Data tab, then the OS. minimizeApp, never exitApp — a stray swipe
// must not kill the SSE session and the page state behind it.
function handleAndroidBack() {
    const vis = el => !!(el && el.getClientRects().length);   // these overlays are position:fixed, so offsetParent is always null
    // The themed alert/confirm's first button is Cancel on a confirm and OK on an alert:
    // clicking it settles the promise the caller is awaiting. Hiding the overlay would not.
    const dlg = document.getElementById('xdlg-overlay');
    if (vis(dlg)) { const b = dlg.querySelector('#xdlg-btns button'); if (b) b.click(); return; }
    if (document.getElementById('recoveryDialog')) { closeRecovery(); return; }
    if (document.querySelector('.ss-backdrop.ss-open')) { ssClose(); return; }

    // Every dismissable panel is a top-level fixed overlay whose header carries a lone ✕ —
    // the one button that also tears its state down. Highest z-index is the topmost.
    // #test-panel-overlay is excluded: it is a floating pill, and its ✕ aborts a running test.
    let top = null, topZ = -1;
    document.querySelectorAll('body > div[id$="-overlay"]').forEach(el => {
        if (el.id === 'test-panel-overlay' || !vis(el)) return;
        const z = parseInt(getComputedStyle(el).zIndex, 10) || 0;
        if (z >= topZ) { topZ = z; top = el; }
    });
    if (top) {
        if (top.id === 'commission-modal-overlay' && cxRunActive()) {
            fileToast('Test running — use the wizard\'s Stop or Abort button');
            return;   // a back swipe must never abort a run
        }
        const x = Array.prototype.find.call(top.querySelectorAll('button'),
                                            b => b.textContent.trim() === '✕' && vis(b));
        if (x) x.click();
        return;   // a modal with no dismiss button swallows Back rather than letting it through
    }

    // Vessel Info incomplete pins the UI to Setup, where sending Back to Live Data would only
    // raise the nag alert — minimize instead.
    const active = document.querySelector('.tab-content.active');
    if (active && active.id !== 'livedata' && vesselInfoComplete) { showMainTab('livedata'); return; }
    const App = window.Capacitor.Plugins.App;
    if (App && App.minimizeApp) App.minimizeApp();
}

// Foreground reconnect that needs no plugin: app builds without @capacitor/app never bind
// the appStateChange listener above, but every WebView still fires visibilitychange on
// background/foreground. Both routes share foregroundReconnect(), which collapses the two
// into one reconnect when the plugin IS present.
document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible') return;
    foregroundReconnect();
});

function initializeEventSource() {

    if (DEMO_MODE) {
        return;
    }

    if (isAppInBackground) {
        diagLog("App backgrounded, skipping SSE reconnection");
        return;
    }
    if (sseReconnectAttempts >= MAX_SSE_RECONNECTS) {
        // Capacitor: a hotspot bounce hands the regulator a new IP, so retries
        // against the old one exhausting is the EXPECTED signal — re-scan the
        // network once (rediscoverAfterLoss shows the dialog itself on failure).
        if (IS_CAPACITOR && !DEMO_MODE && !window._rediscoveryTried) {
            window._rediscoveryTried = true;
            console.log('[DISCOVERY] SSE retries exhausted — re-scanning for the regulator');
            rediscoverAfterLoss();
            return;
        }
        diagLog("Max SSE reconnection attempts reached (10 attempts over 20 seconds). Manual reconnect required.");

        // Show the Connection Lost dialog (gives user the choice of full-reload retry
        // or "Continue Offline" which disables inputs). Hide the in-page reconnect-button
        // while the dialog is up to avoid two competing recovery affordances on screen.
        showRecoveryOptions();
        const reconnectBtn = document.getElementById('reconnect-button');
        if (reconnectBtn) {
            reconnectBtn.style.display = 'none';
        }

        return;
    }

    if (source) {
        source.close();
        source = null;
    }

    if (!window.EventSource) {
        diagError("EventSource not supported");
        return;
    }

    try {
        sseConnectingErrors = 0;  // stale count from a previous source must not insta-trip the new one
        source = new EventSource(buildURL('/events'));

        source.addEventListener('open', function () {
            sseReconnectAttempts = 0;
            sseConnectingErrors = 0;
            window._rediscoveryTried = false;  // re-arm the one-scan-per-loss latch
            updateInlineStatus(true);  // Flip indicator green on SSE connect
            closeRecovery();           // Dismiss Connection Lost dialog if it's open
            if (isOfflineMode) exitOfflineMode(); // Re-enable inputs if user had gone offline
            checkInstallIdFreshness(); // drop stale console history if the device was reflashed/reset
            // Close the hole this outage just punched in the console. Only on a genuine reconnect —
            // the first open of a page life has no gap to fill, and checkInstallIdFreshness may be
            // about to clear the buffer for a reflashed device.
            const gapMs = Date.now() - lastEventTime;
            if (window._firstCsvPacketReceived && gapMs > 3000) {
                const gapEnd = Date.now();
                setTrackedTimeout(() => consoleBackfillFromDevice(gapEnd - gapMs, gapEnd), 1200);
            }
        }, false);


        // \u2500\u2500 SSE: AltLive \u2500 charging-system health live + trend (schema-driven via /altschema) \u2500\u2500
        source.addEventListener('AltLive', function (e) {
            if (!altSchema || !altSchema.live) { if (!altSchema) fetchAltSchema(); return; }
            const v = e.data.split(',').map(Number);
            altSchema.live.forEach((k, i) => { altLive[k] = v[i]; });
            altLive.valid = altLive.valid === 1;
            altLive.steady = altLive.steady === 1;
            updateAltHealth();
            try { altCaptureRender(); } catch (err) {}      // gate-tuning recorder state + countdown
            try { altSessMaybeRecover(); } catch (err) {}   // pull the device series on connect / after a gap
            try { altSessionPush(); } catch (err) {}   // 1 Hz session plot feed
            queueAltTrendUpdate();
            updateCloudStatus();
        }, false);

        // \u2500\u2500 SSE: AltSettings \u2500 GUI-tunable values \u2192 echo spans (schema-driven) \u2500\u2500
        source.addEventListener('AltSettings', function (e) {
            if (!altSchema || !altSchema.settings) { if (!altSchema) fetchAltSchema(); return; }
            const v = e.data.split(',').map(Number);
            const ALT_NOECHO = { altPaused: 1 };   // driven by the Pause/Continue + Reference Source buttons, no echo span
            altSchema.settings.forEach((k, i) => {
                altSettings[k] = v[i];
                if (ALT_NOECHO[k]) return;
                const txt = (k === 'altThermDegF')   // temperature band — follows C/F toggle (delta)
                    ? toDisplayTempDelta(v[i]).toFixed(1)
                    : (Math.round(v[i] * 1000) / 1000);
                const el = document.getElementById(k + '_echo');
                if (el) el.textContent = txt;
                // Band-matrix cells carry the value IN the box — a table has no room for the
                // "(30)" parenthetical — so the echo drives the input as well, except while the
                // user is typing in that box.
                const inp = document.querySelector('input[data-echo="' + k + '"]');
                if (inp && document.activeElement !== inp && inp.dataset.dirty !== '1') inp.value = txt;
            });
            sinfoRefreshOpen();   // alt* echoes feed the C3 "s" signal-info boxes
        }, false);

        // \u2500\u2500 SSE: PerfLive / PerfSettings \u2500 schema-driven (names from /perfschema; no hardcoded array) \u2500\u2500
        source.addEventListener('PerfLive', function (e) {
            if (!perfSchema || !perfSchema.live) { if (!perfSchema) fetchPerfSchema(); return; }
            const v = e.data.split(',').map(Number);
            perfSchema.live.forEach((k, i) => { perfLive[k] = v[i]; });
            perfLive.valid = perfLive.valid === 1;
            updatePerf(); queuePerfPlotUpdate();
            updateCloudStatus();
        }, false);
        source.addEventListener('PerfSettings', function (e) {
            if (!perfSchema || !perfSchema.settings) { if (!perfSchema) fetchPerfSchema(); return; }
            const v = e.data.split(',').map(Number);
            const PERF_NOECHO = { perfFoldSymmetric: 1, perfSpeedSrc: 1, perfPaused: 1 };  // segmented/switch controls, no echo span
            perfSchema.settings.forEach((k, i) => {
                perfSettings[k] = v[i];
                if (PERF_NOECHO[k]) return;
                const el = document.getElementById(k + '_echo');
                if (el) el.textContent = (Math.round(v[i] * 1000) / 1000);
            });
            updatePerfControls(); queuePerfPlotUpdate(); queueMotorPlotUpdate();
        }, false);
        source.addEventListener('MotorLive', function (e) {
            if (!perfSchema || !perfSchema.motorLive) { if (!perfSchema) fetchPerfSchema(); return; }
            const v = e.data.split(',').map(Number);
            perfSchema.motorLive.forEach((k, i) => { motorLive[k] = v[i]; });
            motorLive.valid = motorLive.valid === 1;
            updateMotor(); queueMotorPlotUpdate();
        }, false);
        fetchPerfSchema();
        fetchAltSchema();
        // These poll the ESP32, and AsyncTCP preempts the control loop, so only poll while the panel is
        // actually rendered. The cursor resets on hide, so re-opening a tab fetches at once rather than
        // waiting out one period — fresher on arrival than the old always-on timers.
        // fetchKneeLearnState also disables the Keep-Alive cells when learning is on, so it must run once at
        // connect, not on the first visible tick — otherwise the cells look editable, and Chrome silently
        // drops the rest of your keystrokes when the disable lands on the input you are typing into.
        if (!window._kneeTimer)    { fetchKneeLearnState(); window._kneeTimer = pollWhenVisible(fetchKneeLearnState, 'kneeLearnEnable_checkbox', 4000); }
        if (!window._zeroLogTimer) window._zeroLogTimer = pollWhenVisible(fetchZeroLogState,   'ZeroLogEnable_echo',       5000);
        if (!window._zeroFitTimer) window._zeroFitTimer = pollWhenVisible(fetchZeroFitState,   'zerofit-status',           5000);

        source.addEventListener('error', function (e) {
            const state = this.readyState;
            let reason = '';

            if (state === EventSource.CONNECTING) {
                reason = 'Network hiccup or temporary stall (CONNECTING)';
            } else if (state === EventSource.CLOSED) {
                reason = 'Connection closed — likely WiFi drop, ESP32 reboot, or stalled SSE stream';
            } else {
                reason = 'Unknown SSE error state';
            }

            // ALWAYS visible — not suppressed by diagnostic mode
            console.error('[SSE ERROR]', reason, 'readyState=', state, 'event=', e);
            updateInlineStatus(false);  // Flip indicator red on any SSE error

            if (state === EventSource.CONNECTING) {
                // Native auto-retry heals a device that comes back at the SAME
                // address; after a hotspot bounce it retries a dead IP forever.
                // Enough consecutive failures with no 'open' between them → stop
                // and re-scan (Capacitor only — browsers can't scan, and native
                // retry is their best remaining strategy).
                sseConnectingErrors++;
                if (IS_CAPACITOR && !DEMO_MODE && sseConnectingErrors >= MAX_SSE_CONNECTING_ERRORS && !discoveryInProgress) {
                    this.close();
                    sseConnectingErrors = 0;
                    if (!window._rediscoveryTried) {
                        window._rediscoveryTried = true;
                        console.log('[DISCOVERY] SSE stuck reconnecting — re-scanning for the regulator');
                        rediscoverAfterLoss();
                    } else {
                        showRecoveryOptions();
                        const reconnectBtn = document.getElementById('reconnect-button');
                        if (reconnectBtn) reconnectBtn.style.display = 'none';
                    }
                    return;
                }
            }

            if (state === EventSource.CLOSED) {
                sseReconnectAttempts++;

                const backoffDelay = 2000; // Fixed 2 second retry interval

                // ALSO always visible
                console.error('[SSE RECONNECT]',
                    `Attempt ${sseReconnectAttempts}/${MAX_SSE_RECONNECTS}`,
                    `delay=${backoffDelay}ms`);

                if (sseReconnectTimer) {
                    clearTimeout(sseReconnectTimer);
                }

                sseReconnectTimer = setTrackedTimeout(() => {
                    initializeEventSource();
                }, backoffDelay);
            }
        }, false);

        // Re-bind stream listeners (CSVData/CSVData2/CSVData3/TimestampData/console)
        // on every reconnect. Without this, only the open/AltLive/AltSettings/error
        // listeners survive a reconnect and the main telemetry streams go silent.
        // window.attachStreamListeners is defined inside the window 'load' callback,
        // so it is undefined on the very first call to initializeEventSource() — the
        // initial attach is performed by the load callback itself once.
        if (typeof window.attachStreamListeners === 'function') {
            window.attachStreamListeners(source);
        }

    } catch (error) {
        diagError("Failed to create EventSource:", error);
    }
}

// ===== DEMO MODE FOR APP STORE (No ESP32 hardware required) =====

function enableDemoMode() {
    if (DEMO_MODE) return;

    DEMO_MODE = true;
    console.log('[DEMO MODE] Enabled - Generating simulated data');

    // Hard-sever the device link: demo must never actuate real hardware — field
    // enable, alarm GPIO, reboot, OTA — even if a regulator appears on the network
    // AFTER demo latched. RFC-2606 .invalid can never resolve, so every fetch and
    // re-synced form action dies at DNS; the remembered base in localStorage stays
    // untouched for the next real launch. The capture-phase listener also swallows
    // form submits outright (their hidden target iframe would otherwise render a
    // WKWebView error page).
    API_BASE_URL = 'http://demo.invalid';
    syncFormActionsToDevice();
    document.addEventListener('submit', function (e) {
        if (DEMO_MODE) { e.preventDefault(); e.stopImmediatePropagation(); }
    }, true);

    // Demo feeds handleCSVData() directly (bypassing the CSVData listener that
    // normally hides the boat splash), so clear the splash here too. Same for the
    // Connection Lost dialog — the failed-rediscovery path can raise it before
    // demo's patience window expires.
    hideWaitingForRegulator();
    closeRecovery();

    // Add visual demo banner. padding-top includes env(safe-area-inset-top) so
    // the warning isn't hidden under the iPhone notch / Dynamic Island.
    const banner = document.createElement('div');
    banner.id = 'demo-banner';
    banner.style.cssText = 'position:fixed;top:0;left:0;right:0;background:#ff9800;color:#000;padding:calc(10px + env(safe-area-inset-top)) 10px 10px;text-align:center;z-index:10000;font-weight:bold;font-size:14px;';
    banner.textContent = '⚠️ DEMO MODE - Simulated Data (No Hardware Connected)';
    document.body.insertBefore(banner, document.body.firstChild);

    // Adjust body padding to account for banner (also notch-aware).
    document.body.style.paddingTop = 'calc(40px + env(safe-area-inset-top))';

    // Demo has no device to fetch vessel_info.json from, so vesselInfoComplete is
    // false and the Setup-only tab lock would trap the user on Vessel Info. Vessel
    // info is meaningless without hardware — mark it complete, pin the landing
    // (demo bypasses the CSVData listener, so maybeApplyLanding never runs), and
    // go straight to Live Data → Alternator with free navigation.
    vesselInfoComplete = true;
    window._landingApplied = true;
    showMainTab('livedata');
    showSubTab('livedata', 'alternator');

    // The settings arm-gate lives in firmware, so without hardware the Unlock
    // button can never succeed (and the submit swallower above blocks its form
    // anyway) — unlock outright so the button disappears and every pane is
    // browsable. Registered=true opens the Cloud Features sub-tab gate; Fleet
    // Stats / Leaderboards / Config Sharing are public cloud iframes that load
    // fine over the phone's own internet. The cloud tab gets a prominent
    // everything-here-is-fake banner.
    applySettingsUnlockUI();
    isDeviceRegistered = true;
    demoInjectCloudBanner();
    demoFillCloudPanes();

    startDemoData();

}

// Prominent disclosure pinned above the Cloud Features sub-tabs while demo is live.
// The profile below it is simulated; the iframes (leaderboards etc.) are real public pages.
function demoInjectCloudBanner() {
    if (document.getElementById('demo-cloud-banner')) return;
    const tab = document.getElementById('cloudfeatures');
    if (!tab) return;
    const b = document.createElement('div');
    b.id = 'demo-cloud-banner';
    b.style.cssText = 'background:#ff9800;color:#000;font-weight:bold;font-size:14px;text-align:center;padding:10px 12px;border-radius:6px;margin:8px 0;';
    b.textContent = 'DEMO MODE - Everything on this page is simulated. Nothing is real, saved, or sent.';
    tab.insertBefore(b, tab.firstChild);
}

// Brief static mockups for the Cloud Features sub-tabs. The real panes are cloud
// iframes keyed to a registered device token, so in demo the iframes stay hidden
// and these render into each pane's status element instead. Buttons are decorative
// (disabled) — demo is navigate-and-look, not click.
function demoFillCloudPanes() {
    const th = 'text-align:left;padding:6px 10px;border-bottom:1px solid rgba(128,128,128,0.35);';
    const td = 'padding:6px 10px;border-bottom:1px solid rgba(128,128,128,0.2);';
    const row3 = (a, b, c) => `<tr><td style="${td}">${a}</td><td style="${td}">${b}</td><td style="${td}">${c}</td></tr>`;
    const table = (h3, rows) => `<table style="border-collapse:collapse;margin:6px 0 16px;"><tr><th style="${th}">#</th><th style="${th}">Vessel</th><th style="${th}">${h3}</th></tr>${rows}</table>`;
    const set = (id, html) => {
        const el = document.getElementById(id);
        if (el) { el.innerHTML = html; el.style.color = 'inherit'; el.style.display = 'block'; }
    };
    set('leaderboards-status',
        '<strong>Deepest Anchorage</strong>'
        + table('Depth', row3(1, 'Meridian', '142 ft') + row3(2, 'Blue Heron', '118 ft') + row3(3, 'DemoBoat', '96 ft'))
        + '<strong>Longest Passage</strong>'
        + table('Distance', row3(1, 'Wanderer', '1,240 nm') + row3(2, 'Meridian', '980 nm') + row3(3, 'DemoBoat', '610 nm')));
    set('fleetstats-status',
        '<strong>Fleet Overview</strong>'
        + '<div style="line-height:1.9;margin-top:6px;">Registered vessels: 47<br>'
        + 'Combined engine hours: 12,840<br>'
        + 'Average alternator output: 61 A<br>'
        + 'Energy charged this month: 3.9 MWh<br>'
        + 'Most common battery: LiFePO4 400 Ah</div>');
    const cfgBtn = '<button class="btn-secondary" disabled style="opacity:0.5;">Load</button>';
    const cfgRow = (name, by) => `<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 4px;border-bottom:1px solid rgba(128,128,128,0.2);"><span>${name}<br><small style="opacity:0.7;">shared by ${by}</small></span>${cfgBtn}</div>`;
    set('configsharing-status',
        '<strong>Shared Configurations</strong>'
        + cfgRow('LiFePO4 600 Ah / 12 V coastal cruiser', 'Blue Heron')
        + cfgRow('AGM 400 Ah / 12 V bluewater setup', 'Meridian')
        + cfgRow('LiFePO4 300 Ah / 24 V catamaran', 'Wanderer'));
    demoRenderSoftwareUpdate();
}

function demoRenderSoftwareUpdate() {
    const cur = document.getElementById('current-version-display');
    if (cur) cur.textContent = '0.0.48';
    const cur2 = document.getElementById('current-version-display-2');
    if (cur2) cur2.textContent = '0.0.48';
    const loading = document.getElementById('version-loading');
    if (loading) loading.style.display = 'none';
    const list = document.getElementById('version-list');
    if (list) {
        const vrow = (v, note, cta) => `<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 4px;border-bottom:1px solid rgba(128,128,128,0.2);"><span>${v}${note}</span><button class="btn-secondary" disabled style="opacity:0.5;">${cta}</button></div>`;
        list.innerHTML = vrow('0.0.48', ' — installed', 'Reinstall') + vrow('0.0.47', '', 'Install') + vrow('0.0.46', '', 'Install');
        list.style.display = 'block';
    }
}

function startDemoData() {
    sendFakeCSVData();

    // 200 ms = the firmware's default CSV1 broadcast period. Anything slower than the
    // plots' stream-gap limit (max(4×interval, 1500 ms)) stamps a gap marker and breaks
    // the line on EVERY frame — a 2 s demo cadence rendered as all markers, no traces.
    demoInterval = setInterval(sendFakeCSVData, 200);
}

function sendFakeCSVData() {
    window.lastEventTime = Date.now();

    if (window.sensorAges) {
        window.sensorAges.ibv = 0;
        window.sensorAges.soc = 0;
        window.sensorAges.measuredAmps = 0;
        window.sensorAges.bcur = 0;
        window.sensorAges.alternatorTemp = 0;
        window.sensorAges.rpm = 0;
    }

    if (typeof updateInlineStatus === 'function') {
        updateInlineStatus(true);
    }

    // Registry-driven: CSV1/CSV2 frames are `count,` + one value per *_FIELDS entry,
    // and the handlers DISCARD any frame whose count mismatches — a positional array
    // rots on every schema change (the old 50-slot version died that way). Values are
    // fixed-point exactly as firmware sends them (×100 unless noted); unnamed keys
    // default to 0. Slow sine walks + jitter paint a plausible charge scene:
    // ~55 A into the bank at ~13.9 V, ~1900 RPM, field ~40%.
    const t = Date.now() / 1000;
    const rpm = 1900 + 300 * Math.sin(t / 19) + (Math.random() * 60 - 30);
    const ampsClean = 55 + 9 * Math.sin(t / 13);              // filtered/PV traces ride this
    const amps = ampsClean + (Math.random() * 2 - 1);         // raw sensor adds jitter
    const voltsClean = 13.9 + 0.25 * Math.sin(t / 37);
    const volts = voltsClean + (Math.random() * 0.02 - 0.01);
    const duty = 40 + 7 * Math.sin(t / 13 + 0.6) + Math.random();
    const spl = 59 + Math.sin(t / 97);                        // post-limit setpoint, just under the 60 A target
    const csv1 = {
        AlternatorTemperatureF: Math.round((168 + 8 * Math.sin(t / 53)) * 100),
        dutyCycle: Math.round(duty * 100),
        BatteryV: Math.round(volts * 100),
        MeasuredAmps: Math.round(amps * 100),
        RPM: Math.round(rpm),
        Channel3V: Math.round((12.82 + 0.03 * Math.sin(t / 41)) * 100),
        IBV: Math.round((volts - 0.04) * 100),
        Bcur: Math.round((amps - 22) * 100),   // house loads eat part of the output
        VictronVoltage: Math.round((volts - 0.03) * 100),
        FreeHeap: 148000,
        fieldActiveStatus: 1,
        // CC current-PID group (PID tuning plot): PV = filtered amps chasing the limited setpoint
        setpointLimited: Math.round(spl * 100),
        uTargetAmps: 6000,
        pidInput: Math.round(ampsClean * 100),
        pidOutput: Math.round(duty * 100),
        pidError: Math.round((spl - ampsClean) * 100),
        pidAltPV: Math.round(ampsClean * 100),
        // CV loop group (CV tuning + Voltage plots): below-target CC cruise, ceiling parked high
        voltageTarget: 1440,
        Icv: Math.round(6000 + 150 * Math.sin(t / 71)),
        cvPTerm: Math.round((14.4 - voltsClean) * 8 * 100),
        cvIterm: Math.round(5600 + 300 * Math.sin(t / 61)),
        cvKdTrim: Math.max(0, Math.round(150 * Math.sin(t / 7) - 100)),   // occasional small D back-off
        cvKdFiltV: Math.round(voltsClean * 100),
        vvout: Math.round(duty / 100 * volts * 100),
        iiout: Math.round((2.0 + duty / 25) * 100),
        Ignition: 1,
        // iExcess detector sparkline (A ×10): excess breathing well under its threshold
        mExcessEma: Math.round(6 + 4 * Math.sin(t / 17)),
        iExcessThreshold: 80,
        mExcessEmaPeak: Math.round(11 + 4 * Math.sin(t / 17)),
        iExcessThreshMin: 75,
        WifiHeartBeat: (window._demoHeartbeat = (window._demoHeartbeat || 0) + 1),
    };
    const v1 = CSV1_FIELDS.map(k => csv1[k] !== undefined ? csv1[k] : 0);
    const csvHandler = window._csvDataHandler;
    if (csvHandler) {
        csvHandler({ data: v1.length + ',' + v1.join(',') });
    }

    // CSV2 rides its real ~5 s cadence (SOC + peaks for the header/battery panes);
    // at 200 ms it would spam the heavier CSV2-side renderers.
    const csv2Handler = window._csv2DataHandler;
    if (csv2Handler && (!window._demoLastCsv2 || Date.now() - window._demoLastCsv2 >= 5000)) {
        window._demoLastCsv2 = Date.now();
        const csv2 = {
            IBVMax: 1452,
            MeasuredAmpsMax: 9100,
            RPMMax: 3450,
            SOC_percent: Math.round((76 + 2 * Math.sin(t / 240)) * 100),
            EngineRunTime: 19800,
            temperatureThermistor: 92,   // board temp, raw °F
            MaxTemperatureThermistor: 118,
        };
        const v2 = CSV2_FIELDS.map(k => csv2[k] !== undefined ? csv2[k] : 0);
        csv2Handler({ data: v2.length + ',' + v2.join(',') });
    }
}


function checkForDemoMode() {
    // First check 10 s after load, then re-arm every 3 s until a verdict: real data
    // (never demo), demo enabled, or user chose Continue Offline. CONNECTING is NOT
    // a demo trigger — slow-WiFi users can sit in CONNECTING for many seconds, and
    // tripping demo on that state once pinned a permanent demo banner over real
    // data — but it only DEFERS the check, never disarms it: after a failed scan
    // the SSE retries http://alternator.local and lives in CONNECTING, so a
    // one-shot check never fired demo on any WiFi network without the device
    // (App Review phones are exactly that). Past 30 s with zero packets ever,
    // CONNECTING stops deferring — that long with no open is a dead address, not
    // a slow join.
    const t0 = performance.now();
    const check = () => {
        if (window._firstCsvPacketReceived || DEMO_MODE || isOfflineMode) return;
        const patient = performance.now() - t0 < 30000;
        const st = source ? source.readyState : EventSource.CLOSED;
        if (discoveryInProgress || st === EventSource.OPEN || (st === EventSource.CONNECTING && patient)) {
            // A /24 sweep can outlast the 10 s grace — demo mode must not win
            // the race against a discovery that's about to find the device.
            setTrackedTimeout(check, 3000);
            return;
        }
        // No live SSE. no-cors probe of the AP gateway distinguishes "on the setup
        // hotspot mid-provisioning" (show the browser hint) from "no device at
        // all" (App Review — MUST still get demo mode).
        fetchWithTimeout('http://192.168.4.1/', { mode: 'no-cors' }, 2500)
            .then(() => showHotspotSetupHint())
            .catch(() => {
                // Re-test after the 2.5 s probe window — a connection may have landed mid-probe.
                if (window._firstCsvPacketReceived || DEMO_MODE || isOfflineMode) return;
                console.log('[DEMO MODE] No ESP32 detected - enabling demo mode');
                enableDemoMode();
            });
    };
    setTimeout(check, 10000);
}

function showHotspotSetupHint() {
    if (document.getElementById('hotspot-hint-banner')) return;
    hideWaitingForRegulator();
    const banner = document.createElement('div');
    banner.id = 'hotspot-hint-banner';
    banner.style.cssText = 'position:fixed;top:0;left:0;right:0;background:#0a84ff;color:#fff;padding:calc(12px + env(safe-area-inset-top)) 14px 12px;text-align:center;z-index:10000;font-weight:600;font-size:14px;line-height:1.45;';
    banner.innerHTML = "Connected to the regulator's setup hotspot. Open <b>192.168.4.1</b> in your browser to enter your boat's WiFi, then reopen this app.";
    document.body.insertBefore(banner, document.body.firstChild);
    document.body.style.paddingTop = 'calc(72px + env(safe-area-inset-top))';
}

