async function handleVesselInfoSave(event) {
    event.preventDefault();

    const form = document.getElementById('vessel-info-form');
    const messageDiv = document.getElementById('vessel-info-message');

    const selectedOrientation = form.querySelector('input[name="imuMountOrientation"]:checked');
    if (!selectedOrientation) {
        xAlert('Please select a mounting orientation');
        return;
    }
    const selectedMountLoc = form.querySelector('input[name="regulatorMountLoc"]:checked');
    if (!selectedMountLoc) {
        xAlert('Please select where the regulator is mounted');
        return;
    }

    const vesselData = {
        regulator_name: form.REGULATOR_NAME ? form.REGULATOR_NAME.value.trim() : '',
        boat_length_ft: parseFloat(form.BOAT_LENGTH_FT.value),
        boat_displacement_lbs: parseFloat(form.BOAT_DISPLACEMENT_LBS.value),
        boat_type: form.BOAT_TYPE.value,
        boat_make_model: form.BOAT_MAKE_MODEL.value,
        boat_year: parseInt(form.BOAT_YEAR.value),
        home_port: form.HOME_PORT.value,
        engine_make: form.ENGINE_MAKE.value,
        engine_hp: parseInt(form.ENGINE_HP.value),
        battery_voltage: parseInt(form.BATTERY_VOLTAGE.value),
        battery_capacity_ah: parseInt(form.BATTERY_CAPACITY_AH.value),
        battery_type: form.BATTERY_TYPE.value,
        battery_make_model: form.BATTERY_MAKE_MODEL.value,
        alternator_brand_model: form.ALTERNATOR_BRAND_MODEL.value,
        solar_watts: parseInt(form.SOLAR_WATTS.value),
        imu_mount_orientation: parseInt(selectedOrientation.value),
        regulator_mount_loc: parseInt(selectedMountLoc.value),
        imu_dist_bow_ft: parseFloat(form.IMU_DIST_BOW_FT.value),
        imu_dist_cl_ft: parseFloat(form.IMU_DIST_CL_FT.value),
        imu_height_wl_ft: parseFloat(form.IMU_HEIGHT_WL_FT.value)
    };

    // If the user changed system voltage, warn before saving — /saveVesselInfo rescales the whole
    // charge-voltage profile + hard-shutdown trip for the new class. Cancelling aborts the save.
    const _oldV = parseInt(window._nominalStored, 10);
    const _newV = vesselData.battery_voltage;
    const _classOk = v => v === 12 || v === 24 || v === 36 || v === 48;
    if (_classOk(_newV) && _classOk(_oldV)
        && _newV !== _oldV && !(await confirmVoltageRescale(_oldV, _newV))) {
        return;  // user cancelled — leave the form unsaved
    }

    messageDiv.style.display = 'block';
    messageDiv.style.backgroundColor = '#e3f2fd';
    messageDiv.style.color = '#1976d2';
    messageDiv.textContent = 'Saving vessel info...';

    try {
        const formData = new FormData();
        formData.append('vesselData', JSON.stringify(vesselData));

        const response = await fetchWithTimeout(buildURL('/saveVesselInfo'), {
            method: 'POST',
            body: formData
        }, 8000);

        if (!response.ok) throw new Error(`HTTP ${response.status}`);

        const result = await response.json();

        if (result.success) {
            // Battery-defaults populator baseline: what the device had on file BEFORE this save
            const _prevBatt = window.vesselInfo ? {
                type: window.vesselInfo.battery_type || '',
                cap: Number(window.vesselInfo.battery_capacity_ah),
                volt: Number(window.vesselInfo.battery_voltage)
            } : null;
            const _prevOrient = (window.vesselInfo && window.vesselInfo.imu_mount_orientation !== undefined)
                ? Number(window.vesselInfo.imu_mount_orientation) : null;
            window.vesselInfo = vesselData;
            // Re-read identity rather than trusting the submitted string: a cleared name falls
            // back to the unit's own XREG-<id>, which only the device can tell us.
            probeIdentify(API_BASE_URL || '', 4000).then(h => { if (h) applyConnectedIdentity(h); });
            window._nominalStored = vesselData.battery_voltage;  // new baseline for the next change/warning
            applyClassScaledInputAttrs();
            updateBattHealthChemNote();  // chemistry may have just changed
            vesselInfoComplete = true;
            setVesselButtonUpdateMode();  // first save → becomes "Update Vessel Info" + tooltip

            messageDiv.style.backgroundColor = '#e8f5e9';
            messageDiv.style.color = '#2e7d32';
            messageDiv.textContent = 'Vessel info saved successfully! You can now access other tabs.';

            // Update dual-control echoes immediately
            updateEchoIfChanged('SolarWatts_echo', vesselData.solar_watts);
            updateEchoIfChanged('BatteryCapacity_Ah_echo', vesselData.battery_capacity_ah);

            // Orientation changed on an existing profile → the stored level reference was captured
            // in the old orientation and no longer applies. Remind, then run the other popups in
            // sequence (each waits for the previous to close — never stacked).
            const _orientChanged = _prevOrient !== null && isFinite(_prevOrient)
                && _prevOrient !== vesselData.imu_mount_orientation;
            // A ✕-dismiss from a pre-flash session lives in sessionStorage and would mute a
            // factory-fresh device's popup in a reused tab — a true first save re-arms it.
            if (result.firstSave === true) sessionStorage.removeItem('socSeedDismissed');
            // First install only: true once Next is pressed on the Commissioning Prerequisites screen. ✕,
            // "I'll do this later" and a failed config read leave it false — no wizard — but the rest of
            // the chain still runs.
            let _goWizard = false;
            (_orientChanged
                ? xAlert('Because the mounting orientation changed, the saved level reference (Level offsets) no longer matches how the device sits, and heel/pitch will read wrong until it is recaptured.\n\nWith the boat sitting level, press Zero Now in the Vessel Info section to re-zero.', 'Re-do Level Offsets')
                : Promise.resolve())
                // First install: describe the hardware BEFORE anything is recommended from it — Before You
                // Start, then Commissioning Prerequisites (sensor roles, shunt). The battery-defaults proposal
                // below reads battTempProbeEnable from its own /exportConfig, so it sees the Prerequisites
                // writes (one awaited /get in commPrepFinish) with no extra plumbing. The screen's handoff to
                // Charge Rate Limits is deferred to the tail of this chain. Guarded so a failure here never
                // blocks the save result.
                .then(() => { if (result.firstSave === true) return maybeShowCommPrereqs().then(go => { _goWizard = go === true; }).catch(() => { }); })
                // async, never blocks the save result. On a first install the Prerequisites screen has just
                // closed, so the wait box covers the populator's own /exportConfig read (~1-2 s of device time).
                .then(() => { if (result.firstSave === true) vesselNextStepWait(true); return maybeProposeBatteryDefaults(vesselData, _prevBatt, result.firstSave === true); })
                // Factory-fresh device: the firmware runs its deferred SoC seed on Core 1 some time
                // after this save responds, so poll /socseed until the snapshot lands (a single
                // fixed delay raced the Core-1 write and could miss the popup forever). Show it and
                // WAIT for the user to close it BEFORE commissioning: the wizard opens the commission
                // modal and socSeedMaybeAutoOpen suppresses itself over that modal, so a SoC popup
                // deferred until after the wizard opened would never appear this session.
                .then(async () => {
                    if (result.firstSave === true) vesselNextStepWait(true);
                    for (let i = 0; i < 6; i++) {
                        if (i) await new Promise(res => setTimeout(res, 1000));   // check before sleeping: a snapshot already on file costs nothing
                        _socSeedData = null;
                        await socSeedFetch();
                        if (_socSeedData && _socSeedData.snap) break;
                    }
                    vesselNextStepWait(false);
                    if (_socSeedData && _socSeedData.snap && !_socSeedData.ack && !sessionStorage.getItem('socSeedDismissed')) {
                        await new Promise(res => { _socSeedResolve = res; socSeedOpen(); });
                    }
                })
                // First save only: one-time heads-up that the device restarts itself for maintenance.
                .then(() => { if (result.firstSave === true) return maintAckShow(); })
                // First save only, Next was pressed on Prerequisites: Charge Rate Limits → tach alignment →
                // wizard, the same handoff commPrepFinish makes itself on a re-commission. ← Back reopens
                // Prerequisites, whose Next then hands off immediately (the deferral was consumed above).
                .then(() => { if (_goWizard) { vesselNextStepWait(true); openRpmCap(openRpmAlign, commPrepReopen); } })
                // Tail of the chain, never stacked: firmware just set the change flag if voltage/capacity/
                // chemistry moved. No-op on a first save (no finished pass to invalidate).
                .then(() => checkRecommissionPrompt().catch(() => { }));

        } else {
            throw new Error(result.error || 'Save failed');
        }

    } catch (error) {
        messageDiv.style.backgroundColor = '#ffebee';
        messageDiv.style.color = '#c62828';
        messageDiv.textContent = 'Error: ' + error.message;
    }
}

// ===== Battery-defaults populator =====
// After a Vessel Info save that sets or changes battery type / capacity / system voltage,
// propose chemistry-appropriate starting values for the charge-stage and protection settings
// and show them in a Now → Proposed modal with per-row apply checkboxes. Never applies
// silently; every setting stays individually editable afterward. Bulk/Absorption proposals
// are deliberately conservative (lifetime over capacity) and the summary tells the user to
// verify against the manufacturer's data sheet. Type "other" skips the whole pass.

// Compile-time firmware defaults in UI units — fallback "Now" when a key is absent from /exportConfig.
// MUST track the global initialisers in Xregulator.ino; 16 of these had drifted away from the
// firmware, so a fresh device with an unwritten key showed a fabricated "Now" and mis-flagged the
// row as changed. Voltage/current entries are the 12 V seeds — InitSystemSettings multiplies them
// by seedVScale for a 24/36/48 V bank, so this fallback is only exact at 12 V.
const BATTDEF_FW_DEFAULT = {
    BulkVoltage: 13.9, AbsorptionVoltage: 13.9,
    UseFloat: 0, FloatVoltage: 13.6, FLOAT_DURATION: 8, RebulkVoltage: 13.1, RebulkCurrent_A: 10,
    SOC_BlockRebulk_percent: 90, SOC_AllowRebulk_percent: 80, TailCurrent_A: 10, TailCurrent: 5,
    ChargedVoltage: 13.8, BattCurrentLimitA: 100, MaximumAllowedBatteryAmps: 125,
    coldChargeLockoutEnable: 1, battTempDerateEnable: 1, hotChargeLockoutEnable: 0, MaxChargeTempF: 122,
    PeukertExponent: 1.05, ChargeEfficiency: 99,
    AbsorptionTimeoutMs: 45,
    VoltageAlarmHigh: 14.8, VoltageAlarmLow: 11.9, SocAlarmLow: 10, AlternatorHardShutdownV: 14.2,
    VoltageHardwareLimit: 14.3, OvTierLoMarginV: 0.10, OvTierMidMarginV: 0.20, OvMeasMarginV: 0.10,
    IExcessCeilA: 20,
    capSocLowMax: 20, capMinSpan: 70, capRestFloor: 30, capSettleRate: 2.0, bhStepLowA: 30, bhStepDeltaA: 30,
    CvKdDeadbandVps: 0.4, CvKdArmV: 0.5, CvKdTd: 0.85,
    vTgtRampUp: 0.15, vTgtRampDn: 0.15,
    cvAlpha: 0.05, cvPiZero: 0.5
};
// Stored NVS string → UI units (everything else is stored in UI units already)
const BATTDEF_FROM_STORED = {
    FLOAT_DURATION: v => v / 3600,      // seconds → hours
    ChargedVoltage: v => v / 100,       // V×100 → V
    PeukertExponent: v => v / 100,      // ×100 → exponent
    AbsorptionTimeoutMs: v => v / 60000 // ms → minutes
};
const BATTDEF_MODE_NAMES = ['No Float (idle)', 'Voltage Float', 'Zero-Current Float'];
// Per-chemistry rationale shown under the proposal summary. Framed around what each battery wants —
// these are battery-specific recommendations, NOT alternator limits (the alternator has its own).
// Each entry is a fn of the copy context built by deriveBatteryDefaults() (class-scaled bulk and
// hard-cut volts, their per-cell equivalents, cell count, and the derived current limit in amps),
// so the cited numbers match 12/24/36/48 V banks. Per-cell figures are printed alongside every
// voltage: the bus number moves with the class, the per-cell number never does, and per-cell is the
// form an owner checks against a data sheet. limA is 0 when bank capacity is unknown — every
// amp figure has to drop out with it. An owner sees exactly ONE of these three, chosen by battery
// type, so no paragraph may lean on a comparison with another chemistry.
const BATTDEF_CEILING_COPY = d => 'The hard overvoltage cut is set to ' + d.hard + ' V (' + d.hardCell + ' V per cell across ' + d.cells
    + ' cells): brief voltage excursions do not harm a lead-acid battery (its damage mechanisms accumulate over minutes to years), '
    + 'so rather than cut the field on momentary spikes, the ceiling is placed where the connected DC equipment \u2014 not the battery \u2014 '
    + 'becomes the limiting factor. Check it against the lowest maximum input voltage of anything sharing the bus, and lower it if '
    + 'something is rated below ' + d.hard + ' V.';
const BATTDEF_CHEM_COPY = {
    lifepo4: d => 'For lithium (LiFePO4), the charge current limit is set to a moderate fraction of the bank\'s capacity'
        + (d.limA ? ' (' + d.limA + ' A for this bank)' : '')
        + '. The cells will take considerably more; raise it if you prioritize charging time over battery lifetime. '
        + 'Bulk and Absorption are set to ' + d.bulk + ' V (' + d.bulkCell + ' V per cell across ' + d.cells + ' cells) \u2014 roughly a '
        + 'high-90s% state of charge, which avoids the higher-voltage cell stress of a full charge. Float is disabled: a full LiFePO4 bank '
        + 'wants the charge source to step aside rather than hold a setpoint. Unlike lead-acid and AGM, LiFePO4 does not want its charge '
        + 'voltage moved with temperature \u2014 what it will not tolerate is being charged below freezing at all. The hard overvoltage cut '
        + 'is set to ' + d.hard + ' V (' + d.hardCell + ' V per cell across ' + d.cells + ' cells), only ' + d.delta + ' V above the charge '
        + 'target: on lithium the hazard is not slow cell damage but the battery\'s protection circuit (BMS) opening while the alternator is '
        + 'charging, so the ceiling is placed to catch a runaway before the BMS does.',
    agm: d => 'For AGM, the default charge current limit is set to a high fraction of the bank\'s capacity'
        + (d.limA ? ' (' + d.limA + ' A for this bank)' : '')
        + ': a high charge rate reduces sulfation and extends AGM cycle life, and AGM cells accept high in-rush current. The charge voltages '
        + 'are kept toward the lower end of the acceptable range to limit cell stress \u2014 ' + d.bulk + ' V is ' + d.bulkCell + ' V per cell '
        + 'across ' + d.cells + ' cells. Lead-acid and AGM batteries also want a higher charge voltage when cold and a lower one when hot. '
        + BATTDEF_CEILING_COPY(d),
    lead_acid: d => 'For flooded lead-acid, the absorption voltage (' + d.bulk + ' V, ' + d.bulkCell + ' V per cell across ' + d.cells + ' cells)'
        + ' and charge current' + (d.limA ? ' (' + d.limA + ' A for this bank)' : '')
        + ' are set on the higher side to keep the cells fully charged and the electrolyte mixed. This errs toward reduced sulfation at the '
        + 'cost of higher water use \u2014 check the electrolyte level regularly and top up with distilled water, as a bank charged this way '
        + 'will need watering more often. Lead-acid and AGM batteries also want a higher charge voltage when cold and a lower one when hot. '
        + BATTDEF_CEILING_COPY(d)
};

// Notice tiers for the battdef modal, severity carried by the header colour: warn = doing this
// destroys the battery, limit = the regulator cannot do this yet, info = why a proposed value
// differs from the plain recommendation. Glyphs are geometric shapes (U+25B2/U+25B3), never the
// emoji-presentation "‼" — iOS renders that in colour.
const BATTDEF_NOTICE_TIER = {
    warn:  { glyph: '▲', border: 'rgba(252,165,165,0.32)', bg: 'rgba(252,165,165,0.055)', hdBg: 'rgba(252,165,165,0.09)',  fg: '#fca5a5' },
    limit: { glyph: '△', border: 'rgba(230,162,60,0.30)',  bg: 'rgba(230,162,60,0.05)',   hdBg: 'rgba(230,162,60,0.085)',  fg: '#e6a23c' },
    info:  { glyph: 'i',      border: 'rgba(255,255,255,0.12)', bg: 'rgba(255,255,255,0.028)', hdBg: 'rgba(255,255,255,0.045)', fg: '#9aa8a8' }
};
// Inline-styled like the rest of the dark modal shell — styles.css is theme-aware and must not
// reach in here. Titles are written sentence-case; the header uppercases them.
function battDefNotice(tier, title, body) {
    const t = BATTDEF_NOTICE_TIER[tier];
    return '<div style="border:1px solid ' + t.border + '; background:' + t.bg + '; border-radius:6px; margin:0 0 10px; overflow:hidden;">'
        + '<div style="display:flex; align-items:center; gap:7px; padding:6px 10px; background:' + t.hdBg + '; color:' + t.fg
        + '; font-size:10.5px; font-weight:700; letter-spacing:0.07em; text-transform:uppercase;">'
        + '<span style="font-size:11px;">' + t.glyph + '</span>' + title + '</div>'
        + '<div style="padding:6px 10px 9px; font-size:0.86em; line-height:1.5; color:#b9b9b9;">' + body + '</div></div>';
}

// Per-chemistry Battery Health capacity-trend tuning. 12V-referenced rested open-circuit-voltage
// curves at the fixed SoC breakpoints {100,90,80,60,40,30,20,15,10,5,0}; firmware scales by
// SYSTEM_VOLTAGE_CLASS/12 at lookup, so these are entered as 12V values regardless of system voltage.
// Firmware loads the chemistry-matched curve into capOcvVolt[] at commissioning (applyChemistryOcvPreset,
// 8_functions.ino), so these presets drive BOTH the SoC seed and the capacity anchor; AGM rests slightly
// above lead-acid. The anchor window differs because lead-acid/AGM voltage maps to SoC across the whole
// range (anchor can sit at a shallow, non-damaging rest), while flat LiFePO4 only reads reliably at the bottom knee.
const CAP_OCV_PRESETS = {
    lifepo4:   [13.60, 13.40, 13.30, 13.20, 13.10, 13.00, 12.90, 12.80, 12.50, 12.00, 10.00],
    agm:       [12.85, 12.70, 12.55, 12.35, 12.15, 12.05, 11.90, 11.80, 11.70, 11.60, 11.50],
    lead_acid: [12.70, 12.50, 12.40, 12.20, 12.00, 11.90, 11.80, 11.73, 11.65, 11.55, 11.40]
};
// restFloor = minutes at rest before the OCV is trusted (Battery University BU-903: lithium ~90 min,
// lead-acid ≥4 h for surface charge to dissipate; AGM recombines a bit faster). settleRate = the
// dV/dt "stopped moving" gate in mV/10min, ANDed with restFloor. LiFePO4 settles fast so hold it tight
// (2); lead-acid/AGM surface charge lingers, so loosen to ~3.5 — their OCV curve is steep at the anchor
// SoC, so a looser voltage gate costs negligible SoC accuracy but lets a point actually capture.
const CAP_CHEM_ANCHOR = {
    lifepo4:   { lowMax: 20, span: 70, restFloor: 90,  settleRate: 2.0 },   // bottom knee only, deep cycle (flat mid-curve)
    agm:       { lowMax: 50, span: 40, restFloor: 180, settleRate: 3.5 },
    lead_acid: { lowMax: 50, span: 40, restFloor: 240, settleRate: 3.5 }
};

// OCV curves compare element-wise with tolerance so 2- vs 3-decimal storage never reads as "changed".
function ocvBlobsEqual(a, b) {
    const pa = String(a).split(',').map(Number), pb = String(b).split(',').map(Number);
    if (pa.length !== pb.length || pa.length === 0) return false;
    for (let i = 0; i < pa.length; i++) {
        if (!isFinite(pa[i]) || !isFinite(pb[i]) || Math.abs(pa[i] - pb[i]) > 0.005) return false;
    }
    return true;
}

function deriveBatteryDefaults(type, capAh, sysV, mountLoc, battProbe) {
    // bulkV/absV lean gentle for stress/lifetime: LiFePO4 13.9 V ≈ high-90s% SoC well below 14.4+;
    // AGM at 14.4; flooded higher (14.6) because it needs the extra to counter stratification and its
    // dominant killer is UNDERcharge (sulfation), not overcharge. limC is the opposite philosophy: high
    // charge current REDUCES sulfation and lengthens life, so AGM is 1.0C (quality AGM cells tolerate several-C in-rush).
    // Flooded stays 0.20C — it genuinely gasses and heats. These are battery-specific; the alternator's
    // own current ceiling is a separate limit.
    const T = {
        // Lithium vAlmHi 14.4: the external-source tripwire sounds ABOVE the whole cut ladder
        // (hardware rung 14.3) but BELOW the BMS trip floor (~14.5) — an external charger
        // overdriving the bank alarms before any BMS acts. AGM/lead keep 15.8, below their own
        // 15.9/16.0 cuts (approach alarm; no BMS race there) — deliberate, don't "fix".
        lifepo4:   { bulkV: 13.9, absV: 13.9, floatV: null, durH: null, rebulkV: 13.1, socBlock: 90, socAllow: 80, tailC: 0.05, tailPct: 5, chgDetV: 13.8, limC: 0.50, cold: 1, hot: 1, hotF: 113, peukert: 1.05, chgEff: 99, vAlmHi: 14.4, vAlmLo: 11.9, socAlm: 10, absBase: 30, absMax: 45,  ovMeasMargin: 0.1 },
        agm:       { bulkV: 14.4, absV: 14.4, floatV: 13.6, durH: 8,    rebulkV: 12.5, socBlock: 97, socAllow: 90, tailC: 0.02, tailPct: 2, chgDetV: 14.2, limC: 1.00, cold: 0, hot: 0, hotF: 122, peukert: 1.10, chgEff: 93, vAlmHi: 15.8, vAlmLo: 11.8, socAlm: 40, absBase: 60, absMax: 180, ovMeasMargin: 0.5 },
        lead_acid: { bulkV: 14.6, absV: 14.6, floatV: 13.4, durH: 8,    rebulkV: 12.4, socBlock: 97, socAllow: 90, tailC: 0.02, tailPct: 2, chgDetV: 14.3, limC: 0.20, cold: 0, hot: 0, hotF: 122, peukert: 1.25, chgEff: 88, vAlmHi: 15.8, vAlmLo: 11.5, socAlm: 40, absBase: 90, absMax: 240, ovMeasMargin: 0.5 }
    }[type];
    if (!T) return null;
    const kV = (isFinite(sysV) && sysV > 0) ? sysV / 12 : 1;   // 12V-equivalent voltages scale by class
    const C = (isFinite(capAh) && capAh > 0) ? capAh : 0;
    const r1 = v => Math.round(v * 10) / 10, r2 = v => Math.round(v * 100) / 100;
    // Lithium proposal is No Float: a full LFP bank wants the charge source to step aside, not hold
    // a setpoint. Zero-Current Float stays available in Setup for owners who want house loads carried.
    const useFloat = (type === 'lifepo4') ? 0 : 1;

    const rows = [];
    rows.push({ param: 'BulkVoltage', label: 'Bulk Voltage (V)', value: r2(T.bulkV * kV) });
    rows.push({ param: 'AbsorptionVoltage', label: 'Absorption Voltage (V)', value: r2(T.absV * kV) });
    // Without a shunt this timer is the SOLE thing ending absorption (tail current is unmeasurable), so
    // scale it with bank size — linear in Ah off a per-chemistry base, clamped [15, T.absMax] min.
    if (C) rows.push({ param: 'AbsorptionTimeoutMs', label: 'Absorption Timeout (min)', value: Math.min(T.absMax, Math.max(15, Math.round(T.absBase * C / 100))) });
    rows.push({ param: 'UseFloat', label: 'Float Mode', value: useFloat, show: v => BATTDEF_MODE_NAMES[v] || v });
    if (useFloat === 1) {   // FloatVoltage/FLOAT_DURATION are inert in idle and zero-current modes
        rows.push({ param: 'FloatVoltage', label: 'Float Voltage (V)', value: r2(T.floatV * kV) });
        rows.push({ param: 'FLOAT_DURATION', label: 'Float Duration (hrs)', value: T.durH });
    }
    rows.push({ param: 'RebulkVoltage', label: 'Rebulk Voltage (V)', value: r2(T.rebulkV * kV) });
    if (C) rows.push({ param: 'RebulkCurrent_A', label: 'Rebulk Current Threshold (A)', value: r1(C / 20) });
    rows.push({ param: 'SOC_BlockRebulk_percent', label: 'SoC Block Rebulk Above (%)', value: T.socBlock });
    rows.push({ param: 'SOC_AllowRebulk_percent', label: 'SoC Allow Rebulk Below (%)', value: T.socAllow });
    if (C) {
        const lim = r1(T.limC * C);   // /get handler clamp widened to 2000 A, so no mirror cap here
        rows.push({ param: 'TailCurrent_A', label: 'Tail Current (A)', value: r1(T.tailC * C) });
        rows.push({ param: 'BattCurrentLimitA', label: 'Battery Charge Current Limit (A)', value: lim });
        rows.push({ param: 'MaximumAllowedBatteryAmps', label: 'High Current Alarm (Battery) (A)', value: Math.round(1.25 * lim) });
    }
    rows.push({ param: 'ChargedVoltage', label: 'Max Charge Detection Voltage (V)', value: r2(T.chgDetV * kV) });
    rows.push({ param: 'TailCurrent', label: 'Max Charge Detection Tail Current (%)', value: T.tailPct });
    // Over-voltage ladder, chained top-down from the battery's BMS charge-disconnect voltage.
    // Lithium: the hardware (INA228) rung sits 0.2 V x class below the surveyed BMS trip floor —
    // BMS trips compare the HIGHEST cell while we regulate pack voltage, so the pack-referred
    // margin must cover imbalance; the software instant cut rides 0.1 x class under it so software
    // always acts before the electrical backstop. AGM/flooded: no BMS in the picture — lead-acid
    // damage is time-integrated, indifferent to brief bounded spikes, so the ceiling protects the
    // DC loads' published continuous ratings instead of the battery. The timed-tier trip lines
    // fit between the shed line and the software cut. Per PROTECTION_TIMING_OVERHAUL_SPEC the LOW tier
    // RIDES the Group 2 shed line rather than sitting above it, which is why lithium reads 0.10/0.10/0.20:
    // its shed-to-software-cut corridor is only 0.1 V wide, so there is nowhere above the shed line to put
    // LOW. Lead/AGM has a 5.1 V corridor, so its tiers do sit 0.1/0.2 clear of the 0.50 shed margin.
    // Lithium scales linearly because its rung IS per-cell: the BMS trips on the highest cell while we
    // regulate the pack sum, so the pack-referred imbalance allowance really is N x the per-cell offset
    // (a 50 mV outlier eats 0.75 V at 16S vs 0.15 V at 4S). The lead/AGM ceiling is the opposite — a DC
    // LOAD rating, class-invariant in kind — so it stops scaling at the equipment: 16.0 x 4 = 64 V on a
    // 48 V bank, above the ~60 V ceiling of most 48 V gear.
    const hwLimit = (type === 'lifepo4') ? 14.3 * kV : Math.min(16.0 * kV, 60);
    const hardSD = hwLimit - 0.1 * kV;
    // The three target-relative rungs are per-cell and scale, but a capped ceiling can leave no room for
    // them: 48 V flooded at 2.43 V/cell would put MID at 61.2 V under a 60 V cap. Compress all three by
    // one factor so MID lands just under the software cut, rather than proposing a ladder that cannot fit.
    // No-ops at 12/24/36 V on every chemistry — only 48 V lead has a corridor short enough to bind.
    let shedM = T.ovMeasMargin * kV;
    let loM = ((type === 'lifepo4') ? 0.10 : 0.60) * kV;
    let midM = ((type === 'lifepo4') ? 0.20 : 0.70) * kV;
    const midRoom = hardSD - 0.05 * kV - T.bulkV * kV;
    if (midRoom > 0 && midM > midRoom) {
        const squeeze = midRoom / midM;
        shedM *= squeeze; loM *= squeeze; midM *= squeeze;
    }
    rows.push({ param: 'VoltageHardwareLimit', label: 'Hardware Shutdown Voltage (V)', value: r2(hwLimit) });
    rows.push({ param: 'AlternatorHardShutdownV', label: 'Alternator Hard Shutdown Voltage (V)', value: r2(hardSD) });
    rows.push({ param: 'OvTierLoMarginV', label: 'Timed OV Cut LOW — Margin Above Target (V)', value: r2(loM) });
    rows.push({ param: 'OvTierMidMarginV', label: 'Timed OV Cut MID — Margin Above Target (V)', value: r2(midM) });
    rows.push({ param: 'OvMeasMarginV', label: 'Soft OV Trip Margin Above Target (V)', value: r2(shedM) });
    // Flat 20 A for every chemistry and bank size; commissioning later raises it to 40 A for lead-acid/AGM.
    rows.push({ param: 'IExcessCeilA', label: 'Over-Current Trip Ceiling (Alternator) (A)', value: 20 });
    rows.push({ param: 'VoltageAlarmHigh', label: 'High Voltage Alarm (V)', value: r2(T.vAlmHi * kV) });
    rows.push({ param: 'VoltageAlarmLow', label: 'Low Voltage Alarm (V)', value: r2(T.vAlmLo * kV) });
    rows.push({ param: 'SocAlarmLow', label: 'Low State of Charge Alarm (%)', value: T.socAlm });
    rows.push({ param: 'coldChargeLockoutEnable', label: 'Cold-Charge Lockout', value: T.cold, show: v => v ? 'On' : 'Off' });
    // With a battery probe the derate reads the battery itself, so it is On wherever the regulator sits,
    // and the hot lockout has a measurement to act on (it never acts on the board stand-in). Without a
    // probe the board stands in, and an engine-room board temp is not a battery proxy — it reads hot
    // while the bank is still cold, which would push the gains UP exactly when the plant is stiffest.
    // Off beats a proxy that inverts.
    if (battProbe === 1) {
        rows.push({ param: 'battTempDerateEnable', label: 'Battery-Temp Gain Derate', value: 1, show: v => v ? 'On' : 'Off' });
        rows.push({ param: 'hotChargeLockoutEnable', label: 'Hot-Charge Lockout', value: T.hot, show: v => v ? 'On' : 'Off' });
        rows.push({ param: 'MaxChargeTempF', label: 'Max Charge Temp (' + tempUnitLabel() + ')', value: T.hotF, show: v => String(Math.round(toDisplayTemp(v))) });
    } else if (mountLoc === 0 || mountLoc === 1) {
        rows.push({ param: 'battTempDerateEnable', label: 'Battery-Temp Gain Derate', value: mountLoc === 0 ? 1 : 0, show: v => v ? 'On' : 'Off' });
    }
    rows.push({ param: 'PeukertExponent', label: 'Peukert Exponent', value: T.peukert });
    rows.push({ param: 'ChargeEfficiency', label: 'Charge Efficiency (%)', value: T.chgEff });

    // Battery Health — capacity trend anchoring (chemistry-specific) + DCIR step (bank-sized)
    const anchor = CAP_CHEM_ANCHOR[type];
    if (anchor && CAP_OCV_PRESETS[type]) {
        const presetLabel = { lifepo4: 'LiFePO4 curve', agm: 'AGM curve', lead_acid: 'Lead-Acid curve' }[type];
        const ocvBlob = CAP_OCV_PRESETS[type].map(v => v.toFixed(3)).join(',');
        rows.push({ param: 'capOcv', label: 'Rested-Voltage Curve (Capacity Trend)', value: ocvBlob, blob: true,
                    show: v => (v === ocvBlob ? presetLabel : (v ? 'current curve' : 'not set')) });
        rows.push({ param: 'capSocLowMax', label: 'Capacity Anchor — Sample At or Below (%)', value: anchor.lowMax });
        rows.push({ param: 'capMinSpan', label: 'Capacity Anchor — Minimum Span (%)', value: anchor.span });
        rows.push({ param: 'capRestFloor', label: 'Capacity Anchor — Rest Before OCV Trusted (min)', value: anchor.restFloor });
        rows.push({ param: 'capSettleRate', label: 'Capacity Anchor — Voltage Settle Rate (mV/10min)', value: r2(anchor.settleRate * kV) });  // mV/10min is volt-domain: real per-bus, like the firmware seed/rescale
    }
    if (C) {   // DCIR step ~C/4, clamped, so a small bank isn't pulsed at the fixed 30-60 A (crest = 2x low)
        const step = Math.min(30, Math.max(10, Math.round(C / 4)));
        rows.push({ param: 'bhStepLowA', label: 'Resistance Test — Step Low (A)', value: step });
        rows.push({ param: 'bhStepDeltaA', label: 'Resistance Test — Step Delta (A)', value: step });
    }

    // Voltage D term — only the two params that actually vary with bank voltage are proposed here (V/s
    // and V thresholds, × class). Kd (voltage-normalized 12 V-equivalent), the back-off cap (flat amps),
    // the voltage filter (ms) and the mode (one-sided vs two-sided) are universal — one value works on
    // every bank, so like Kp/Ki they are not proposed here; they live in Setup → Voltage. These match the server rescale
    // (×class) exactly, so on a voltage-class change a defaults bank reads back as "matches".
    // CvKdDeadbandVps is a SAFETY MARGIN, not a threshold: commissioning's Step-5 ripple fit measures the
    // real threshold and this rides on top of it; 0.4×class here is only the pre-commissioning fallback.
    rows.push({ param: 'CvKdDeadbandVps', label: 'Voltage-Rise Tolerance — Safety Margin (V/s)', value: r2(0.4 * kV) });
    // 0.5 matches the Xregulator.ino CvKdArmV seed — kept tight so D stays off the sag-recovery climb
    // (1.25 armed the D brake 1.25 V early on OV-recovery climbs and chopped the recovering field).
    rows.push({ param: 'CvKdArmV', label: 'Voltage D Term — Arm Window Below Target (V)', value: r2(0.5 * kV) });

    // Setpoint slew is a per-bank V/s rate, so like the D-term thresholds it scales × class (0.15 V/s on 12V
    // rides as 0.30 on 24V / 0.45 on 36V / 0.60 on 48V). 12V base 0.15 matches the firmware initializer's seedVScale seed.
    rows.push({ param: 'vTgtRampUp', label: 'Voltage Setpoint — Rise Rate (V/s)', value: r2(0.15 * kV) });
    rows.push({ param: 'vTgtRampDn', label: 'Voltage Setpoint — Fall Rate (V/s)', value: r2(0.15 * kV) });

    // α doubles on LiFePO4 (stiff plant → tiny post-event errors; P/I must double for usable
    // regulation/recovery pace) while Td halves so the effective D gain Kd = Td·Kp stays constant —
    // surplus D authority against a locally-stiff plant is a documented failure mode ("sub-ceiling
    // relay", CV_Loop_Dev_Summary.md 07-21). ρ stays chemistry-independent.
    const isLfp = (type === 'lifepo4');
    rows.push({ param: 'cvAlpha', label: 'Voltage Loop Aggressiveness (α)', value: isLfp ? 0.10 : 0.05 });
    rows.push({ param: 'CvKdTd', label: 'Voltage D Term — Derivative Time (s)', value: isLfp ? 0.42 : 0.85 });
    rows.push({ param: 'cvPiZero', label: 'Voltage Loop Ki/Kp Ratio (ρ)', value: 0.5 });

    // Context for BATTDEF_CHEM_COPY. Cell counts are per 12 V of nominal bus (lead-acid/AGM 6 × 2 V,
    // LiFePO4 4 × 3.2 V), so × kV gives the real series count and every per-cell figure comes out
    // identical on a 12/24/36/48 V bank. Trailing zeros are trimmed so 3.600 reads as 3.6.
    const cellsPer12 = { lifepo4: 4, agm: 6, lead_acid: 6 }[type];
    const perCell = v => v.toFixed(3).replace(/0+$/, '').replace(/\.$/, '');
    const copy = {
        bulk: r2(T.bulkV * kV), hard: r2(hardSD), cells: cellsPer12 * kV,
        bulkCell: perCell(T.bulkV / cellsPer12), hardCell: perCell(hardSD / (cellsPer12 * kV)),
        delta: r2(hardSD - T.bulkV * kV), limA: C ? r1(T.limC * C) : 0   // the same number the BattCurrentLimitA row proposes
    };
    return { rows, useFloat, copy };
}

let _battDefResolve = null;
function battDefCbChanged() {
    const cbs = Array.from(document.querySelectorAll('#battdef-body .battdef-cb'));
    const n = cbs.filter(c => c.checked).length;
    const btn = document.getElementById('battdef-apply-btn');
    btn.disabled = !n;
    btn.style.opacity = n ? '' : '0.45';
    btn.style.cursor = n ? 'pointer' : 'default';
    const all = document.getElementById('battdef-cb-all');
    if (all) {
        all.checked = n === cbs.length && n > 0;
        all.indeterminate = n > 0 && n < cbs.length;
    }
}
function battDefCbAll(on) {
    document.querySelectorAll('#battdef-body .battdef-cb').forEach(cb => { cb.checked = on; });
    battDefCbChanged();
}
function battDefClose(apply) {
    document.getElementById('battdef-modal-overlay').style.display = 'none';
    const r = _battDefResolve; _battDefResolve = null;
    if (r) r(apply);
}

async function maybeProposeBatteryDefaults(vessel, prevBatt, deviceFirstSave, manual) {
    try {
        const type = vessel && vessel.battery_type;
        if (!type) { _battDefSkipNote('No battery type is on file, so no starting values could be recommended. Set the battery type under Setup &rarr; Vessel Info first.', manual); return; }
        // deviceFirstSave (device flag) covers a stale pre-flash browser tab whose prevBatt is set.
        const firstSave = deviceFirstSave || !(prevBatt && prevBatt.type);
        const battChanged = prevBatt && prevBatt.type && (
            prevBatt.type !== type ||
            prevBatt.cap !== Number(vessel.battery_capacity_ah) ||
            prevBatt.volt !== Number(vessel.battery_voltage));
        // Silent on purpose: this is every ordinary re-save of unchanged vessel info, so a note here
        // would fire on each save. The recommender is reachable on demand from System Settings, so
        // this return is no longer a one-way door. `manual` skips the gate entirely.
        if (!manual && !firstSave && !battChanged) return;
        if (type === 'other') { _battDefSkipNote('No recommendations are made for the Other battery type. Inspect every charge-stage and protection setting under Setup and adjust each one individually.', manual); return; }
        // A successful /saveVesselInfo proves the device is armed (that endpoint is arm-gated);
        // this tab's mirror can be stale after a reload. Re-sync and proceed — a genuinely
        // unarmed device fails the /exportConfig below, which already shows a visible skip note.
        if (!settingsUnlocked) syncArmState();

        // Current values from the device (raw NVS strings)
        const r = await fetchWithTimeout(buildURL('/exportConfig'), {}, 10000);
        if (!r.ok) { _battDefSkipNote('Could not read the current device settings (HTTP ' + r.status + '), so no initial charging settings could be recommended.' + (r.status === 403 ? ' Settings are locked — unlock them and try again.' : ''), manual); return; }
        const cfg = (await r.json()).config || {};
        const battSrc = ('BatteryCurrentSource' in cfg) ? parseInt(cfg.BatteryCurrentSource, 10) : 0;  // 0 = INA228
        const battProbe = ('battTempProbeEnable' in cfg) ? parseInt(cfg.battTempProbeEnable, 10) : 0;   // 1 = BATT-role DS18B20 in use
        const shuntPresent = ('BatteryShuntPresent' in cfg) ? parseInt(cfg.BatteryShuntPresent, 10) : 1;

        const der = deriveBatteryDefaults(type, Number(vessel.battery_capacity_ah), Number(vessel.battery_voltage), Number(vessel.regulator_mount_loc), battProbe);
        if (!der) { _battDefSkipNote('Battery type "' + _cfgEsc(String(type)) + '" is not one this regulator has recommendations for. Set each charge-stage and protection value individually under Setup.', manual); return; }

        const rows = [];   // preserve der.rows order; each carries now + match so matches render inline, highlighted
        for (const row of der.rows) {
            rows.push({ ...row, ...battDefRowState(cfg, row) });
        }
        const changed = rows.filter(r => !r.match);
        const unchanged = rows.length - changed.length;

        const typeName = { lifepo4: 'LiFePO4', agm: 'AGM', lead_acid: 'Lead Acid' }[type] || type;
        const capTxt = (Number(vessel.battery_capacity_ah) > 0) ? Number(vessel.battery_capacity_ah) + ' Ah, ' : '';
        // Charge targets/limits don't yet move with temperature (setpoint temp-comp is unbuilt; the
        // battery temperature itself now comes from the Setup > Temperature source chain). Inline here
        // (one message, in context) rather than a separate popup after this modal.
        const _tc = (typeof displayTempUnit !== 'undefined' && displayTempUnit === 1);
        let noticeHtml = '';
        if (type === 'agm' || type === 'lead_acid') {
            // The "wants more voltage cold, less hot" physics lives in BATTDEF_CHEM_COPY; only the
            // regulator's own gap is a notice.
            noticeHtml = battDefNotice('limit', 'No temperature compensation yet',
                'This regulator does not yet move your charge voltages, current limit, or protection limits with temperature — they stay fixed at whatever you set.');
        } else if (type === 'lifepo4') {
            const tFrz = _tc ? '0 °C' : '32 °F';
            noticeHtml = battDefNotice('warn', 'Do not charge below freezing',
                    'Charging a lithium (LiFePO4) battery below freezing (' + tFrz + ') plates the cells and permanently damages them, and the battery\'s protection circuit (BMS) can disconnect to defend itself — if it opens while the alternator is charging, the sudden loss of load can spike system voltage and damage other electronics.');
        }
        if (battProbe !== 1) {
            noticeHtml += battDefNotice('limit', 'Battery temperature source',
                'Battery temperature is taken from the regulator board unless a battery probe, an NMEA 2000 battery monitor, a VE.Direct monitor with a temperature sensor, or an RV-C source provides it. The board runs warmer than its surroundings, so the cold-charge lockout is a coarse guard when it is the only source. A battery probe fitted later is assigned under Setup > Temperature, where the hot-charge lockout and battery temperature limits also live.');
        }
        // Voltage float is allowed without a shunt (2026-09-09): absorption then ends on its time limit
        // instead of tail current, the way a solar controller floats with no shunt. Say which exit will
        // run, and that the time limit is therefore the setting to get right.
        if (der.useFloat === 1 && shuntPresent !== 1) {
            noticeHtml += battDefNotice('info', 'Float without a shunt runs on time',
                'The battery shunt is marked absent, so the regulator cannot see the battery\'s own current. Absorption will end on its time limit (Absorption Timeout under Setup > Battery) instead of on tail current, and float then holds the float voltage. With no shunt that time limit is the setting to get right for this bank. Declaring the shunt and entering its resistance switches the exit to tail current.');
        }
        if (type === 'lifepo4' && battSrc !== 0) {
            noticeHtml += battDefNotice('info', 'Float changed to No Float',
                'Zero-current float needs the INA228 battery shunt as the Battery Current Source, so Float Mode is proposed as No Float (idle) instead.');
        }
        const chemCopy = (typeof BATTDEF_CHEM_COPY[type] === 'function')
            ? BATTDEF_CHEM_COPY[type](der.copy)
            : (BATTDEF_CHEM_COPY[type] || '');
        const sum = document.getElementById('battdef-summary');
        sum.innerHTML = '<p style="margin:0 0 10px;">Based on the bank (<b>' + _cfgEsc(typeName) + '</b>, ' + capTxt + vessel.battery_voltage + ' V), '
            + 'the regulator can fill in recommended starting values for various settings below.<br>'
            + 'These are starting points - verify against the battery manufacturer\'s data sheets and your own research.</p>'
            + (chemCopy ? '<p style="margin:0 0 10px;">' + chemCopy + '</p>' : '')
            + noticeHtml
            + (unchanged ? '<p style="margin:0 0 10px;"><b>' + unchanged + '</b> setting' + (unchanged === 1 ? ' already matches' : 's already match') + ' the recommendation and ' + (unchanged === 1 ? 'is' : 'are') + ' highlighted below.</p>' : '');

        const body = document.getElementById('battdef-body');
        if (changed.length) {
            const show = row => row.show ? row.show : (v => String(v));
            let ci = 0;   // running index into `changed` for checkbox data-i (matches carry no checkbox)
            body.innerHTML = '<table style="width:100%; border-collapse:collapse; font-size:0.85em;">'
                + '<tr style="color:#aaa; text-align:left;"><th style="padding:3px 6px 3px 0; text-align:center;"><input type="checkbox" id="battdef-cb-all" checked onchange="battDefCbAll(this.checked)" title="Check / uncheck all" style="accent-color:#00a19a; margin:0; vertical-align:middle;"><br>Apply</th><th style="padding:3px 8px 3px 0;">Setting</th><th style="padding:3px 8px;">Now</th><th style="padding:3px 0;">Proposed</th></tr>'
                + rows.map(c => {
                    const sh = show(c);
                    const nowTxt = _cfgEsc(c.blob ? sh(c.now) : (isFinite(c.now) ? sh(c.now) : '?'));
                    const propTxt = _cfgEsc(sh(c.value));
                    if (c.match) {
                        return '<tr style="background:rgba(0,161,154,0.10);">'
                            + '<td style="padding:3px 6px 3px 0; text-align:center;"><span style="color:#00a19a; font-size:0.8em; font-weight:600;" title="Already matches the recommendation — nothing to apply">matches</span></td>'
                            + '<td style="padding:3px 8px 3px 0; color:#9cc;">' + _cfgEsc(c.label) + '</td>'
                            + '<td style="padding:3px 8px; color:#888;">' + nowTxt + '</td>'
                            + '<td style="padding:3px 0; color:#888;">' + propTxt + '</td></tr>';
                    }
                    const i = ci++;
                    const pre = (manual && BATTDEF_CX_OWNED.has(c.param)) ? '' : ' checked';
                    return '<tr><td style="padding:3px 6px 3px 0; text-align:center;"><input type="checkbox" class="battdef-cb" data-i="' + i + '"' + pre + ' onchange="battDefCbChanged()" style="accent-color:#00a19a; margin:0; vertical-align:middle;" title="' + (pre ? '' : 'Commissioning may own this value - check it only if you want the chemistry recommendation back') + '"></td>'
                        + '<td style="padding:3px 8px 3px 0; color:#9cc;">' + _cfgEsc(c.label) + '</td>'
                        + '<td style="padding:3px 8px; color:#888;">' + nowTxt + '</td>'
                        + '<td style="padding:3px 0; color:#fff;">' + propTxt + '</td></tr>';
                }).join('')
                + '</table>';
        } else {
            body.innerHTML = '<div style="color:#888; font-size:0.9em; padding:8px 0;">Nothing to change — the current settings already match the recommendations for this bank.</div>';
        }
        document.getElementById('battdef-apply-btn').style.display = changed.length ? '' : 'none';
        battDefCbChanged();   // re-enable the button if a previous open left it disabled
        vesselNextStepWait(false);   // first-install chain: armed after the Prerequisites screen closed
        document.getElementById('battdef-modal-overlay').style.display = 'flex';
        const apply = await new Promise(res => { _battDefResolve = res; });
        if (!apply || !changed.length) return;

        // Modal is hidden but still in the DOM, so the checkbox states survive the await
        const picked = [];
        document.querySelectorAll('#battdef-body .battdef-cb:checked').forEach(cb => picked.push(changed[+cb.dataset.i]));
        if (!picked.length) return;

        // One /get request — every hasParam block in the refactored handler processes independently
        const url = '/get?' + picked.map(c => c.param + '=' + encodeURIComponent(c.value)).join('&');
        const ar = await fetchWithTimeout(buildURL(url), {}, 10000);
        if (!ar.ok) { _battDefReport('Could not apply the recommended values (HTTP ' + ar.status + ').' + (manual ? '' : ' The vessel info itself was saved.'), false, manual); return; }

        // HTTP 200 does NOT mean the writes landed: /get answers with the LAST matching handler's
        // message, or "No message sent..." when nothing matched, so a request whose params were all
        // unrecognised, out of a handler's constrain() range, or overwritten by another handler in the
        // same request still comes back 200. Re-read and re-diff instead of trusting the status.
        let stuck = [];
        try {
            const vr = await fetchWithTimeout(buildURL('/exportConfig'), {}, 10000);
            if (vr.ok) {
                const vcfg = (await vr.json()).config || {};
                stuck = picked.filter(c => !battDefRowState(vcfg, c).match);
            }
        } catch (ve) { diagLog('battery defaults verify read failed:', ve); }

        const took = picked.length - stuck.length;
        if (!stuck.length) {
            _battDefReport('Applied ' + took + ' recommended value' + (took === 1 ? '' : 's') + '. Review them any time under Setup.', true, manual);
        } else {
            _battDefReport('Applied ' + took + ' of ' + picked.length + ' recommended values. These did not take and are still at their old value: '
                + stuck.map(c => c.label).join('; ') + '. Set them by hand under Setup.', false, manual);
        }
    } catch (e) {
        diagLog('battery defaults proposal failed:', e);
        _battDefSkipNote('Could not load the recommended initial charging settings (' + e.message + '). Review them any time under Setup &rarr; Battery.', manual);
    }
}

// Surface a battdef skip (else a silent config-fetch failure looks like a clean save) on the banner.
// The two rows commissioning MEASURES, so the chemistry table's generic value is a downgrade once a
// wizard run exists. IExcessCeilA is in commissionSnapshotScalarsToBuf's revert set and the Thresholds
// step raises it past the flat 20 A proposed here; CvKdDeadbandVps is overwritten by the Step-5 ripple
// fit (see its declaration comment in Xregulator.ino). On a MANUAL launch these arrive unchecked so a
// re-apply cannot silently undo a measurement — still listed, still checkable if the owner wants the
// generic value back. Deliberately NOT included: cvAlpha / CvKdTd / cvPiZero (design constants, nothing
// outside the /get handler writes them) and bhStepLowA / bhStepDeltaA (first-boot seed only).
const BATTDEF_CX_OWNED = new Set(['IExcessCeilA', 'CvKdDeadbandVps']);

// System Settings > Recommend Initial Charging Settings. The save-chain call fires at most once per battery
// identity per device lifetime, so without this there is no way back to the proposal after a Skip.
// Re-reads vessel info rather than trusting window.vesselInfo: that mirror can hold another unit's
// battery block after switching regulators in one browser session, which is how a bench with two
// identically-specified banks silently gets the wrong ladder.
async function launchBatteryRecommender() {
    if (_battDefResolve) { xAlert('The recommendation list is already open.', 'Recommend Initial Charging Settings'); return; }
    if (!settingsUnlocked) { xAlert('Please unlock settings first', 'Recommend Initial Charging Settings'); return; }
    let vessel = null;
    try {
        const r = await fetchWithTimeout(buildURL('/vessel_info.json'), {}, 5000);
        if (r.ok) { vessel = await r.json(); window.vesselInfo = vessel; }
    } catch (e) { diagLog('recommender vessel re-read failed:', e); }
    if (!vessel) vessel = window.vesselInfo;
    if (!vessel || !vessel.battery_type) {
        xAlert('No battery type is on file yet. Fill in the battery type, capacity and system voltage under Setup > Vessel Info and save, then come back here.', 'Recommend Initial Charging Settings');
        return;
    }
    await maybeProposeBatteryDefaults(vessel, null, true, true);
}

// Apply outcome. Same reachability problem as _battDefSkipNote: the banner is inside the Vessel Info
// tab, so a manual launch gets a dialog.
function _battDefReport(txt, ok, manual) {
    const md = document.getElementById('vessel-info-message');
    if (manual || !md) { xAlert(txt, ok ? 'Recommend Initial Charging Settings' : 'Some Values Did Not Apply'); return; }
    md.style.display = 'block';
    md.style.backgroundColor = ok ? '#e8f5e9' : '#ffebee';
    md.style.color = ok ? '#2e7d32' : '#c62828';
    md.textContent = txt;
}

// `manual` = launched from the System Settings button rather than the vessel-info save chain.
// #vessel-info-message lives inside the Vessel Info tab, so it is off-screen for a manual launch —
// those get a dialog instead, and text with no markup in it, since xAlert renders plain text.
function _battDefSkipNote(txt, manual) {
    const md = document.getElementById('vessel-info-message');
    if (manual || !md) { xAlert(String(txt).replace(/<br>/g, '\n').replace(/&rarr;/g, '>').replace(/<[^>]*>/g, ''), 'Recommend Initial Charging Settings'); return; }
    md.style.display = 'block';
    md.innerHTML += '<br><span style="color:#e6a23c;">' + txt + '</span>';
}

// One row's "what the device has now" + whether it already matches the recommendation. Extracted so
// the post-Apply verification re-runs the SAME comparison the modal rendered — a second, hand-rolled
// diff would drift from this one and report phantom failures.
function battDefRowState(cfg, row) {
    if (row.blob) {   // OCV curve: comma-joined string, compared numerically not as a scalar
        const nowStr = (cfg[row.param] !== undefined && cfg[row.param] !== '') ? String(cfg[row.param]) : '';
        return { now: nowStr, match: ocvBlobsEqual(nowStr, row.value) };
    }
    let nowUi;
    if (cfg[row.param] !== undefined) {
        const raw = parseFloat(cfg[row.param]);
        nowUi = BATTDEF_FROM_STORED[row.param] ? BATTDEF_FROM_STORED[row.param](raw) : raw;
    } else {
        nowUi = BATTDEF_FW_DEFAULT[row.param];
    }
    return { now: nowUi, match: isFinite(nowUi) && Math.abs(nowUi - row.value) < 0.005 };
}

// First-save chain only: between two setup screens the page sits idle on the device (SoC-seed poll,
// then the /exportConfig NVS walk, then the prerequisites write), which reads as a finished save.
// A note on the Vessel Info banner is out of sight at the bottom of a long form, so the wait gets
// its own black box in the same family as the screens on either side of it and the sequence never
// goes blank. Painting is delayed 600 ms so the common fast path never flashes it; a tail swap at
// 12 s turns the box amber and offers a close X so a stalled chain is not a trap.
let _vesselWaitShowTimer = null;
let _vesselWaitTailTimer = null;
function vesselNextStepWait(on) {
    if (_vesselWaitShowTimer !== null) { clearTrackedTimeout(_vesselWaitShowTimer); _vesselWaitShowTimer = null; }
    if (_vesselWaitTailTimer !== null) { clearTrackedTimeout(_vesselWaitTailTimer); _vesselWaitTailTimer = null; }
    const ov = document.getElementById('nextstep-modal-overlay');
    if (!ov) return;
    if (!on) { ov.style.display = 'none'; return; }
    _vesselWaitShowTimer = setTrackedTimeout(() => {
        _vesselWaitShowTimer = null;
        const title = document.getElementById('nextstep-title');
        const dots = document.getElementById('nextstep-dots');
        const head = document.getElementById('nextstep-head');
        const sub = document.getElementById('nextstep-sub');
        const x = document.getElementById('nextstep-close-btn');
        // Reset every escalated field: the same box is reused for each gap in the chain.
        title.textContent = 'Loading the Next Step';
        dots.style.color = '#35d6c7';
        head.style.color = '#e8e8e8';
        head.innerHTML = 'Setting up &mdash; the next screen opens by itself.';
        sub.textContent = 'Regulator busy — wait a few seconds and stay on this page';
        x.style.display = 'none';
        ov.style.display = 'flex';
        _vesselWaitTailTimer = setTrackedTimeout(() => {
            _vesselWaitTailTimer = null;
            title.textContent = 'Still Waiting on the Regulator';
            dots.style.color = '#f0b86a';
            head.style.color = '#f0b86a';
            head.textContent = 'Still waiting on the regulator.';
            sub.innerHTML = 'If nothing opens in a few more seconds, close this box and press '
                + '<strong style="color:#ccc;">Update Vessel Info</strong> again to restart the sequence.';
            x.style.display = '';
        }, 12000);
    }, 600);
}

// ===== Commissioning Prerequisites screen =====
// On a first Vessel Info save it runs FIRST, ahead of the battery-defaults popup, so the proposal is
// derived from the hardware described here; the Charge Rate Limits handoff is then made by the save
// chain rather than by this screen (_commPrepDeferHandoff). Presents the sensor/current settings
// commissioning depends on, pre-filled from /exportConfig. Only user-edited fields are written, in one
// /get (battdef pattern).
// Temperature inputs follow the app's display unit; every param is submitted in its native unit.
let _commPrereqResolve = null;   // awaited by the vessel-save chain; resolved when the modal closes
let _commPrepCfg = null;         // /exportConfig snapshot captured at open, for changed-detection
let _commPrepInit = {};          // input id → initial value string (only changed inputs are written)
let _commPrepTsInit = 0;         // TempSource at open (0 = DS18B20, 1 = Thermistor)
let _commPrepTempSrc = 0;        // live TempSource selection
let _commPrepShuntInit = 1;      // BatteryShuntPresent at open (1 = INA228 fitted, 0 = none)
let _commPrepShuntPresent = 1;   // live shunt-present selection
let _commPrepFloatInit = '';     // UseFloat at open (Other-only charge block); written only if the select changed
let _commPrepRpmActive = false;  // deep-linked into the RPM editor from the wizard: suppress the live blue row highlight
let _commPrepFirstInstall = true; // false on a re-commission: different intro copy
// Whether Next hands off to the tach-alignment screen. Split from _commPrepFirstInstall because the two
// questions are different: the intro copy asks "is this their first install", the alignment screen asks
// "is the engine-speed axis about to be re-measured against". A wholesale restart answers no to the first
// and YES to the second — it reverts every other setting to pre-commissioning and re-runs all nine steps,
// and every RPM-binned one of them is measured against this axis (see commissionClearRpmDependents in the
// firmware, which wipes seven stages when it moves). Continuing a partial run answers no to both: a rescale
// mid-tune would invalidate the steps already done in that same run.
let _commPrepShowAlign = true;
let _commPrepDeferHandoff = false; // vessel-save chain: Next resolves the screen instead of opening Charge Rate Limits (the chain does, after battdef / SoC / restart ack)
let _commPrepOwLast = null;      // last /tempSensors JSON, polled while this screen is open
let _commPrepOwSig = null;       // id:role:present signature of the rendered probe rows (null forces the first build)
let _commPrepOwBusy = false;     // a /tempSensors fetch is in flight
let _commPrepOwScanUntilMs = 0;  // "Scanning" shown until this time after a scan or an assignment
let _commPrepOwPolling = false;  // the 5 s probe poll is installed once per session

const CP_BTN_GREEN = 'background:linear-gradient(180deg,#35d6c7,#23a99c); color:#06302d; font-weight:700; border:none;';

function commPrepPaintCta() {
    const start = document.getElementById('commprep-start-btn');
    if (start) {
        start.style.cssText = 'border-radius:6px; padding:8px 16px; cursor:pointer; font-size:0.9em; ' + CP_BTN_GREEN;
        start.disabled = false;   // a re-render clears the probe-assignment gate; commPrepOwGate re-applies it if still needed
        start.title = '';
    }
}

// ----- Temperature probes on the prerequisites screen -----
// Binding the probes is part of commissioning, not homework for afterwards: the wizard stamps the
// battery-temperature source class it measured against, and an unbound Alternator role leaves the
// over-temperature protection with no temperature at all. Assignments and the two enable toggles are
// written immediately (like the Charge-Limit Follow button); the number fields stay staged until Next.
function commPrepOwVisible() {
    const ov = document.getElementById('commprep-modal-overlay');
    return !!ov && ov.style.display !== 'none' && document.visibilityState !== 'hidden';
}
function commPrepOwPollStart() {
    if (_commPrepOwPolling) return;
    _commPrepOwPolling = true;
    setTrackedInterval(() => { if (commPrepOwVisible()) commPrepOwPollNow(); }, 5000);
}
async function commPrepOwPollNow() {
    if (_commPrepOwBusy) return;
    _commPrepOwBusy = true;
    try {
        const r = await fetchWithTimeout(buildURL('/tempSensors'), { cache: 'no-cache' }, 6000);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        _commPrepOwLast = await r.json();
        commPrepOwRender(_commPrepOwLast);
    } catch (e) {
        diagLog('prerequisites tempSensors fetch failed:', e);   // block stays hidden; Next is not gated on a read we could not make
    } finally {
        _commPrepOwBusy = false;
    }
}
// Rows are rebuilt only when the id/role/present set changes, so an open role <select> is never torn
// down mid-choice; the temperature cell updates in place. No age column: a sensor is on the bus or it is
// not, and one that is listed but has stopped answering says so where its temperature would be.
const CP_OW_ROLE_LABEL = ['Alternator', 'Battery', 'Extra'];   // firmware roles 0..2; must match OW_ROLE_NAMES
const CP_OW_STALE_S = 30;                                      // read cadence is 5 s; 30 s of silence is a fault, not jitter
function commPrepOwRender(j) {
    const box = document.getElementById('commprep-ow');
    if (!box || !j) return;
    const probes = Array.isArray(j.probes) ? j.probes : [];
    const roles = j.roles || {};
    // Thermistor alternator with nothing on the bus is the one install with nothing to say here.
    box.style.display = (probes.length || _commPrepTempSrc === 0) ? '' : 'none';
    const body = document.getElementById('commprep-ow-rows');
    const head = document.getElementById('commprep-ow-head');
    if (head) head.style.display = probes.length ? '' : 'none';   // column titles over an empty-state line read as a broken table
    const sig = probes.map(p => p.id + ':' + p.role + ':' + (p.present ? 1 : 0)).join(',');
    if (body && sig !== _commPrepOwSig) {
        _commPrepOwSig = sig;
        body.innerHTML = probes.length ? probes.map(p => {
            const id = String(p.id || '').toLowerCase();
            const role = Number(p.role);
            const opts = [-1, 0, 1, 2].map(v => '<option value="' + v + '"' + (v === role ? ' selected' : '') + '>'
                + (v < 0 ? 'Not used' : CP_OW_ROLE_LABEL[v]) + '</option>').join('');
            return '<tr data-ow-id="' + _cfgEsc(id) + '"' + (p.present ? '' : ' style="opacity:0.55;"') + '>'
                + '<td style="padding:3px 8px 3px 0; font-family:monospace; color:#ddd;" title="' + _cfgEsc(id) + '">'
                + _cfgEsc(id.slice(-6).toUpperCase()) + '</td>'
                + '<td class="cp-ow-temp" style="padding:3px 8px 3px 0; color:#ccc;"></td>'
                + '<td style="padding:3px 0;"><select onchange="commPrepOwAssign(this)" style="background:#161616; color:#ddd; border:1px solid #444; border-radius:5px; padding:3px 6px; font-size:12px;">'
                + opts + '</select></td></tr>';
        }).join('') : '<tr><td colspan="3" style="padding:3px 0; color:#888;">No sensors found on the bus. Check the wiring, then press Rescan.</td></tr>';
    }
    const lbl = tempUnitLabel();
    for (const p of probes) {
        const id = String(p.id || '').toLowerCase();
        if (!/^[0-9a-f]{16}$/.test(id) || !body) continue;
        const tr = body.querySelector('tr[data-ow-id="' + id + '"]');
        if (!tr) continue;
        const td = tr.querySelector('.cp-ow-temp');
        if (!td) continue;
        const tF = (p.tempF === null || p.tempF === undefined) ? NaN : Number(p.tempF);
        const age = Number(p.ageS);
        let txt, warn = false;
        if (!p.present) { txt = 'not found'; warn = true; }
        else if (!Number.isFinite(tF) || !Number.isFinite(age) || age > CP_OW_STALE_S) { txt = 'not responding'; warn = true; }
        else txt = toDisplayTemp(tF).toFixed(1) + ' ' + lbl;
        if (td.textContent !== txt) td.textContent = txt;
        const col = warn ? '#e6a23c' : '#ccc';
        if (td.style.color !== col) td.style.color = col;
    }
    // Two things the table cannot say by itself: a bound sensor that has left the bus, and a Battery
    // assignment that Setup > Battery has switched off at the source select.
    const warn = document.getElementById('commprep-ow-warn');
    if (warn) {
        const present = new Set(probes.filter(p => p.present).map(p => String(p.id || '').toLowerCase()));
        const lines = [];
        const absent = (key, name, want) => {
            if (!want) return;
            const addr = String(roles[key] || '').toLowerCase();
            if (addr && !present.has(addr)) lines.push('The ' + name + ' sensor (' + addr.slice(-6).toUpperCase() + ') is not on the bus.');
        };
        absent('alt', 'alternator', _commPrepTempSrc === 0);
        absent('batt', 'battery', true);
        absent('extra', 'other', true);
        if (roles.batt && _commPrepCfg && Number(_commPrepCfg.battTempSource) === 6) {
            lines.push('Battery Temperature Source is set to None under Setup > Battery, so the battery sensor is not read.');
        }
        if (!probes.length && _commPrepTempSrc === 0) lines.push('Commissioning will run with no alternator temperature, and the over-temperature protection cannot act.');
        const txt = lines.join(' ');
        if (warn.textContent !== txt) warn.textContent = txt;
        warn.style.display = lines.length ? '' : 'none';
    }
    const st = document.getElementById('commprep-ow-status');
    if (st) {
        const n = probes.filter(p => p.present).length;
        const txt = (Number(j.scanning) === 1 || Date.now() < _commPrepOwScanUntilMs) ? 'Scanning the bus'
            : (n + ' sensor' + (n === 1 ? '' : 's') + ' found');
        if (st.textContent !== txt) st.textContent = txt;
    }
    commPrepOwGate(j);
}
// Blocking gate. Only the alternator blocks: commissioning drives the alternator hard and the
// over-temperature protection has nothing to act on without it. A missing battery or other sensor is a
// warning — battery temperature falls back through its own source chain, and Other feeds nothing the run
// depends on. Re-evaluated on every poll, so assigning the sensor clears it without reopening the screen.
// Uses the live Temperature Source selection, not the stored one: Digital chosen here is written by Next.
const CP_OW_GATE_TITLE = 'Choose the alternator temperature sensor first';
function commPrepOwGate(j) {
    const body = document.getElementById('commprep-body');
    const start = document.getElementById('commprep-start-btn');
    if (!body) return;
    const roles = (j && j.roles) || {};
    const n = j ? (Number(j.count) || 0) : 0;
    const missing = (n >= 1) && _commPrepTempSrc !== 1 && !roles.alt;
    let box = document.getElementById('commprep-owgate');
    if (!missing) {
        if (box) box.remove();
        if (start && start.disabled) commPrepPaintCta();
        return;
    }
    if (!box) {
        box = document.createElement('div');
        box.id = 'commprep-owgate';
        box.style.cssText = 'margin:0 0 14px; padding:11px 12px; background:rgba(230,162,60,0.06); border:1px solid rgba(230,162,60,0.32); border-radius:6px; font-size:12px; line-height:1.5; color:#e6a23c;';
        body.insertBefore(box, body.firstChild);
    }
    const html = '<strong>Say which sensor is on the alternator.</strong> '
        + n + ' sensor' + (n === 1 ? ' is' : 's are') + ' on the bus and none of them is set to Alternator. '
        + (!settingsUnlocked ? 'Unlock settings to set it.' : 'Set it in the table below.');
    if (box.innerHTML !== html) box.innerHTML = html;
    // Locked settings refuse the assignment, so blocking Next would dead-end the screen — say it, don't
    // block it. Re-run on every poll, so a lock that lands while the gate is up (arm window expired,
    // another client disarmed) also gives Next back.
    if (start) {
        if (settingsUnlocked) { start.disabled = true; start.style.opacity = '0.45'; start.style.cursor = 'default'; start.title = CP_OW_GATE_TITLE; }
        else if (start.disabled) commPrepPaintCta();
    }
}
async function commPrepOwAssign(sel) {
    const tr = sel.closest('tr');
    const id = tr ? String(tr.dataset.owId || '') : '';
    const newRole = parseInt(sel.value, 10);
    const cur = (_commPrepOwLast && Array.isArray(_commPrepOwLast.probes))
        ? _commPrepOwLast.probes.find(p => String(p.id || '').toLowerCase() === id) : null;
    const oldRole = cur ? Number(cur.role) : -1;
    const revert = () => { sel.value = String(oldRole); };
    if (!settingsUnlocked) { xAlert('Please unlock settings first'); revert(); return; }
    if (!/^[0-9a-f]{16}$/.test(id) || !Number.isFinite(newRole)) { revert(); return; }
    sel.disabled = true;
    let enabledEarly = null;   // enable turned on ahead of the bind, undone if the bind is refused
    try {
        // The assignment IS the enable: there is no separate Installed/None control on this screen to
        // contradict it. Battery role on → the source chain may read it; role off → it may not. The
        // enable goes on BEFORE the bind: with one probe on the bus and both enables off, the firmware's
        // enumerate re-binds it to Alternator between the clear and the re-bind, and the re-bind is then
        // refused as already assigned.
        if (newRole === 1 && oldRole !== 1) { await commPrepOwSetEnable('battTempProbeEnable', true); enabledEarly = 'battTempProbeEnable'; }
        if (newRole === 2 && oldRole !== 2) { await commPrepOwSetEnable('extraTempProbeEnable', true); enabledEarly = 'extraTempProbeEnable'; }
        await owWriteRole(id, oldRole, newRole);
        if (oldRole === 1 && newRole !== 1) await commPrepOwSetEnable('battTempProbeEnable', false);
        if (oldRole === 2 && newRole !== 2) await commPrepOwSetEnable('extraTempProbeEnable', false);
        _commPrepOwScanUntilMs = Date.now() + 1500;
    } catch (e) {
        diagLog('prerequisites probe role assignment failed:', e);
        if (enabledEarly) { try { await commPrepOwSetEnable(enabledEarly, false); } catch (e2) { } }
        const why = String((e && e.message) || '');
        xAlert(/^Rejected/.test(why) ? ('Could not assign the sensor: ' + why.replace(/^Rejected:\s*/, '') + '.')
                                     : 'Could not assign the sensor. Check the connection and try again.');
        revert();
    } finally {
        sel.disabled = false;
        setTrackedTimeout(commPrepOwPollNow, 700);
        setTrackedTimeout(commPrepOwPollNow, 2500);
    }
}
async function commPrepOwSetEnable(param, on) {
    const r = await fetchWithTimeout(buildURL('/get?' + param + '=' + (on ? 1 : 0)), {}, 8000);
    if (!r.ok) throw new Error('HTTP ' + r.status);
}
async function commPrepOwScan() {
    if (!settingsUnlocked) { xAlert('Please unlock settings first'); return; }
    const btn = document.getElementById('commprep-ow-scan');
    if (btn) btn.disabled = true;
    try {
        const r = await fetchWithTimeout(buildURL('/get?owScan=1'), {}, 8000);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        _commPrepOwScanUntilMs = Date.now() + 2500;
        const st = document.getElementById('commprep-ow-status');
        if (st) st.textContent = 'Scanning the bus';
    } catch (e) {
        diagLog('prerequisites probe scan request failed:', e);
        xAlert('Could not start the probe scan. Check the connection and try again.');
    } finally {
        if (btn) btn.disabled = false;
        setTrackedTimeout(commPrepOwPollNow, 1500);
        setTrackedTimeout(commPrepOwPollNow, 4000);
    }
}
function commPrepFetchCfg() {
    return fetchWithTimeout(buildURL('/exportConfig'), {}, 10000)
        .then(r => r.ok ? r.json() : null)
        .catch(e => { diagLog('commissioning prerequisites config fetch failed:', e); return null; });
}

// Maintenance-restart acknowledgement — first Vessel Info save only, sequenced after the SoC
// popup and before the Charge Rate Limits handoff. Static body in index.html; any close
// path resolves the save-chain promise.
let _maintAckResolve = null;
function maintAckShow() {
    return new Promise(res => {
        _maintAckResolve = res;
        document.getElementById('maint-ack-overlay').style.display = 'flex';
    });
}
function maintAckClose() {
    document.getElementById('maint-ack-overlay').style.display = 'none';
    if (_maintAckResolve) { _maintAckResolve(); _maintAckResolve = null; }
}

// Pre-flight for EVERY commissioning run, not only the first. A re-commission needs the same
// Charge-Limit Follow check and the same sensor settings confirmed before the wizard re-measures
// the system; the values are simply already filled in. firstInstall also decides what Next hands
// off to — tach alignment is a first-install-only screen. deferHandoff (the vessel-save chain):
// Next resolves true instead of opening Charge Rate Limits — the chain opens it after the
// battery-defaults, SoC and restart-ack screens; every other exit resolves false.
async function openCommPrereqs(firstInstall, deferHandoff, showAlign) {
    _commPrepFirstInstall = !!firstInstall;
    _commPrepShowAlign = (showAlign === undefined) ? !!firstInstall : !!showAlign;
    _commPrepDeferHandoff = !!deferHandoff;
    try {
        // A successful /saveVesselInfo proves the device is armed; this tab's mirror can be stale after a
        // reload (same case as the battery-defaults popup). This screen now opens seconds after the save,
        // and both the role selects and the Next write are gated on the mirror, so the resync is awaited
        // alongside the config read (one small request — never the longer of the two) instead of racing
        // the first assignment.
        const armP = settingsUnlocked ? null : syncArmState();
        const cfgP = commPrepFetchCfg();
        vesselNextStepWait(true);
        const [j] = await Promise.all([cfgP, armP]);
        vesselNextStepWait(false);
        if (!j) {
            // First install the save chain simply carries on. A re-commission was a deliberate button
            // press, so dead-ending here reads as a broken control — say so and run the rest of the flow.
            if (firstInstall) { _battDefSkipNote('Could not read the current device settings, so the commissioning prerequisites screen was skipped. Those settings are all available under Setup.'); return false; }
            await xAlert('Could not read the current device settings, so the prerequisites screen was skipped. Check them under Setup if anything has changed since the last run.');
            openRpmCap(openCommissionModal, null);
            return false;
        }
        // Same response also carries the RPM cap tables the NEXT screen needs, so hand them over
        // rather than making openRpmCap re-fetch. The cap tables live in the "learning" namespace and
        // nothing this screen writes can touch them, so the snapshot cannot go stale in between.
        _rpmCapTablesPre = j.tables || null;
        _commPrepCfg = j.config || {};
        commPrepRender(_commPrepCfg);
        document.getElementById('commprep-modal-overlay').style.display = 'flex';
        commPrepOwPollStart();          // installed once; renders the probe block and re-checks the Next gate every 5 s
        commPrepOwPollNow();
        return await new Promise(res => { _commPrereqResolve = res; });   // true only from Next
    } catch (e) {
        diagLog('commissioning prerequisites failed:', e);
        return false;
    }
}

// First install — the vessel-save chain awaits this one and makes the Charge Rate Limits handoff itself
// once the battery-defaults, SoC and restart-ack screens are done; resolves true only if Next was pressed.
function maybeShowCommPrereqs() { return openCommPrereqs(true, true); }

function commPrepRender(cfg) {
    const numF = k => (cfg[k] !== undefined && cfg[k] !== '') ? parseFloat(cfg[k]) : NaN;
    const raw = k => { const v = numF(k); return isFinite(v) ? String(v) : ''; };
    const tempLbl = tempUnitLabel();
    const fToDisp = f => !isFinite(f) ? '' : (displayTempUnit === 1 ? String(Math.round((f - 32) * 5 / 9 * 10) / 10) : String(f));

    const ts = (numF('TempSource') === 1) ? 1 : 0;
    _commPrepTsInit = ts; _commPrepTempSrc = ts;

    const shuntPresent = (numF('BatteryShuntPresent') === 0) ? 0 : 1;   // default fitted
    _commPrepShuntInit = shuntPresent; _commPrepShuntPresent = shuntPresent;

    // The charge block (Bulk/Absorption/Float/current/protection) appears ONLY for Other — every other
    // chemistry got these proposed by the battery-defaults populator, which bails for Other and leaves
    // nothing set. Battery temperature limits are not here at all: they are non-critical for the run. The
    // populator proposes the cold/hot lockout enables and the hot limit from chemistry; the cold floor
    // (MinChargeTempF) stays at the firmware default until edited under Setup > Battery.
    const chem = (window.vesselInfo && String(window.vesselInfo.battery_type || '').toLowerCase()) || '';
    const isOther = chem === 'other';

    const inputCss = 'width:100%; background:#161616; color:#ddd; border:1px solid #444; border-radius:5px; padding:7px 10px; font-size:14px; box-sizing:border-box;';
    const lblCss = 'display:block; font-size:12px; color:#9cc; margin-bottom:5px;';
    const rowCss = 'margin-bottom:14px;';
    const field = (label, id, val, step, min, max) =>
        '<div style="' + rowCss + '"><label style="' + lblCss + '">' + label + '</label>' +
        '<input id="' + id + '" type="number" step="' + step + '" min="' + min + '" max="' + max + '" value="' + val + '" style="' + inputCss + '"></div>';

    // Charge-Limit Follow is only worth a word when it is actually on: commissioning must own the
    // battery, and follow resumes the instant the wizard's heartbeat stops. Off already — say nothing.
    const dvccNotice = (numF('dvccEn') === 1)
        ? '<div id="commprep-dvcc" style="margin:0 0 14px; padding:11px 12px; background:rgba(230,162,60,0.06); border:1px solid rgba(230,162,60,0.32); border-radius:6px;">' +
          '<div id="commprep-dvcc-copy" style="font-size:12px; line-height:1.5; color:#e6a23c; margin-bottom:9px;"><strong>Charge-Limit Follow is on.</strong> Commissioning must own the battery. Switch it off for the run, then turn it back on under Setup &gt; Integrations when you are done.</div>' +
          '<button type="button" id="commprep-dvcc-btn" onclick="commPrepDvccOff()" class="btn-secondary" style="border-radius:5px; padding:6px 14px; cursor:pointer; font-size:0.85em;">Switch it off</button>' +
          '</div>'
        : '';

    const capCss = 'font-size:11px; color:#888; margin-top:5px; line-height:1.4;';
    const fieldCap = (label, id, val, step, min, max, cap) =>
        '<div style="' + rowCss + '"><label style="' + lblCss + '">' + label + '</label>' +
        '<input id="' + id + '" type="number" step="' + step + '" min="' + min + '" max="' + max + '" value="' + val + '" style="' + inputCss + '">' +
        '<div style="' + capCss + '">' + cap + '</div></div>';
    const grpHdr = t => '<div style="font-size:11px; color:#9cc; letter-spacing:0.04em; text-transform:uppercase; margin:2px 0 8px;">' + t + '</div>';

    // Phone-only laptop nudge. This is the first screen of the flow and the first one that is a form,
    // so it is where a small screen starts to hurt; the vessel-info landing nudge (smallScreenSetupMsg)
    // never fires on a re-commission, which reaches this screen too.
    const smallScreen = _isPhoneSizedScreen()
        ? '<p style="font-size:13px; line-height:1.5; color:#bbb; margin:0 0 14px;"><strong style="color:#e0e0e0;">Use a laptop or tablet if you can.</strong> Setup and Commissioning works on a phone, but it\'s a worse UX on a small screen.</p>'
        : '';
    const intro = cxPanelOverrideStripHtml() + smallScreen + '<p style="font-size:13px; line-height:1.5; color:#bbb; margin:0 0 14px;">' + (_commPrepFirstInstall
            ? 'A few things to set before commissioning measures your system. These affect how the regulator reads temperature and current. Anything you skip stays editable later under Setup.'
            : 'These are the settings commissioning measures against, filled in from the regulator. Confirm they still describe the system before the wizard re-measures it — anything you change here is written when you press Next.') + '</p>' + dvccNotice;

    const seg = '<div style="' + rowCss + '"><label style="' + lblCss + '">Alternator Temperature Source</label>' +
        '<div class="cap-mode-toggle" style="background:rgba(255,255,255,0.07); border-color:#444;">' +
        '<button type="button" id="commprep-ts-0" class="cap-mode-btn' + (ts === 0 ? ' cap-mode-active' : '') + '" onclick="commPrepTempSrc(0)">Digital</button>' +
        '<button type="button" id="commprep-ts-1" class="cap-mode-btn' + (ts === 1 ? ' cap-mode-active' : '') + '" onclick="commPrepTempSrc(1)">Thermistor</button>' +
        '</div><div style="' + capCss + '">Default is the digital sensor provided with the kit.</div></div>';

    const shuntSeg = '<div style="' + rowCss + '"><label style="' + lblCss + '">Battery shunt (INA228)</label>' +
        '<div class="cap-mode-toggle" style="background:rgba(255,255,255,0.07); border-color:#444;">' +
        '<button type="button" id="commprep-sh-1" class="cap-mode-btn' + (shuntPresent === 1 ? ' cap-mode-active' : '') + '" onclick="commPrepShuntPresent(1)">Installed</button>' +
        '<button type="button" id="commprep-sh-0" class="cap-mode-btn' + (shuntPresent === 0 ? ' cap-mode-active' : '') + '" onclick="commPrepShuntPresent(0)">None</button>' +
        '</div>' +
        '<div style="font-size:11px; color:#888; margin-top:5px; line-height:1.4;">Set this before commissioning. Without a shunt: state of charge, the battery-current limit, and zero-current float turn off, and absorption can no longer end on tapering current — it runs until its time limit instead, then float (if enabled) holds the float voltage. The alternator-current limit protects the battery (as best it can — it\'s unaware of other charging sources). This mode is NOT RECOMMENDED and for skilled use only.</div>' +
        '</div>';

    const thermistor = '<div id="commprep-thermistor" style="display:' + (ts === 1 ? '' : 'none') + '; margin:0 0 14px; padding:10px 12px; background:#191919; border:1px solid #333; border-radius:6px;">' +
        field('Thermistor Series Resistor R_fixed (Ω)', 'commprep-rfixed', raw('R_fixed'), '1', '0', '1000000') +
        field('Thermistor Beta', 'commprep-beta', raw('Beta'), '1', '0', '100000') +
        field('Thermistor Reference Temp T0 (°C)', 'commprep-t0', raw('T0_C'), '0.1', '0', '300') +
        '</div>';

    const hr = '<hr style="border:none; border-top:1px solid #333; margin:2px 0 14px;">';

    // Shell only — commPrepOwRender fills the rows, the warnings and the Next gate from /tempSensors while
    // the screen is open, and hides the whole block on a thermistor install with a bare 1-Wire bus. Assigning
    // Battery or Other here is what turns their source on; there is no separate enable to contradict the table.
    const owBlock = '<div id="commprep-ow" style="display:none;">' +
        '<div style="' + rowCss + '">' + grpHdr('Digital Temperature Sensors') +
        '<div style="' + capCss + ' margin-top:0; margin-bottom:7px;">Set what each sensor measures. Warm one by hand to identify it — its reading rises within a few seconds.</div>' +
        '<table style="width:100%; border-collapse:collapse; font-size:12px;">' +
        '<thead id="commprep-ow-head"><tr style="color:#9cc; text-align:left;">' +
        '<th style="font-weight:600; padding:0 8px 4px 0;">Serial</th><th style="font-weight:600; padding:0 8px 4px 0;">Temperature</th>' +
        '<th style="font-weight:600; padding:0 0 4px;">Measures</th></tr></thead>' +
        '<tbody id="commprep-ow-rows"></tbody></table>' +
        '<div id="commprep-ow-warn" style="display:none; font-size:11px; color:#e6a23c; margin-top:6px; line-height:1.4;"></div>' +
        '<div style="display:flex; align-items:center; gap:10px; margin-top:8px;">' +
        '<button type="button" id="commprep-ow-scan" onclick="commPrepOwScan()" style="background:#3a3a3a; border:1px solid #555; color:#ddd; border-radius:5px; padding:5px 12px; cursor:pointer; font-size:0.8em;">Rescan</button>' +
        '<span id="commprep-ow-status" style="font-size:11px; color:#888;"></span></div>' +
        '<div style="' + capCss + '">Alternator feeds the over-temperature protection. Battery supplies the battery temperature the charge lockouts and the voltage-loop gain derate use. Extra is any other temperature you want to watch, shown on Live Data with its own alarms.</div>' +
        '</div>' + hr + '</div>';

    // FLOAT_DURATION is stored/exported in seconds; the input edits hours (firmware re-multiplies on write).
    const uf = (function () { const v = numF('UseFloat'); return (v === 1 || v === 2) ? v : 0; })();
    const floatDurH = () => { const s = numF('FLOAT_DURATION'); return isFinite(s) ? String(Math.round(s / 3600 * 100) / 100) : ''; };
    _commPrepFloatInit = String(uf);
    const otherBlock = isOther ? (
        '<div style="font-size:11px; color:#9cc; letter-spacing:0.04em; text-transform:uppercase; margin:2px 0 6px;">Charge Settings</div>' +
        '<p style="font-size:12px; line-height:1.5; color:#e6a23c; margin:0 0 14px;">Battery type is set to Other, so no recommended charge values were proposed. Set these starting points now and verify each against your battery\'s data sheet.</p>' +
        field('Bulk Voltage (V)', 'commprep-bulkv', raw('BulkVoltage'), '0.01', '1', '99') + hr +
        field('Absorption Voltage (V)', 'commprep-absv', raw('AbsorptionVoltage'), '0.01', '1', '99') + hr +
        '<div style="' + rowCss + '"><label style="' + lblCss + '">Float Mode</label>' +
        '<select id="commprep-usefloat" onchange="commPrepFloatMode(this.value)" style="' + inputCss + '">' +
        '<option value="0"' + (uf === 0 ? ' selected' : '') + '>No Float (idle)</option>' +
        '<option value="1"' + (uf === 1 ? ' selected' : '') + '>Voltage Float</option>' +
        '<option value="2"' + (uf === 2 ? ' selected' : '') + '>Zero-Current Float</option>' +
        '</select></div>' +
        '<div id="commprep-floatsub" style="display:' + (uf === 1 ? '' : 'none') + '; margin:0 0 14px; padding:10px 12px; background:#191919; border:1px solid #333; border-radius:6px;">' +
        field('Float Voltage (V)', 'commprep-floatv', raw('FloatVoltage'), '0.01', '1', '99') +
        field('Float Duration (hrs)', 'commprep-floatdur', floatDurH(), '0.01', '0', '999') +
        '</div>' + hr +
        field('Battery Charge Current Limit (A)', 'commprep-battlim', raw('BattCurrentLimitA'), '5', '0', '500') + hr +
        field('Alternator Hard Shutdown Voltage (V)', 'commprep-hardsd', raw('AlternatorHardShutdownV'), '0.01', '1', '99') + hr +
        field('Hardware Shutdown Voltage (V)', 'commprep-hwlim', raw('VoltageHardwareLimit'), '0.01', '10', '70') + hr +
        field('High Voltage Alarm (V)', 'commprep-valmhi', raw('VoltageAlarmHigh'), '0.01', '1', '99') + hr +
        field('Low Voltage Alarm (V)', 'commprep-valmlo', raw('VoltageAlarmLow'), '0.01', '1', '99') + hr
    ) : '';

    const shRow = (a, u, m, hl) => '<tr style="text-align:right;' + (hl ? ' font-weight:700; color:#fff;' : '') + '"><td style="text-align:left;">' + a + ' A' + (hl ? ' — BMV-712' : '') + '</td><td>' + u + '</td><td>' + m + '</td></tr>';
    const shGrp = (t, rows) => '<tr><td colspan="3" style="text-align:left; padding-top:5px; color:#7fb0c0; text-transform:uppercase; letter-spacing:0.04em; font-size:10px;">' + t + '</td></tr>' + rows.map(r => shRow(r[0], r[1], r[2], r[3])).join('');
    const shuntHelp =
        '<details style="margin:-4px 0 0; font-size:11px;">' +
        '<summary style="cursor:pointer; color:#7fb0c0;">Common shunt values</summary>' +
        '<div style="margin-top:6px; color:#999; line-height:1.4;">Shunts are rated by a full-scale millivolt drop at a rated current; µΩ = mV ÷ amps × 1000. Victron is the 50 mV family.</div>' +
        '<table style="width:100%; margin-top:6px; border-collapse:collapse; font-size:11px; color:#ccc; text-align:right;">' +
        '<tr style="color:#9cc;"><th style="text-align:left;">Rated</th><th>µΩ</th><th>mΩ</th></tr>' +
        shGrp('50 mV — Victron / marine', [[100, 500, '0.5'], [200, 250, '0.25'], [300, 167, '0.167'], [400, 125, '0.125'], [500, 100, '0.1', 1], [1000, 50, '0.05'], [2000, 25, '0.025']]) +
        shGrp('75 mV — industrial / analog meter', [[50, 1500, '1.5'], [100, 750, '0.75'], [150, 500, '0.5'], [200, 375, '0.375'], [300, 250, '0.25'], [400, 188, '0.188'], [500, 150, '0.15'], [600, 125, '0.125']]) +
        shGrp('100 mV', [[100, 1000, '1.0'], [200, 500, '0.5'], [300, 333, '0.333'], [500, 200, '0.2'], [1000, 100, '0.1']]) +
        '</table></details>';

    document.getElementById('commprep-body').innerHTML =
        intro + owBlock +
        grpHdr('Alternator') + seg + thermistor +
        fieldCap('Alternator Temperature Limit (' + tempLbl + ')', 'commprep-templimit', fToDisp(numF('TemperatureLimitF')), '1', '0', '350',
                 'A case temperature, not a winding temperature — the case runs 40–50 °F cooler than the windings inside.') + hr +
        grpHdr('Battery') + shuntSeg +
        '<div id="commprep-shunt-row" style="display:' + (shuntPresent === 1 ? '' : 'none') + ';">' +
        field('Shunt Resistance (µΩ)', 'commprep-shunt', raw('ShuntResistanceMicroOhm'), '1', '1', '5000') + shuntHelp +
        '</div>' + hr +
        otherBlock;
    commPrepPaintCta();
    _commPrepOwSig = null;                                    // rows were just wiped with the body
    if (_commPrepOwLast) commPrepOwRender(_commPrepOwLast);   // repaint from the last poll instead of blanking until the next one

    // Only inputs the user actually edits get written — snapshot their initial strings after render.
    _commPrepInit = {};
    document.querySelectorAll('#commprep-body input[type=number]').forEach(el => { _commPrepInit[el.id] = el.value; });
}

// Turns Charge-Limit Follow off from the prerequisites screen. Written immediately rather than
// staged with the number fields: it must hold even if this screen is dismissed with ✕, and a
// failure has to be visible before the run starts rather than silently skipped.
async function commPrepDvccOff() {
    if (!settingsUnlocked) { xAlert('Please unlock settings first'); return; }
    const btn = document.getElementById('commprep-dvcc-btn');
    const copy = document.getElementById('commprep-dvcc-copy');
    const box = document.getElementById('commprep-dvcc');
    if (btn) { btn.disabled = true; btn.textContent = 'Switching off...'; }
    try {
        const r = await fetchWithTimeout(buildURL('/get?dvccEn=0'), {}, 8000);
        if (!r.ok) throw new Error('HTTP ' + r.status);
    } catch (e) {
        diagLog('charge-limit follow off failed:', e);
        if (btn) { btn.disabled = false; btn.textContent = 'Switch it off'; }
        if (copy) copy.innerHTML = '<strong>Could not reach the regulator.</strong> Try again, or switch Charge-Limit Follow off under Setup &gt; Integrations before starting.';
        return;
    }
    if (_commPrepCfg) _commPrepCfg.dvccEn = '0';   // a re-render must not re-offer what is already done
    if (box) { box.style.background = 'rgba(46,196,182,0.06)'; box.style.borderColor = 'rgba(46,196,182,0.32)'; }
    if (copy) { copy.style.color = '#2ec4b6'; copy.style.marginBottom = '0'; copy.innerHTML = '<strong>Charge-Limit Follow is off.</strong> Turn it back on under Setup &gt; Integrations when commissioning is done.'; }
    if (btn) btn.remove();
}

// Thermistor sub-fields (R_fixed / Beta / T0) reveal only when Thermistor is the source.
function commPrepTempSrc(v) {
    _commPrepTempSrc = v;
    const b0 = document.getElementById('commprep-ts-0'), b1 = document.getElementById('commprep-ts-1');
    if (b0) b0.classList.toggle('cap-mode-active', v === 0);
    if (b1) b1.classList.toggle('cap-mode-active', v === 1);
    const th = document.getElementById('commprep-thermistor');
    if (th) th.style.display = (v === 1) ? '' : 'none';
    if (_commPrepOwLast) commPrepOwRender(_commPrepOwLast);   // Thermistor drops the Alternator-role requirement
}

// Shunt Resistance is inert without a battery shunt — reveal it only when one is installed.
function commPrepShuntPresent(v) {
    _commPrepShuntPresent = v;
    const b1 = document.getElementById('commprep-sh-1'), b0 = document.getElementById('commprep-sh-0');
    if (b1) b1.classList.toggle('cap-mode-active', v === 1);
    if (b0) b0.classList.toggle('cap-mode-active', v === 0);
    const row = document.getElementById('commprep-shunt-row');
    if (row) row.style.display = (v === 1) ? '' : 'none';
}

// Float Voltage / Float Duration are inert unless Voltage Float (UseFloat=1) is selected — reveal only then.
function commPrepFloatMode(v) {
    const sub = document.getElementById('commprep-floatsub');
    if (sub) sub.style.display = (String(v) === '1') ? '' : 'none';
}

function commPrepCollectChanges() {
    const out = [];
    const toF = d => displayTempUnit === 1 ? Math.round((d * 9 / 5 + 32) * 10) / 10 : d;   // display → native °F
    const rec = (param, id, native) => {
        const el = document.getElementById(id);
        if (!el || el.value === '') return;                 // blank → don't write
        if (el.value === (_commPrepInit[id] || '')) return; // unchanged in the shown unit
        const v = parseFloat(el.value);
        if (!isFinite(v)) return;
        out.push({ param, value: native ? native(v) : v });
    };
    rec('TemperatureLimitF', 'commprep-templimit', toF);
    rec('ShuntResistanceMicroOhm', 'commprep-shunt', null);
    rec('BattCurrentLimitA', 'commprep-battlim', null);
    rec('R_fixed', 'commprep-rfixed', null);
    rec('Beta', 'commprep-beta', null);
    rec('T0_C', 'commprep-t0', null);
    // Other-only charge block. rec() no-ops when the input is absent, so these are inert for non-Other.
    // Inputs already carry /get's expected units: volts direct, Float Duration in hours (firmware ×3600).
    rec('BulkVoltage', 'commprep-bulkv', null);
    rec('AbsorptionVoltage', 'commprep-absv', null);
    rec('FloatVoltage', 'commprep-floatv', null);
    rec('FLOAT_DURATION', 'commprep-floatdur', null);
    rec('AlternatorHardShutdownV', 'commprep-hardsd', null);
    rec('VoltageHardwareLimit', 'commprep-hwlim', null);
    rec('VoltageAlarmHigh', 'commprep-valmhi', null);
    rec('VoltageAlarmLow', 'commprep-valmlo', null);
    const ufSel = document.getElementById('commprep-usefloat');
    if (ufSel && ufSel.value !== _commPrepFloatInit) out.push({ param: 'UseFloat', value: parseInt(ufSel.value, 10) });
    if (_commPrepTempSrc !== _commPrepTsInit) out.push({ param: 'TempSource', value: _commPrepTempSrc });
    // Write shunt-present before the wizard starts so its side effects (zero-current float demoted, SoC/limit off) settle
    // ahead of commissioning, instead of being toggled mid-run.
    if (_commPrepShuntPresent !== _commPrepShuntInit) out.push({ param: 'BatteryShuntPresent', value: _commPrepShuntPresent });
    return out;
}

// Write any edited fields (one /get) then close. start=true hands off to the commissioning wizard —
// immediately, or (vessel-save chain) by resolving true so the chain opens Charge Rate Limits later.
async function commPrepFinish(start) {
    const changes = commPrepCollectChanges();
    _commPrepRpmActive = false;
    document.getElementById('commprep-modal-overlay').style.display = 'none';
    if (start) vesselNextStepWait(true);   // the write below, then openRpmCap (or the chain's battery-defaults read), run against a blank page
    if (changes.length && settingsUnlocked) {
        const url = '/get?' + changes.map(c => c.param + '=' + encodeURIComponent(c.value)).join('&');
        try { await fetchWithTimeout(buildURL(url), {}, 10000); } catch (e) { diagLog('prerequisites submit failed:', e); }
    }
    const deferred = _commPrepDeferHandoff; _commPrepDeferHandoff = false;   // one-shot: a reopen via ← Back hands off immediately
    if (!start) _rpmCapTablesPre = null;   // no next screen takes the handed-over tables
    const r = _commPrereqResolve; _commPrereqResolve = null; if (r) r(!!start);
    if (!start || deferred) return;
    // Both paths: Low/High charge-rate limits next, ← Back reopens this screen. Tach alignment is
    // first-install only — RPMScalingFactor/PulleyRatio persist and stay editable under Setup ▸ Engine.
    openRpmCap(_commPrepShowAlign ? openRpmAlign : openCommissionModal, commPrepReopen);
}

// ← Back from Charge Rate Limits: the screen comes back as it was left, and its Next hands off directly.
function commPrepReopen() { document.getElementById('commprep-modal-overlay').style.display = 'flex'; }

// ✕ — dismiss without writing edits (mirrors the battdef Skip/✕).
function commPrepClose() {
    _commPrepRpmActive = false;
    document.getElementById('commprep-modal-overlay').style.display = 'none';
    _commPrepDeferHandoff = false;
    _rpmCapTablesPre = null;
    const r = _commPrereqResolve; _commPrereqResolve = null; if (r) r(false);
}

// ===== Charge Rate Limits screen (pre-commissioning) =====
// Standalone dark modal between the Prerequisites screen and tach alignment
// (commPrepFinish → openRpmCap → [Continue in Low/High] → openRpmAlign → wizard). Seeds BOTH the Low
// and High RPM/current cap tables at once via /get?capBothSave (firmware writes both blobs regardless
// of the live mode); the chosen Continue button then sets HiLow, so the mode the user picks is the one
// active for commissioning. The Amps/kW toggle mirrors the live RPM Table — values are held canonically
// in amps and cross-derived to kW at the live battery voltage for display and on save.
let _rpmCap = null;         // { rpm:[10], lo:[10], hi:[10] (amps), unit:'amps'|'kw' }
let _rpmCapNext = null;     // handoff after a Continue button: openRpmAlign (first install) or openCommissionModal (re-commission)
let _rpmCapBack = null;     // ← Back target: reopen Prerequisites; null only when that screen was skipped
let _rpmCapTablesPre = null; // tables handed over by the Prerequisites screen's /exportConfig; null → fetch our own

async function openRpmCap(next, back) {
    _rpmCapNext = next || openRpmAlign;
    _rpmCapBack = back || null;
    if (!settingsUnlocked) { vesselNextStepWait(false); _rpmCapNext(); return; }   // locked → can't write tables; skip ahead
    let tables = _rpmCapTablesPre || {};
    _rpmCapTablesPre = null;   // one-shot: a ← Back and second Next re-reads from the device
    if (!Object.keys(tables).length) {
        try {
            const r = await fetchWithTimeout(buildURL('/exportConfig'), {}, 10000);
            if (r.ok) tables = (await r.json()).tables || {};
        } catch (e) { diagLog('charge-rate limits load failed:', e); }
    }
    const arr = k => String(tables[k] || '').split(',').map(s => parseFloat(s));
    const rpm = arr('rpmPoints'), hi = arr('capTable'), lo = arr('capTableLo');
    _rpmCap = {
        unit: 'amps',
        rpm: Array.from({ length: 10 }, (_, i) => isFinite(rpm[i]) ? Math.round(rpm[i]) : 0),
        hi: Array.from({ length: 10 }, (_, i) => isFinite(hi[i]) ? hi[i] : 0),
        lo: Array.from({ length: 10 }, (_, i) => isFinite(lo[i]) ? lo[i] : 0)
    };
    vesselNextStepWait(false);   // armed by commPrepFinish; the table read above was the last gap
    const backBtn = document.getElementById('rpmcap-back-btn');
    if (backBtn) backBtn.style.display = _rpmCapBack ? '' : 'none';
    const cta = document.getElementById('rpmcap-continue-btn');
    if (cta) cta.style.cssText = 'border-radius:6px; padding:8px 16px; cursor:pointer; font-size:0.9em; ' + CP_BTN_GREEN;
    document.getElementById('rpmcap-modal-overlay').style.display = 'flex';
    rpmCapRender();
}

function rpmCapRender() {
    const s = _rpmCap, u = (s.unit === 'kw') ? 'kW' : 'A';
    const step = (s.unit === 'kw') ? '0.01' : '1';
    let rows = '';
    for (let i = 0; i < 10; i++) {
        const pre = '<span class="crl-mk">' + (i === 0 ? '&lt;' : '') + '</span>';
        const suf = '<span class="crl-mk">' + (i === 9 ? '+' : '') + '</span>';
        rows +=
            '<tr>' +
            '<td><div class="crl-rpm">' + pre +
            '<input class="crl-in" type="number" step="1" min="0" value="' + s.rpm[i] + '" oninput="rpmCapEdit(' + i + ',\'rpm\',this.value)">' + suf + '</div></td>' +
            '<td><input class="crl-in" type="number" step="' + step + '" min="0" value="' + rpmCapShown(s.lo[i]) + '" oninput="rpmCapEdit(' + i + ',\'lo\',this.value)"></td>' +
            '<td><input class="crl-in" type="number" step="' + step + '" min="0" value="' + rpmCapShown(s.hi[i]) + '" oninput="rpmCapEdit(' + i + ',\'hi\',this.value)"></td>' +
            '</tr>';
    }
    document.getElementById('rpmcap-body').innerHTML =
        cxPanelOverrideStripHtml() +
        '<p style="font-size:15px;line-height:1.5;margin:0 0 12px;">Set a limit for the most charge current the alternator may produce at each engine speed. Fill in two columns: <strong>High</strong> is your system\'s full capability; <strong>Low</strong> is a gentler rate used for commissioning (recommend a third of High).</p>' +
        '<div style="display:flex; align-items:center; gap:10px; margin:0 0 12px;">' +
        '<span style="font-size:12px; color:#9cc;">Limit by</span>' +
        '<div class="cap-mode-toggle" style="background:rgba(255,255,255,0.07); border-color:#444;">' +
        '<button type="button" class="cap-mode-btn' + (s.unit === 'amps' ? ' cap-mode-active' : '') + '" onclick="rpmCapSetUnit(\'amps\')">Amps</button>' +
        '<button type="button" class="cap-mode-btn' + (s.unit === 'kw' ? ' cap-mode-active' : '') + '" onclick="rpmCapSetUnit(\'kw\')">kW</button>' +
        '</div></div>' +
        '<table class="crl-table">' +
        '<colgroup><col style="width:36%"><col style="width:32%"><col style="width:32%"></colgroup>' +
        '<thead><tr>' +
        '<th>Engine RPM</th><th>Low (' + u + ')</th><th>High (' + u + ')</th>' +
        '</tr></thead><tbody>' + rows + '</tbody></table>' +
        '<p style="color:#9aa; font-size:12.5px; margin:14px 0 0; line-height:1.5;">Between the speeds you enter, the limit follows a straight line (linear interpolation); below the first speed and above the last it holds flat.</p>' +
        '<p style="font-size:13px; margin:14px 0 0; line-height:1.5;">Commissioning runs in whichever mode you continue with \u2014 <strong style="color:#2ec4b6;">Low is recommended</strong>, so the tests stay gentle on the alternator and battery. Switch to High once commissioning is done.</p>';
}

// Render a stored amp value in the current unit (kW derived at the live battery voltage).
function rpmCapShown(amps) {
    if (_rpmCap.unit === 'kw') { const kw = ampsToKW(amps); return isFinite(kw) ? Math.round(kw * 100) / 100 : 0; }
    return isFinite(amps) ? Math.round(amps) : 0;
}
// Store an edited cell as amps (canonical); an RPM edit stores the integer breakpoint.
function rpmCapEdit(i, col, v) {
    const n = parseFloat(v);
    if (col === 'rpm') { _rpmCap.rpm[i] = isFinite(n) ? Math.round(n) : 0; return; }
    _rpmCap[col][i] = (_rpmCap.unit === 'kw') ? kwToAmps(isFinite(n) ? n : 0) : (isFinite(n) ? n : 0);
}
// Toggle Amps/kW — re-render so every cell converts at the current voltage; canonical amps are kept.
function rpmCapSetUnit(unit) {
    if (!_rpmCap || _rpmCap.unit === unit) return;
    _rpmCap.unit = unit;
    rpmCapRender();
}

// Save BOTH tables (capBothSave writes both blobs regardless of live mode) + the unit, set the chosen
// charge-rate mode, then hand off to tach alignment. mode: 0 = Low, 1 = High.
async function rpmCapContinue(mode) {
    const s = _rpmCap;
    if (s && settingsUnlocked) {
        let url = '/get?capBothSave=1';
        for (let i = 0; i < 10; i++) {
            const hiKw = ampsToKW(s.hi[i]), loKw = ampsToKW(s.lo[i]);
            url += '&rpmTableRPMPoints' + i + '=' + (s.rpm[i] || 0);
            url += '&rpmCapHi' + i + '=' + (isFinite(s.hi[i]) ? s.hi[i] : 0);
            url += '&rpmCapLo' + i + '=' + (isFinite(s.lo[i]) ? s.lo[i] : 0);
            url += '&rpmCapPwrHi' + i + '=' + (isFinite(hiKw) ? hiKw : 0);
            url += '&rpmCapPwrLo' + i + '=' + (isFinite(loKw) ? loKw : 0);
        }
        url += '&capLimitMode=' + (s.unit === 'kw' ? 1 : 0);
        // Both requests are load-bearing: proceeding past a failed one strands the wizard in the wrong
        // mode with no sign of it. Keep the screen open and make the user retry instead.
        try {
            const r = await fetchWithTimeout(buildURL(url), {}, 10000);
            if (!r.ok) throw new Error('rejected (HTTP ' + r.status + ')');
        } catch (e) {
            await xAlert('Saving the charge-rate limit tables failed — nothing was changed. Check the connection and press Continue again.\n\n' + e);
            return;
        }
        try {
            pendingToggles.set('HiLow', { desiredValue: mode, baseRev: lastSeenRev });
            await submitChargeRateModeImmediately(mode);
            setChargeRateMode(mode === 0 ? 'low' : 'high');
        } catch (e) {
            pendingToggles.delete('HiLow');
            // Deliberately does not assert which mode the device is in: a timeout here often means the
            // switch WAS applied and the reply was just slow. Continue re-sends the same value either way.
            await xAlert('Switching to ' + (mode === 0 ? 'Low' : 'High') + ' charge rate was not confirmed. Press Continue again.\n\n' + e);
            return;
        }
    }
    document.getElementById('rpmcap-modal-overlay').style.display = 'none';
    (_rpmCapNext || openRpmAlign)();
}
// ← Back to the Prerequisites screen, which now precedes this one on both the first install and a re-commission.
function rpmCapBack() {
    document.getElementById('rpmcap-modal-overlay').style.display = 'none';
    if (_rpmCapBack) _rpmCapBack();
}
// ✕ — bail out of the setup flow (does NOT open the wizard), mirroring rpmAlignCancel.
function rpmCapCancel() {
    document.getElementById('rpmcap-modal-overlay').style.display = 'none';
}

// ===== Themed alert/confirm (dark modal shell) =====
// Replaces every native xAlert()/await xConfirm() in the app. One lazily-created overlay; concurrent
// requests queue behind _xDlgQueue so a second dialog can never clobber the first's resolver.
// xConfirm resolves true ONLY on an explicit OK click. Unlike native confirm, these do not
// block the JS thread — callers await them.
let _xDlgQueue = Promise.resolve();
function _xDlgShow(msg, opts) {
    const o = opts || {};
    let ov = document.getElementById('xdlg-overlay');
    if (!ov) {
        ov = document.createElement('div');
        ov.id = 'xdlg-overlay';
        ov.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(0,0,0,0.55); z-index:11000; align-items:center; justify-content:center;';
        ov.innerHTML = '<div style="background:#1e1e1e; color:#ddd; width:430px; max-width:calc(100vw - 40px); border-radius:8px; box-shadow:0 6px 32px rgba(0,0,0,0.8); border:1px solid #444; box-sizing:border-box; max-height:calc(100vh - 60px); display:flex; flex-direction:column;">'
            + '<div style="padding:10px 16px 9px; border-bottom:1px solid #333; background:#252525; border-radius:8px 8px 0 0;">'
            + '<span id="xdlg-title" style="font-weight:600; font-size:13px; color:#aaa; letter-spacing:0.03em;"></span></div>'
            + '<div style="padding:16px 20px 18px; overflow-y:auto;">'
            + '<div id="xdlg-msg" style="font-size:13px; line-height:1.5; color:#ccc; white-space:pre-line; overflow-wrap:break-word;"></div>'
            + '<input id="xdlg-input" type="text" style="display:none; width:100%; margin-top:12px; background:#161616; color:#ddd; border:1px solid #444; border-radius:5px; padding:7px 10px; font-size:14px; box-sizing:border-box;">'
            + '<div id="xdlg-btns" style="display:flex; gap:10px; margin-top:16px;"></div>'
            + '</div></div>';
        document.body.appendChild(ov);
    }
    return new Promise(resolve => {
        document.getElementById('xdlg-title').textContent = o.title || (o.confirm ? 'Confirm' : 'Notice');
        document.getElementById('xdlg-msg').textContent = String(msg);
        const btns = document.getElementById('xdlg-btns');
        btns.innerHTML = '';
        const inp = document.getElementById('xdlg-input');
        inp.style.display = o.prompt ? 'block' : 'none';
        inp.value = '';
        let settled = false;
        const done = v => { if (settled) return; settled = true; ov.style.display = 'none'; resolve(v); };
        if (o.confirm) {
            const cancel = document.createElement('button');
            cancel.textContent = o.cancelText || 'Cancel';
            cancel.style.cssText = 'flex:1; background:#3a3a3a; border:1px solid #555; color:#ddd; border-radius:5px; padding:9px 16px; cursor:pointer; font-size:13px;';
            cancel.onclick = () => done(o.prompt ? null : false);
            btns.appendChild(cancel);
        }
        const okB = document.createElement('button');
        okB.textContent = o.okText || 'OK';
        okB.style.cssText = 'flex:1; background:linear-gradient(180deg,#35d6c7,#23a99c); color:#06302d; font-weight:700; font-size:13px; border:none; border-radius:5px; padding:9px 16px; cursor:pointer;';
        okB.onclick = () => done(o.prompt ? inp.value : true);
        btns.appendChild(okB);
        ov.style.display = 'flex';
        if (o.prompt) inp.focus(); else okB.focus();
    });
}
// Dark panel wrapper for the firmware-update overlay states (forced + manual paths).
function fuPanel(inner) {
    return `
          <div style="background:#1e1e1e; color:#ddd; width:430px; max-width:calc(100vw - 40px); border-radius:8px; box-shadow:0 6px 32px rgba(0,0,0,0.8); border:1px solid #444; box-sizing:border-box;">
            <div style="padding:10px 16px 9px; border-bottom:1px solid #333; background:#252525; border-radius:8px 8px 0 0;">
              <span style="font-weight:600; font-size:13px; color:#aaa; letter-spacing:0.03em;">Firmware Update</span>
            </div>
            <div style="padding:18px 20px 20px; font-size:0.92em; line-height:1.5; text-align:center;">${inner}</div>
          </div>`;
}
function xAlert(msg, title, opts) {
    const p = _xDlgQueue.then(() => _xDlgShow(msg, Object.assign({ title: title }, opts || {})));
    _xDlgQueue = p.then(() => { }, () => { });
    return p;
}
function xPrompt(msg, opts) {
    const p = _xDlgQueue.then(() => _xDlgShow(msg, Object.assign({ confirm: true, prompt: true }, opts || {})));
    _xDlgQueue = p.then(() => { }, () => { });
    return p;
}
function xConfirm(msg, opts) {
    const p = _xDlgQueue.then(() => _xDlgShow(msg, Object.assign({ confirm: true }, opts || {})));
    _xDlgQueue = p.then(() => { }, () => { });
    return p;
}
// For inline onsubmit handlers: an async dialog can't block a native submit, so always return
// false and re-submit programmatically on OK (form.submit() bypasses onsubmit — no loop).
function xConfirmSubmit(form, msg) {
    xConfirm(msg).then(ok => { if (ok) form.submit(); });
    return false;
}

// ===== Re-commission prompts =====
// Two triggers, both dismissible, at most one per app open. (a) A finished pass older than three years:
// a bank's internal resistance climbs as it ages, and that resistance IS the plant gain the voltage loop's
// gains were derived from — so the loop slowly gets more aggressive than commissioning intended. (b) A
// Vessel Info voltage/capacity/chemistry change, which invalidates the measured gain outright (firmware
// sets the flag inside /saveVesselInfo). Age is judged against the BROWSER clock; the device soft clock
// can be unset at sea. "Silence" persists in NVS until the next pass; "Ignore" re-asks next app open.
const RECOMMISSION_MAX_AGE_S = 3 * 365.25 * 24 * 3600;
const CX_NAV_HINT = 'To re-commission: go to Setup → Alternator → Commissioning and press Start Commissioning.';

async function checkRecommissionPrompt() {
    let r;
    try {
        const resp = await fetchWithTimeout(buildURL('/recommission.json'), {}, 8000);
        if (!resp.ok) return;
        r = await resp.json();
    } catch (e) { return; }              // offline / demo mode — never nag
    if (!r || !(r.epoch > 0)) return;    // no pass ever finished ⇒ nothing to redo

    if (r.change) {
        const silence = await xConfirm(
            'You changed a setting that affects alternator control tuning — system voltage, bank capacity, or battery chemistry.\n\n'
            + 'The voltage loop\'s gains were measured against the old bank and no longer describe this one.\n\n'
            + CX_NAV_HINT,
            { title: 'Re-commission recommended', okText: 'Silence — I will recommission now', cancelText: 'Ignore' });
        if (silence) fetch(buildURL('/recommissionAck?commissionChangeAck=1')).catch(() => { });
        return;
    }

    const ageS = Math.floor(Date.now() / 1000) - r.epoch;
    if (r.ageAck || ageS < RECOMMISSION_MAX_AGE_S) return;
    const yrs = (ageS / (365.25 * 24 * 3600)).toFixed(1);
    const silence = await xConfirm(
        'This system was last commissioned ' + yrs + ' years ago.\n\n'
        + 'A battery bank\'s internal resistance rises as it ages, and the voltage loop\'s gains were measured against what that resistance was then. Re-commissioning matches the loop to the bank you have now.\n\n'
        + CX_NAV_HINT,
        { title: 'Re-commission recommended', okText: 'Silence — I will recommission now', cancelText: 'Ignore' });
    if (silence) fetch(buildURL('/recommissionAck?commissionAgeAck=1')).catch(() => { });
}

// ===== First-boot SoC seed popup =====
// The firmware records a one-shot snapshot of the boot-time voltage seed (served at /socseed).
// Auto-opens once per device (SocSeedAck flag in NVS) after the first CSV packet — or, on a
// factory-fresh device, as a step of the first Vessel Info save chain, after the Prerequisites and
// battery-defaults screens (the firmware defers the seed until real chemistry/capacity exist).
// Reopens any time from the header SOC readout.
let _socSeedData = null;
let _socSeedResolve = null;   // resolved when the SoC popup closes, so the vessel-save chain can wait for it before commissioning

async function socSeedFetch() {
    try {
        const r = await fetchWithTimeout(buildURL('/socseed'), {}, 8000);
        if (r.ok) _socSeedData = await r.json();
    } catch (e) { diagLog('socseed fetch failed:', e); }
    return _socSeedData;
}

async function socSeedMaybeAutoOpen() {
    // Don't auto-pop over the first-run chain's screens or the commissioning modal (the chain shows this
    // popup itself, in sequence); still reachable from the header SOC readout.
    const overModal = ['commprep-modal-overlay', 'battdef-modal-overlay', 'nextstep-modal-overlay', 'commission-modal-overlay'].some(id => {
        const el = document.getElementById(id);
        return el && (el.style.display === 'flex' || el.style.display === 'block');
    });
    if (overModal) return;
    const d = await socSeedFetch();
    if (d && d.snap && !d.ack && !sessionStorage.getItem('socSeedDismissed')) socSeedOpen();
}

function socSeedClose(finish) {
    document.getElementById('socseed-modal-overlay').style.display = 'none';
    // ✕ (or Finish while settings are locked) suppresses for this session only; Finish persists the ack
    if (finish && settingsUnlocked) {
        fetch(buildURL('/get?SocSeedAck=1')).catch(() => { });
        if (_socSeedData) _socSeedData.ack = 1;
    } else {
        sessionStorage.setItem('socSeedDismissed', '1');
    }
    const r = _socSeedResolve; _socSeedResolve = null; if (r) r();
}

async function socSeedApplySoc() {
    const inp = document.getElementById('socseed-override');
    const msg = document.getElementById('socseed-override-msg');
    const v = parseFloat(inp.value);
    if (!isFinite(v) || v < 0 || v > 100) { msg.style.color = '#fca5a5'; msg.textContent = 'Enter a value from 0 to 100 %.'; return; }
    try {
        const r = await fetchWithTimeout(buildURL('/get?ManualSOCPoint=' + encodeURIComponent(v)), {}, 8000);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        document.getElementById('socseed-result-pct').textContent = Math.round(v) + ' %';
        msg.style.color = '#2ec4b6'; msg.textContent = 'State of charge set to ' + v + ' %. The charge counter restarted from this value.';
    } catch (e) {
        msg.style.color = '#fca5a5'; msg.textContent = 'Could not set SOC (' + e.message + ').';
    }
}

async function socSeedOpen() {
    if (!_socSeedData) await socSeedFetch();
    const s = _socSeedData && _socSeedData.snap;
    const body = document.getElementById('socseed-body');
    if (!body) return;
    if (!s) {
        body.innerHTML = '<div style="color:#888; padding:8px 0;">No commissioning estimate is stored on this device &mdash; on its last fresh start, the state of charge was restored from memory rather than estimated from voltage.</div>';
    } else {
        socSeedRender(s);
    }
    document.getElementById('socseed-modal-overlay').style.display = 'flex';
}

function socSeedRender(s) {
    const chemName = { lifepo4: 'LiFePO4', agm: 'AGM', lead_acid: 'Lead Acid' }[String(s.chem || '').toLowerCase()] || s.chem || 'unknown';
    const secTitle = t => '<div style="font-size:11px; font-weight:600; letter-spacing:0.06em; color:#777; text-transform:uppercase; margin:16px 0 6px;">' + t + '</div>';
    const eq = (lbl, math) => '<div style="padding:7px 0; border-bottom:1px solid #2a2a2a; font-size:13px;"><span style="color:#999; font-size:12px;">' + lbl + '</span>'
        + '<span style="display:block; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:12.5px; color:#8fd9d4; margin-top:2px; overflow-x:auto; white-space:nowrap;">' + math + '</span></div>';

    const intro = '<p style="font-size:13px; color:#bbb; margin:0 0 12px;">Calculating battery bank state of charge % based on the following inputs:</p>';

    const inputs = '<div style="display:grid; grid-template-columns:1fr auto; row-gap:5px; column-gap:12px; font-size:13px;">'
        + '<span style="color:#999;">Battery terminal voltage</span><span style="text-align:right;">' + Number(s.v).toFixed(2) + ' V</span>'
        + '<span style="color:#999;">Battery current (&minus; = discharging)</span><span style="text-align:right;">' + Number(s.i).toFixed(1) + ' A</span>'
        + '<span style="color:#999;">Board temperature</span><span style="text-align:right;">' + (s.tF == null ? 'unavailable' : Math.round(toDisplayTemp(s.tF)) + ' ' + tempUnitLabel()) + '</span>'
        + '<span style="color:#999;">Chemistry</span><span style="text-align:right;">' + _cfgEsc(chemName) + '</span>'
        + '<span style="color:#999;">Bank capacity</span><span style="text-align:right;">' + (s.cap > 0 ? s.cap + ' Ah, ' : '') + s.sysV + ' V</span>'
        + '</div>';

    const result = '<div style="display:flex; align-items:baseline; justify-content:space-between; background:#222; border:1px solid rgba(46,196,182,0.13); border-left:3px solid #2ec4b6; border-radius:6px; padding:10px 14px; margin:14px 0 2px;">'
        + '<div style="font-size:12px; color:#888;">Estimated state of charge</div>'
        + '<div id="socseed-result-pct" style="font-size:26px; font-weight:700; color:#2ec4b6;">' + s.soc + ' %</div></div>';

    let calc = '', ladder = '';
    if (s.fb) {
        calc = '<div style="color:#bbb; font-size:13px; margin-top:10px;">The battery voltage reading was not valid at boot, so the estimate fell back to 50&nbsp;%.</div>';
    } else {
        calc = secTitle('Calculation');
        calc += eq('Internal resistance, scaled for temperature',
            s.tF == null ? 'R scale = 1.00 (no temperature reading)'
                : 'R scale = e^(0.035 &times; (25 &minus; ' + ((s.tF - 32) / 1.8).toFixed(1) + ' &deg;C)) = ' + Number(s.rs).toFixed(2));
        if (s.cap > 0) {
            const rBase = s.lith ? 6 : 12;
            const rEff = rBase * s.rs * (100 / s.cap) * (s.sysV / 12);
            calc += eq('Effective resistance for this bank',
                'R = ' + rBase + ' m&Omega; &times; ' + Number(s.rs).toFixed(2) + ' &times; (100 / ' + s.cap + ' Ah) = ' + rEff.toFixed(1) + ' m&Omega;');
            calc += eq('Resting voltage (open-circuit voltage, OCV)',
                'V rest = ' + Number(s.v).toFixed(2) + ' &minus; (' + Number(s.i).toFixed(1) + ' A &times; ' + rEff.toFixed(1) + ' m&Omega;) = ' + Number(s.vocv).toFixed(3) + ' V');
        } else {
            calc += eq('Resting voltage (open-circuit voltage, OCV)',
                'Bank capacity unknown &mdash; no current correction, V rest = ' + Number(s.v).toFixed(2) + ' V');
        }
        calc += eq('Resting-voltage table, interpolated',
            Number(s.vlo).toFixed(2) + ' V = ' + s.plo + ' % &hellip; ' + Number(s.vhi).toFixed(2) + ' V = ' + s.phi + ' % &rarr; ' + s.soc + ' %');
        if (s.lith && s.vhi > s.vlo) {   // flat-plateau graphic + caveat is LiFePO4-specific; lead/AGM slope monotonically
            const pos = Math.max(0, Math.min(1, (s.vocv - s.vlo) / (s.vhi - s.vlo))) * 100;
            const knee = (s.soc <= 30)
                ? 'This reading sits on the bottom knee of the LiFePO4 curve &mdash; the one region where voltage alone gives a trustworthy state of charge.'
                : 'The LiFePO4 voltage curve is very flat in this range, so this estimate is coarse &mdash; if you know the true state of charge, set it below.';
            ladder = '<div style="margin-top:20px;">'
                + '<div style="position:relative; height:26px; border-radius:5px; background:linear-gradient(to right,#46392a 0%,#3a3a2c 35%,#2a4340 100%); border:1px solid #333;">'
                + '<div style="position:absolute; top:-5px; bottom:-5px; left:' + pos.toFixed(0) + '%; width:2px; background:#2ec4b6; box-shadow:0 0 6px rgba(46,196,182,0.67);">'
                + '<span style="position:absolute; top:-15px; left:50%; transform:translateX(-50%); font-size:10px; color:#2ec4b6; white-space:nowrap;">' + Number(s.vocv).toFixed(2) + ' V</span></div></div>'
                + '<div style="display:flex; justify-content:space-between; font-size:10px; color:#666; margin-top:4px;">'
                + '<span>' + Number(s.vlo).toFixed(2) + ' V<br>' + s.plo + ' %</span>'
                + '<span style="text-align:right;">' + Number(s.vhi).toFixed(2) + ' V<br>' + s.phi + ' %</span></div>'
                + '<div style="font-size:11px; color:#777; margin-top:6px;">' + knee + '</div></div>';
        }
    }

    const unlocked = !!settingsUnlocked;
    const override = '<div style="margin-top:16px; padding-top:12px; border-top:1px solid #333;">'
        + '<div style="font-size:11px; font-weight:600; letter-spacing:0.06em; color:#777; text-transform:uppercase;">Manual override</div>'
        + '<div style="display:flex; gap:8px; align-items:center; margin-top:6px;">'
        + '<input type="number" id="socseed-override" min="0" max="100" step="1" placeholder="' + s.soc + '"' + (unlocked ? '' : ' disabled')
        + ' style="flex:1; min-width:0; background:#161616; color:#ddd; border:1px solid #444; border-radius:5px; padding:7px 10px; font-size:14px; box-sizing:border-box;">'
        + '<span style="color:#888; font-size:13px;">%</span>'
        + '<button onclick="socSeedApplySoc()"' + (unlocked ? '' : ' disabled')
        + ' style="background:#2a2a2a; color:#bbb; font-weight:600; font-size:13px; border:1px solid #444; border-radius:5px; padding:8px 16px; cursor:pointer;' + (unlocked ? '' : ' opacity:0.45; cursor:default;') + '">Set SOC</button></div>'
        + '<div id="socseed-override-msg" style="font-size:11px; color:#777; margin-top:6px;">'
        + (unlocked ? 'If you know the true state of charge, set it here &mdash; the charge counter (coulomb counter) restarts from this value.'
            : 'Unlock settings to set a value.') + '</div></div>';

    const foot = '<div style="margin-top:14px; padding-top:10px; border-top:1px solid #333; font-size:11px; color:#777;">This is a one-time starting estimate. From here SOC tracks measured amp-hours in and out, and it self-corrects over time: every detected full charge re-anchors SOC to 100&nbsp;%, and deep discharges followed by a rest let the regulator measure the bank\'s true usable capacity.</div>';

    // _socSeedResolve is set only when this popup is a step in the first-run vessel-save chain,
    // where the Commissioning Prerequisites screen opens next — so "Next", not "Finish". Opened
    // standalone from the header SOC readout it resolves nothing and just dismisses: "Done".
    const nextLabel = _socSeedResolve ? 'Next &rarr;' : 'Done';
    const finish = '<button onclick="socSeedClose(true)" style="display:block; margin:14px auto 0; background:linear-gradient(180deg,#35d6c7,#23a99c); color:#06302d; font-weight:700; font-size:13px; border:none; border-radius:5px; padding:8px 28px; cursor:pointer;">' + nextLabel + '</button>';

    document.getElementById('socseed-body').innerHTML = intro + inputs + result + calc + ladder + foot + finish + override;
}

function populateProfileForm(profile) {
    document.getElementById('profile-username').value = profile.username || '';
    document.getElementById('profile-email').value = profile.email || '';
}


// Handle profile update/registration form submission
// Profile Update Flow:
// First time: /getAuthToken returns registered:false → calls /registerProfile → register-device edge function creates account & token
// Updates: /getAuthToken returns registered:true → calls /updateProfile → update-profile edge function validates token & updates profile
function handleProfileUpdate(event) {
    event.preventDefault();

    if (!settingsUnlocked) {
        xAlert("Please unlock settings first");
        return;
    }


    const form = document.getElementById('profile-form');
    const messageDiv = document.getElementById('profile-message');
    const formData = new FormData(form);

    const deviceUidSpan = document.getElementById('profile-device-uid');
    if (deviceUidSpan) {
        formData.append('deviceUID', deviceUidSpan.textContent);
    }
    // Identity only — the firmware's /registerProfile & /updateProfile no longer read vessel
    // fields; the cloud profile's vessel columns fill from the config snapshot.

    messageDiv.style.display = 'block';
    messageDiv.style.backgroundColor = '#e3f2fd';
    messageDiv.style.color = '#1976d2';
    messageDiv.textContent = 'Saving profile...';

    fetchWithTimeout(buildURL('/getAuthToken'), {}, 8000)
        .then(response => {
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            return response.json();
        })
        .then(data => {
            const endpoint = data.registered ? buildURL('/updateProfile') : buildURL('/registerProfile');
            return cloudOpPost(endpoint, {
                method: 'POST',
                body: formData
            }, 8000);
        })
        // Text-first parse: cloud sends JSON {success,error} on 4xx/409, but the firmware
        // can also reply with plain text (403 "Settings not armed" while locked, empty body on
        // 502/503). Reading text and tolerating a parse failure surfaces every error path
        // instead of throwing a misleading "Network error" on non-JSON replies.
        .then(response => response.text().then(text => {
            let data = {};
            try { data = text ? JSON.parse(text) : {}; } catch (e) { data = {}; }
            return { httpStatus: response.status, data, raw: text };
        }))
        .then(({ httpStatus, data, raw }) => {
            if (data.success) {
                messageDiv.style.backgroundColor = '#e8f5e9';
                messageDiv.style.color = '#2e7d32';
                messageDiv.textContent = 'Profile saved successfully!';
                isDeviceRegistered = true;
                try { sessionStorage.setItem('deviceRegistered', '1'); } catch (e) {} // cache for session — survives reloads
            } else {
                messageDiv.style.backgroundColor = '#ffebee';
                messageDiv.style.color = '#c62828';
                // Prefer the cloud's error string; fall back to raw body (e.g. "Forbidden") then status
                messageDiv.textContent = 'Error: ' + (data.error || (raw && raw.trim()) || `HTTP ${httpStatus}`);
            }
        })
        .catch(err => {
            messageDiv.style.backgroundColor = '#ffebee';
            messageDiv.style.color = '#c62828';
            messageDiv.textContent = 'Network error: ' + err.message;
        });
}

async function handleDeleteAllData() {
    if (!settingsUnlocked) {
        xAlert("Please unlock settings first");
        return;
    }

    if (!await xConfirm('WARNING: This permanently deletes your cloud account and ALL associated cloud data including history, profile, and statistics. This CANNOT be undone.\n\nYour hardware device will continue working locally, but all cloud features are reset.\n\nType DELETE in the next prompt to confirm.')) {
        return;
    }

    const confirmation = await xPrompt('Type DELETE to confirm:');
    if (confirmation !== 'DELETE') {
        xAlert('Deletion cancelled');
        return;
    }

    const formData = new FormData();

    cloudOpPost(buildURL('/deleteAllData'), {
        method: 'POST',
        body: formData
    }, 8000)
        // Text-first parse so a non-2xx cloud reply (e.g. 409, or a 403 "Forbidden" from the
        // firmware) surfaces its real error string instead of being swallowed as a bare status.
        .then(response => response.text().then(text => {
            let data = {};
            try { data = text ? JSON.parse(text) : {}; } catch (e) { data = {}; }
            return { httpStatus: response.status, data, raw: text };
        }))
        .then(({ httpStatus, data, raw }) => {
            if (data.success) {
                xAlert('Your account and all cloud data were deleted. Your device keeps working locally; cloud features have been reset.').then(() => location.reload());
            } else {
                xAlert('Error: ' + (data.error || (raw && raw.trim()) || `HTTP ${httpStatus}` || 'Deletion failed'));
            }
        })
        .catch(err => {
            xAlert('Network error: ' + err.message);
        });
}

async function resetThermalPID() {
    if (!await xConfirm('Reset the temperature controller? Its integrator and filter will be cleared and rebuilt.')) return;
    fetch(buildURL('/resetThermalPID'), { method: 'POST' })
        .then(r => r.ok ? console.log('Thermal PID reset') : console.warn('Reset failed'))
        .catch(err => console.warn('Reset error:', err));
}

async function resetInnerPID() {
    if (!await xConfirm('Reset the output current controller? Its integrator will be zeroed and field output will ramp back up from zero under the slew limit.')) return;
    fetch(buildURL('/resetInnerPID'), { method: 'POST' })
        .then(r => r.ok ? console.log('Output current PID reset') : console.warn('Reset failed'))
        .catch(err => console.warn('Reset error:', err));
}

async function resetVoltageLoop() {
    if (!await xConfirm('Reset the voltage controller integrator? The voltage loop will rebuild from zero.')) return;
    fetch(buildURL('/resetVoltageLoop'), { method: 'POST' })
        .then(r => r.ok ? console.log('Voltage loop reset') : console.warn('Reset failed'))
        .catch(err => console.warn('Reset error:', err));
}

// ===== PID TUNING SCORE LOG =====

let _tuningLogPollTimer = null;

// Run fn only while elId is actually rendered (offsetParent is null under any display:none ancestor tab)
// and the browser tab is foreground. The 1 s ticker is browser-side only; the guarded call is what hits
// the device. lastRun resets on hide so the panel refreshes the moment it comes back on screen.
function pollWhenVisible(fn, elId, periodMs) {
    let lastRun = 0;
    return setInterval(() => {
        const el = document.getElementById(elId);
        if (document.visibilityState !== 'visible' || !el || el.offsetParent === null) { lastRun = 0; return; }
        const now = Date.now();
        if (now - lastRun >= periodMs) { lastRun = now; fn(); }
    }, 1000);
}

// CSV2 imuInstallCode. Codes 1-3 all mean heel/pitch/slam are being flagged suspicious on upload and
// excluded from the leaderboards. Code 4 = no motion sensor: nothing to say, and Zero Now would be refused.
function renderImuInstallWarning(code) {
    const el = document.getElementById('imuInstallWarn');
    if (!el) return;
    let msg = '', cls = 'imu-install-warn';
    if (Number(code) === 1) {
        msg = 'Motion sensor has never been zeroed. Press Zero Now with the boat level and still. Until then, heel, pitch and slam readings are marked suspicious and excluded from the leaderboards.';
    } else if (Number(code) === 2) {
        msg = 'Motion sensor mount check failed: with the boat level and still, the up axis did not read 1 g. The regulator must be mounted on a vertical surface (bulkhead or wall), right side up. Heel, pitch and slam readings are marked suspicious.';
    } else if (Number(code) === 3) {
        msg = 'Motion sensor install has not been validated. Press Zero Now with the boat level and still. Until then, heel, pitch and slam readings are marked suspicious and excluded from the leaderboards.';
        cls += ' info';
    }
    if (!msg) { el.style.display = 'none'; return; }
    if (el.textContent !== msg) el.textContent = msg;
    if (el.className !== cls) el.className = cls;
    el.style.display = '';
}

// Diagnostic log panels poll the device. A failed poll must not leave the previous render looking live.
// The note is appended outside the <tbody> that render*() replaces, so a successful redraw can't wipe it.
function markPanelFetch(bodyId, ok) {
    const body = document.getElementById(bodyId);
    if (!body) return;
    const table = body.closest('table');
    const host = (table && table.parentElement) || body.parentElement;
    if (!host) return;
    let note = host.querySelector(':scope > .panel-fetch-note');
    if (!note) {
        note = document.createElement('div');
        note.className = 'panel-fetch-note';
        host.appendChild(note);
    }
    if (ok) {
        note.dataset.lastGood = new Date().toLocaleTimeString();
        note.textContent = 'Last good: ' + note.dataset.lastGood;
        note.classList.remove('stale');
    } else {
        note.classList.add('stale');
        note.textContent = note.dataset.lastGood
            ? 'Could not refresh — showing data from ' + note.dataset.lastGood
            : 'Could not refresh — no data yet.';
    }
}

function fetchTuningLog() {
    fetch(buildURL('/tuninglog'))
        .then(r => r.ok ? r.json() : null)
        .then(data => {
            if (data) { renderTuningLog(data); markPanelFetch('tuningLogBody', true); }
            else markPanelFetch('tuningLogBody', false);
        })
        .catch(() => markPanelFetch('tuningLogBody', false));
}

function renderTuningLog(data) {
    // Live accuracy mirror (Setup panel): data.live = [Tracking % (in-band of challenged time),
    // worst over-current (A), 0, 0]. The always-on panel in Live Data → Diag is fed off CSV2.
    const live = data.live || [];
    {
        const el0 = document.getElementById('liveScore0');
        if (el0) el0.textContent = 'Tracking: ' + (live[0] > 0 ? live[0].toFixed(1) + ' %' : '—');
        const el1 = document.getElementById('liveScore1');
        if (el1) el1.textContent = 'Peak: ' + (live[1] > 0 ? live[1].toFixed(2) + ' A' : '—');
    }

    const testRow = document.getElementById('testScoreRow');
    if (testRow) {
        if (data.ta) {
            testRow.style.display = '';
            const tsel = document.getElementById('currentTestScore');
            const ttgl = document.getElementById('testToggleCount');
            if (tsel) tsel.textContent = data.ts > 0 ? data.ts.toFixed(2) : '—';
            if (ttgl) ttgl.textContent = data.tt;
            // Push live score into the floating test panel
            if (_testPanelCurrentTest === 'curr') {
                const scored = Math.max(0, (data.tt || 0) - 4);
                updateTestPanelScore(data.ts, scored + ' scored',
                    (data.tt || 0) < 4 ? 'Ring-in (' + (data.tt || 0) + '/4)' : 'Scoring');
            }
        } else {
            testRow.style.display = 'none';
        }
    }

    // Commit section: show when TuningMode is active, update progress
    const commitSection = document.getElementById('tuningCommitSection');
    if (commitSection) {
        commitSection.style.display = data.ta ? '' : 'none';
        if (data.ta) {
            const scored  = Math.max(0, (data.tt || 0) - 4);   // ring-in is first 4 toggles
            const pct     = Math.min(100, (scored / 4) * 100);
            const ready   = scored >= 4;
            const cyclesEl = document.getElementById('tuningCyclesCount');
            const barEl    = document.getElementById('tuningCyclesBar');
            const badgeEl  = document.getElementById('tuningReadyBadge');
            const btnEl    = document.getElementById('commitTuningBtn');
            if (cyclesEl) cyclesEl.textContent = scored;
            if (barEl)    barEl.style.width = pct.toFixed(0) + '%';
            if (badgeEl)  { badgeEl.textContent = ready ? 'Ready to commit' : 'waiting…';
                            badgeEl.style.color  = ready ? '#22c55e' : '#888'; }
            if (btnEl)    btnEl.disabled = !ready;
        }
    }

    // Current settings for row highlighting
    const curKp  = parseFloat(document.getElementById('PidKp_echo')?.textContent);
    const curKi  = parseFloat(document.getElementById('PidKi_echo')?.textContent);
    const curKd  = parseFloat(document.getElementById('PidKd_echo')?.textContent);
    const curAmp = parseInt(document.getElementById('waveAmplitude_echo')?.textContent);
    const curPer = parseInt(document.getElementById('wavePeriod_echo')?.textContent);

    const records = (data.rec || []).slice();  // already sorted best-first by firmware
    const tbody = document.getElementById('tuningLogBody');
    if (!tbody) return;

    tbody.innerHTML = records.map(r => {
        const scoreColor = r.s < 5 ? '#22c55e' : r.s < 10 ? '#eab308' : '#ef4444';   // current loop: good < 5
        const isMatch = !isNaN(curKp) &&
            Math.abs(r.kp - curKp) < 0.0001 &&
            Math.abs(r.ki - curKi) < 0.0001 &&
            Math.abs(r.kd - curKd) < 0.00001 &&
            r.wa === curAmp && r.wp === curPer;
        const rowStyle = isMatch ? 'background:rgba(99,102,241,0.18);' : '';

        return `<tr style="${rowStyle}">
            <td style="padding:2px 5px;">${r.n}</td>
            <td style="padding:2px 5px;color:${scoreColor};font-weight:bold;">${r.s.toFixed(2)}</td>
            <td style="padding:2px 5px;">${r.kp.toFixed(3)}</td>
            <td style="padding:2px 5px;">${r.ki.toFixed(3)}</td>
            <td style="padding:2px 5px;">${r.kd.toFixed(4)}</td>
            <td style="padding:2px 5px;">${r.sd}</td>
            <td style="padding:2px 5px;">${r.tg.toFixed(2)}</td>
            <td style="padding:2px 5px;">${r.dr.toFixed(1)}</td>
            <td style="padding:2px 5px;">${r.wa}</td>
            <td style="padding:2px 5px;">${r.wp}</td>
            <td style="padding:2px 5px;">${r.wf != null ? r.wf : '—'}</td>
            <td style="padding:2px 5px;">${r.rpm.toFixed(0)}</td>
            <td style="padding:2px 5px;">${toDisplayTemp(r.temp).toFixed(1)}</td>
            <td style="padding:2px 5px;">${r.worst.toFixed(1)}</td>
            <td style="padding:2px 5px;">${r.t.toFixed(0)}</td>
            <td style="padding:2px 5px;">${(r.bv != null ? r.bv : 0).toFixed(2)}</td>
            <td style="padding:2px 5px;">${stageLabel(r.cs)}</td>
            <td style="padding:2px 5px;white-space:nowrap;">${fmtTuningTs(r.ts)}</td>
            <td style="padding:2px 5px;">${(r.note || '').replace(/&/g, '&amp;')}</td>
        </tr>`;
    }).join('');
}

function commitTuningScore() {
    const btn = document.getElementById('commitTuningBtn');
    const status = document.getElementById('tuningCommitStatus');
    if (btn) btn.disabled = true;
    if (status) status.textContent = 'Sending…';
    // Note: r.ok must be checked — firmware returns 403 while settings are
    // locked before the commit flag is ever set.
    fetch(buildURL('/get?commitTuningScore=1'))
        .then(r => {
            if (!r.ok) {
                if (btn) btn.disabled = false;
                if (status) status.textContent = (r.status === 403)
                    ? 'Rejected — dashboard locked. Unlock first.'
                    : ('Rejected — HTTP ' + r.status);
                return;
            }
            if (status) status.textContent = 'Committed — check Score Log.';
            setTimeout(() => { if (status) status.textContent = ''; }, 4000);
            fetchTuningLog();
        })
        .catch(() => {
            if (btn) btn.disabled = false;
            if (status) status.textContent = 'Send failed.';
        });
}

async function resetTuningLog() {
    if (!await xConfirm('Reset all tuning scores and live windows?')) return;
    fetch(buildURL('/resettuninglog'), { method: 'POST' })
        .then(() => fetchTuningLog())
        .catch(() => {});
}

// Manual reset for the Control Accuracy panel. Clears all three loops' accumulators AND the
// live excursion stopwatches on the device; the cells fall to dashes until fresh challenged
// time accrues.
async function resetAccuracyScores() {
    if (!await xConfirm('Reset the Control Accuracy numbers (tracking and excursions for all three loops)?')) return;
    fetch(buildURL('/resetAccuracyScores'), { method: 'POST' }).catch(() => {});
}

// Diagnostics expander: fetches /accstate on open and renders the raw v4 accumulators + live
// excursion state. On-demand only — kept out of CSV2.
function fetchAccState() {
    const el = document.getElementById('accStateBody');
    if (!el) return;
    el.textContent = 'Loading…';
    fetch(buildURL('/accstate'))
        .then(r => r.ok ? r.json() : null)
        .then(d => {
            if (!d) { el.textContent = 'Not available.'; return; }
            const liveLine = (L, unit) => !L.liveExc ? 'none'
                : (L.liveSide > 0 ? 'over' : 'under') + '-band excursion, '
                  + L.liveOutS.toFixed(1) + 's out of band so far' + unit;
            const loopLines = (L, over, worst) =>
                '   in authority ' + fmtT(L.validS) + ' — challenged ' + fmtT(L.activeS)
                + ' (in band ' + fmtT(L.inbandS) + '), constrained ' + fmtT(L.constS)
                + '\n   excursions: ' + L.exc + ', out-of-band total ' + L.recovS.toFixed(1) + 's'
                + '\n   damaging exposure: ' + over + ', worst ' + worst;
            el.textContent =
                'Current loop\n' + loopLines(d.cur, d.cur.overExp.toFixed(1) + ' A·s', d.cur.worst.toFixed(2) + ' A')
                + '\n   live: ' + liveLine(d.cur, '')
                + '\n\nVoltage loop\n' + loopLines(d.volt, d.volt.overExpMv.toFixed(0) + ' mV·s', d.volt.worstMv.toFixed(0) + ' mV')
                + '\n   live: ' + liveLine(d.volt, '')
                + '\n\nThermal loop\n   containment sessions: ' + d.therm.sessions
                + ', binding ' + fmtT(d.therm.bindS) + ' (in band ' + fmtT(d.therm.inbandS) + ')'
                + '\n   worst over limit: ' + toDisplayTempDelta(d.therm.worstF).toFixed(1) + ' ' + tempUnitLabel();
        })
        .catch(() => { el.textContent = 'Not available.'; });
}

// ===== Overvoltage History (Live Data ▸ Diag) =====
// Lifetime OV histogram + counters from device RTC RAM (/getOvTelemetry), fetched when the
// section opens. Band edges are built from the returned bulk + k (SYSTEM_VOLTAGE_CLASS/12), so
// nothing is hardcoded client-side; time_ms arrives as decimal strings (uint64-safe).
function fetchOvTelemetry() {
    const body = document.getElementById('ovtBinsBody');
    fetch(buildURL('/getOvTelemetry'))
        .then(r => r.ok ? r.json() : null)
        .then(d => {
            if (!d) { if (body) body.innerHTML = '<tr><td colspan="3" style="padding:6px 0;color:var(--text-muted);">Not available.</td></tr>'; return; }
            const put = (id, v) => { const e = document.getElementById(id); if (e) e.textContent = v; };
            put('ovtSoftCount', d.soft);
            put('ovtSwHardCount', d.sw_hard);
            put('ovtInaCount', d.ina);
            put('ovtKdCount', d.kd !== undefined ? d.kd : '—');
            put('ovtTierLowCount', d.tier_low !== undefined ? d.tier_low : '—');
            put('ovtTierMidCount', d.tier_mid !== undefined ? d.tier_mid : '—');
            if (!body) return;
            const fineW = d.fine_width_12v * d.k, coarseW = d.coarse_width_12v * d.k;
            const fineTop = d.bulk + d.bins_fine * fineW;
            const nBins = d.bins_fine + d.bins_coarse + 1;
            const binLo = i => i < d.bins_fine ? d.bulk + i * fineW
                : i < d.bins_fine + d.bins_coarse ? fineTop + (i - d.bins_fine) * coarseW
                : fineTop + d.bins_coarse * coarseW;
            const fmtDwell = ms => ms >= 90000 ? (ms / 60000).toFixed(2) + ' min' : (ms / 1000).toFixed(2) + ' s';
            let lastActive = -1;
            for (let i = 0; i < nBins; i++) if (d.events[i] || Number(d.time_ms[i])) lastActive = i;
            // One zero row above the highest active band, so the table shows coverage continues upward
            // (an empty histogram shows band 0 as its zero row).
            const capRow = Math.min(lastActive + 1, nBins - 1);
            let rows = '';
            for (let i = 0; i <= capRow; i++) {
                const ev = d.events[i], ms = Number(d.time_ms[i]);
                if (!ev && !ms && i !== capRow) continue;
                const band = (i === nBins - 1)
                    ? '≥ ' + binLo(i).toFixed(2) + ' V'
                    : binLo(i).toFixed(2) + ' – ' + binLo(i + 1).toFixed(2) + ' V';
                rows += '<tr style="border-top:1px solid var(--border);">'
                    + '<td style="padding:5px 6px 5px 0;color:var(--text-muted);white-space:nowrap;">' + band + '</td>'
                    + '<td style="padding:5px 8px;text-align:right;font-weight:600;">' + ev + '</td>'
                    + '<td style="padding:5px 0 5px 8px;text-align:right;font-weight:600;white-space:nowrap;">' + fmtDwell(ms) + '</td>'
                    + '</tr>';
            }
            body.innerHTML = rows || '<tr><td colspan="3" style="padding:6px 0;color:var(--text-muted);">No time above the Bulk target recorded yet.</td></tr>';
        })
        .catch(() => { if (body) body.innerHTML = '<tr><td colspan="3" style="padding:6px 0;color:var(--text-muted);">Not available.</td></tr>'; });
}

function resetOvTelemetryLifetime() {
    xConfirm('This permanently clears the lifetime overvoltage history — the histogram and the three lifetime counters that survive restarts and firmware updates. The session counters on the Protections tab are not affected. Clear it?').then(ok => {
        if (!ok) return;
        fetch(buildURL('/resetOvTelemetryLifetime'), { method: 'POST' })
            .then(() => fetchOvTelemetry())
            .catch(() => { });
    });
}

// ── Oscillation damper (hunt governor) — Live Data ▸ Diag ▸ Alternator ─────────────────────
// Live state rides CSV1 (huntDerate / huntFreqHz / huntState) so gain and state can never
// disagree by a frame; the episode table is the device's own /huntledger.csv, re-read on open.
// The verdict strings below are the firmware's internal tokens — map them, never print raw.
const HG_VERDICT = {
    'damped': 'Wobble stopped',
    'damped-partial': 'Wobble halved — reduced gain kept',
    'external-suspected': 'Not the regulator — full gain restored',
    'aborted': 'Not concluded — gain test interrupted, conditions changed',
    'recovered': 'Settled on its own',
    'damped-dterm': 'Wobble stopped — voltage damper switched off here',
    'dterm-no-resp': 'Voltage damper was not the cause — turned back on',
    // Rows written before the abort verdicts were split carry plain 'aborted' for BOTH levers;
    // they render as a gain test and cannot be told apart retroactively.
    'aborted-dterm': 'Not concluded — voltage damper test interrupted, conditions changed',
};

// Wording is driven by state first, gain second: the derate alone cannot separate "inside a
// mapped trouble spot" from "testing a cut right now", and those mean different things.
function hgStateWord(state, pct, enabled) {
    if (enabled === false) return 'Off — hunting persists at full gain';
    switch (state) {
        case 1: return 'Testing — gain cut applied, measuring whether the wobble responds';
        case 4: return 'Testing — voltage damper paused, measuring whether the wobble responds';
        case 3: return 'Cooling down — the last wobble did not respond to the gain cut';
        default: return pct >= 100 ? 'Watching — no trouble spot at this speed, full gain'
                                   : 'In a mapped trouble spot — running reduced gain';
    }
}

// The master switch appears twice: the canonical row in Setup > Alternator > Tuning > Current >
// Controller Parameters (next to the PID Ki it derates) and a mirror in this Diag card, which is the
// screen a user is actually on when they decide to switch it off. Both post the same HuntGovEnable;
// this keeps the other checkbox visually in step during the ~1 s before the firmware echo lands,
// because updateCheckbox() freezes BOTH while the toggle is pending.
function huntGovToggle(el, checkboxId, hiddenId, mirrorId) {
    if (!handleUserToggle(checkboxId, hiddenId, 'HuntGovEnable')) return;
    const mirror = document.getElementById(mirrorId);
    if (mirror) mirror.checked = el.checked;
    el.form.submit();
    submitMessage();
}

function huntGovLiveOnCsv1(data) {
    const s = document.getElementById('hgStateText');
    if (!s) return;
    const on = getEchoText('HuntGovEnable_echo', '') === 'OFF' ? false : true;
    const pct = Math.round((data.huntDerate !== undefined ? Number(data.huntDerate) : 100));
    const state = data.huntState !== undefined ? Number(data.huntState) : 0;
    const freq = (data.huntFreqHz !== undefined ? Number(data.huntFreqHz) : 0) / 100;
    s.textContent = hgStateWord(state, pct, on);
    const g = document.getElementById('hgGainPct');
    if (g) g.textContent = on ? pct + '%' : '100%';
    const f = document.getElementById('hgFreqNow');
    if (f) f.textContent = (on && freq > 0) ? freq.toFixed(2) + ' Hz' : 'none';
    // A test just concluded (state left 1/4): the episode record and map changed on the device —
    // re-pull them if the section is open, so the list and plot can never sit stale against the
    // live status line. 1.5 s grace lets the firmware queue the record first.
    if (hgPrevHuntState !== null && hgPrevHuntState !== state
        && (hgPrevHuntState === 1 || hgPrevHuntState === 4)) {
        const det = document.getElementById('hgLedgerList');
        const sec = det && det.closest('details');
        if (sec && sec.open) setTimeout(fetchHuntLedger, 1500);
    }
    hgPrevHuntState = state;
    // Live engine-speed marker on the speed map: redraw at most 1/s, only when the plot is on
    // screen and the marker would visibly move.
    hgNowRpm = 'RPM' in data ? Number(data.RPM) || 0 : 0;
    if (hgMapU && Date.now() - hgNowLastDrawMs > 1000 && Math.abs(hgNowRpm - hgNowDrawnRpm) >= 5) {
        // offsetParent forces a style/layout flush, so the visibility test is read last: only on
        // the ~1/s frames that already cleared the throttle, never on every 10 Hz CSV1 frame.
        const mapEl = document.getElementById('hgMapPlot');
        if (mapEl && mapEl.offsetParent) {
            hgNowLastDrawMs = Date.now();
            hgMapU.redraw();
        }
    }
}

// Voltage-damper (D-term) lever readout — CSV2 cadence is plenty (it moves on pocket entry/exit
// and test open/close). Old firmware without the field leaves the row at its placeholder.
function huntGovLiveOnCsv2(data) {
    const el = document.getElementById('hgKdState');
    if (!el || data.huntKdScale === undefined) return;
    const pct = Number(data.huntKdScale);
    el.textContent = pct >= 99 ? 'Running' : pct <= 1 ? 'Off at this speed' : 'Reduced (pocket edge)';
}

function fetchHuntLedger() {
    const list = document.getElementById('hgLedgerList');
    const count = document.getElementById('hgEpisodeCount');
    const link = document.getElementById('hgRawLink');
    if (link) link.href = buildURL('/huntledger');   // Capacitor: a bare /huntledger href resolves to localhost
    // note() covers every empty/error path, so it also hides the episode map — the map only
    // ever shows in the success path below, fed from the same parse as the list.
    const note = m => {
        if (list) list.innerHTML = '<div style="padding:6px 0;color:var(--text-muted);">' + m + '</div>';
        const w = document.getElementById('hgMapWrap');
        if (w) w.style.display = 'none';
    };
    fetch(buildURL('/huntledger'))
        .then(r => r.ok ? r.text() : null)
        .then(t => {
            if (t === null) { note('Not available.'); if (count) count.textContent = '—'; return; }
            // Firmware serves a plain sentence, not a CSV, until the first episode is written.
            const lines = t.trim().split('\n').map(l => l.trim()).filter(l => l.length);
            const rows = (lines.length && lines[0].indexOf('epoch,') === 0) ? lines.slice(1) : [];
            if (count) count.textContent = rows.length ? String(rows.length) : 'none';
            if (!rows.length) {
                // Don't claim "never detected" until the map confirms there are no pockets either —
                // pockets can outlive their evidence rows (ledger cap-trim), and a freshly-mapped
                // pocket's record may not be readable yet. renderHuntMap fetches /huntmap and
                // writes the honest note for whichever case holds.
                renderHuntMap([], true);
                return;
            }
            let html = '';
            const eps = [];   // parsed once here, shared with the episode map
            for (let i = rows.length - 1; i >= 0; i--) {      // newest first
                const c = rows[i].split(',');
                if (c.length < 9) continue;
                const epoch = Number(c[0]), rpm = Number(c[1]), cv = Number(c[2]);
                const freq = Number(c[3]), a0 = Number(c[4]), aEnd = Number(c[5]);
                const steps = Number(c[6]), verdict = c[7], derate = Number(c[8]);
                eps.push({ rpm: rpm, verdict: verdict, derate: derate });
                // Episodes logged before the clock synced carry a meaningless epoch — say so
                // rather than printing 1970.
                const when = epoch > 1577836800 ? new Date(epoch * 1000).toLocaleString()
                                                : 'time unknown — logged before clock sync';
                // D-lever records carry the voltage-movement metric (V/s), not field swing — the
                // D-driven wobble lives in volts and barely registers in the field drive.
                // Which lever an abort was testing comes from the verdict token alone — both abort
                // rows log steps = 1, so steps can never be used to tell them apart.
                const isAbort = (verdict === 'aborted' || verdict === 'aborted-dterm');
                const isDterm = (verdict === 'damped-dterm' || verdict === 'dterm-no-resp' || verdict === 'aborted-dterm');
                const facts = [
                    (rpm > 0 ? rpm + ' rpm' : 'engine speed not recorded'),
                    (cv ? 'voltage-limited' : 'current-limited'),
                    freq.toFixed(2) + ' Hz wobble',
                    // "aborted" is logged with no end amplitude — the episode never reached a verdict.
                    // Its aEnd is a 0 placeholder meaning "no post reading exists", so no abort row
                    // may ever print an end value; the baseline unit follows the lever.
                    (isAbort ? (isDterm ? 'voltage movement ' + a0.toFixed(2) + ' V/s at the start'
                                        : 'field swing ' + a0.toFixed(1) + '% at the start')
                        : isDterm ? 'voltage movement ' + a0.toFixed(2) + ' → ' + aEnd.toFixed(2) + ' V/s'
                                  : 'field swing ' + a0.toFixed(1) + '% → ' + aEnd.toFixed(1) + '%'),
                    (isAbort ? (isDterm ? 'voltage damper test, no result' : 'current-loop gain test, no result')
                        : isDterm ? 'voltage damper paused' : steps === 1 ? '1 gain cut' : steps + ' gain cuts'),
                    'gain left at ' + Math.round(derate * 100) + '%',
                ];
                html += '<div style="border-top:1px solid var(--border);padding:7px 0;">'
                    + '<div style="display:flex;justify-content:space-between;gap:10px;align-items:baseline;flex-wrap:wrap;">'
                    + '<span style="font-weight:600;">' + (HG_VERDICT[verdict] || verdict) + '</span>'
                    + '<span style="color:var(--text-muted);font-size:0.92em;">' + when + '</span>'
                    + '</div>'
                    + '<div style="color:var(--text-muted);margin-top:2px;line-height:1.5;">' + facts.join(' · ') + '</div>'
                    + '</div>';
            }
            if (list) list.innerHTML = html || '<div style="padding:6px 0;color:var(--text-muted);">No readable episodes in the record.</div>';
            renderHuntMap(eps);
        })
        .catch(() => { note('Not available.'); if (count) count.textContent = '—'; });
}

// ── Speed map: live gain-vs-speed profile (trapezoid pockets from /huntmap) + episode dots ──
// The firmware's pocket map IS the control rule; this plot draws it verbatim: full gain
// everywhere, the Damped Gain across each pocket core, linear taper over the wings. Dots are
// ledger evidence (blue filled = verified, amber hollow = did not respond, grey hollow = the test
// was interrupted and concluded nothing); the dashed vertical is the live engine speed off CSV1. Colors are fixed and CVD-validated against both card
// surfaces; axis/grid theming comes from the uPlot wrapper.
let hgMapU = null;
let hgMapData = { xs: [], profile: [], kept: [], rest: [], xlo: 0, xhi: 1000 };
let hgMapState = { pockets: [], cut: 50, wing: 15, enabled: 1 };
let hgNowRpm = 0;
let hgNowDrawnRpm = -1;
let hgNowLastDrawMs = 0;
let hgPrevHuntState = null;   // last huntState seen on CSV1 — a transition out of testing re-pulls the ledger/map

// JS mirror of the firmware's huntMapGain(), in percent — Ki pockets (lever 0) only; D pockets
// (lever 1) act on the voltage damper, not this gain, and draw as their own shading. Damper off =
// firmware applies full gain everywhere, so the profile draws flat; shading and dots still show
// the retained map.
function hgProfileGain(r) {
    if (!hgMapState.enabled) return 100;
    const cut = hgMapState.cut, wing = hgMapState.wing / 100;
    let g = 100;
    hgMapState.pockets.forEach(p => {
        if (Number(p.lever) === 1) return;
        const wLo = p.lo * (1 - wing), wHi = p.hi * (1 + wing);
        if (r < wLo || r > wHi) return;
        let gi;
        if (r < p.lo) gi = 100 - (100 - cut) * (r - wLo) / (p.lo - wLo);
        else if (r > p.hi) gi = 100 - (100 - cut) * (wHi - r) / (wHi - p.hi);
        else gi = cut;
        if (gi < g) g = gi;
    });
    return g;
}

function hgMapXRange() { return [hgMapData.xlo, hgMapData.xhi]; }

// Fixed 105 ceiling; floor follows the deepest value on screen so an empty map still frames sanely
function hgMapYRange() {
    let mn = 100;
    hgMapData.profile.forEach(v => { if (v != null && v < mn) mn = v; });
    hgMapData.kept.forEach(v => { if (v != null && v < mn) mn = v; });
    hgMapData.rest.forEach(v => { if (v != null && v < mn) mn = v; });
    (hgMapData.dkept || []).forEach(v => { if (v != null && v < mn) mn = v; });
    (hgMapData.abrt || []).forEach(v => { if (v != null && v < mn) mn = v; });
    return [Math.max(0, Math.min(80, Math.floor((mn - 8) / 10) * 10)), 105];
}

// Entry point from fetchHuntLedger: pulls the live map, then draws it with the episode dots.
// A failed /huntmap (old firmware, demo mode) degrades to a flat full-gain line + dots.
// noEpisodeRows: the ledger parse found nothing — the note under the list is written HERE, after
// the map answers whether pockets exist, so the text can never contradict the live status line.
function renderHuntMap(eps, noEpisodeRows) {
    fetch(buildURL('/huntmap'))
        .then(r => r.ok ? r.json() : null)
        .catch(() => null)
        .then(map => {
            hgMapState = (map && Array.isArray(map.pockets))
                ? { pockets: map.pockets, cut: Number(map.cut) || 50, wing: Number(map.wing) || 15,
                    enabled: map.enabled === undefined ? 1 : Number(map.enabled) }
                : { pockets: [], cut: 50, wing: 15, enabled: 1 };
            if (noEpisodeRows) {
                const list = document.getElementById('hgLedgerList');
                if (list) list.innerHTML = '<div style="padding:6px 0;color:var(--text-muted);">'
                    + (hgMapState.pockets.length
                        ? 'The speed map below is active, but its episode details could not be read just now — press Re-read episode record.'
                        : 'No wobble has ever been detected on this regulator — there has been nothing to damp. This is the normal, healthy case.')
                    + '</div>';
            }
            hgMapBuild(eps || []);
        });
}

function hgMapBuild(eps) {
    const wrap = document.getElementById('hgMapWrap');
    const el = document.getElementById('hgMapPlot');
    if (!wrap || !el) return;
    const pts = eps.filter(e => e.rpm > 0);   // rpm 0 = engine speed not recorded — unplottable
    const excl = document.getElementById('hgMapExcluded');
    if (excl) {
        const n = eps.length - pts.length;
        excl.textContent = n === 0 ? ''
            : n === 1 ? '1 episode without an engine speed is not shown'
                      : n + ' episodes without an engine speed are not shown';
    }
    if ((!pts.length && !hgMapState.pockets.length) || typeof uPlot === 'undefined') { wrap.style.display = 'none'; return; }
    wrap.style.display = '';
    const wing = hgMapState.wing / 100;
    let xlo = Infinity, xhi = -Infinity;
    hgMapState.pockets.forEach(p => { xlo = Math.min(xlo, p.lo * (1 - wing)); xhi = Math.max(xhi, p.hi * (1 + wing)); });
    pts.forEach(e => { xlo = Math.min(xlo, e.rpm); xhi = Math.max(xhi, e.rpm); });
    const pad = Math.max(80, 0.12 * (xhi - xlo));
    xlo = Math.max(0, xlo - pad);
    xhi = xhi + pad;
    // x list: domain ends + every trapezoid vertex + every dot speed, ascending (duplicates fine)
    const xset = [xlo, xhi];
    hgMapState.pockets.forEach(p => { xset.push(p.lo * (1 - wing), p.lo, p.hi, p.hi * (1 + wing)); });
    pts.forEach(e => xset.push(e.rpm));
    xset.sort((a, b) => a - b);
    const xs = [], profile = [], kept = [], rest = [], dkept = [], abrt = [];
    xset.forEach(x => { xs.push(x); profile.push(hgProfileGain(x)); kept.push(null); rest.push(null); dkept.push(null); abrt.push(null); });
    pts.forEach(e => {   // first free slot matching this rpm, so same-speed episodes each keep a dot
        for (let i = 0; i < xs.length; i++) {
            if (xs[i] !== e.rpm || kept[i] !== null || rest[i] !== null || dkept[i] !== null || abrt[i] !== null) continue;
            if (e.verdict === 'damped' || e.verdict === 'damped-partial') kept[i] = e.derate * 100;
            // D-verified dot sits at the Ki gain (usually 100%) — the pocket it made acts on the
            // voltage damper, drawn as purple shading, not on this line
            else if (e.verdict === 'damped-dterm') dkept[i] = e.derate * 100;
            // An interrupted test proved nothing about the belt or the engine governor, so it can
            // never share the amber "did not respond" series — that verdict is a real finding.
            else if (e.verdict === 'aborted' || e.verdict === 'aborted-dterm') abrt[i] = e.derate * 100;
            else rest[i] = e.derate * 100;
            break;
        }
    });
    hgMapData = { xs: xs, profile: profile, kept: kept, rest: rest, dkept: dkept, abrt: abrt, xlo: xlo, xhi: xhi };
    if (hgMapU) { hgMapU.setData([xs, profile, kept, rest, dkept, abrt]); return; }   // setData re-runs the range fns
    const opts = {
        width: plotFitWidth(el, 280),
        height: 200,
        padding: [10, 8, 0, 0],
        series: [
            { label: 'rpm' },
            { label: 'gain', stroke: '#3a7bd5', width: 2, points: { show: false } },
            { label: 'verified', stroke: '#3a7bd5', paths: () => null,
              points: { show: true, size: 8, fill: '#3a7bd5', stroke: '#3a7bd5' } },
            { label: 'no response', stroke: '#c07f2f', paths: () => null,
              points: { show: true, size: 8, width: 1.8, fill: 'transparent', stroke: '#c07f2f' } },
            { label: 'voltage damper off', stroke: '#8256b0', paths: () => null,
              points: { show: true, size: 8, fill: '#8256b0', stroke: '#8256b0' } },
            { label: 'not concluded', stroke: '#8d8f95', paths: () => null,
              points: { show: true, size: 8, width: 1.8, fill: 'transparent', stroke: '#8d8f95' } },
        ],
        scales: {
            x: { time: false, range: () => hgMapXRange() },
            y: { auto: false, range: () => hgMapYRange() },
        },
        axes: [
            { grid: { show: true }, values: (u, t) => t.map(v => String(v)) },
            { scale: 'y', grid: { show: true }, side: 3, values: (u, t) => t.map(v => v + '%') },
        ],
        legend: { show: false },
        cursor: { drag: { x: false, y: false } },
        hooks: {
            // drawAxes fires after grid/axes but before series, so shading sits UNDER line and dots
            drawAxes: [u => {
                const ctx = u.ctx; ctx.save();
                ctx.beginPath(); ctx.rect(u.bbox.left, u.bbox.top, u.bbox.width, u.bbox.height); ctx.clip();
                const wg = hgMapState.wing / 100;
                hgMapState.pockets.forEach(p => {
                    // Ki pockets blue, voltage-damper (D) pockets purple — independent rules that may overlap
                    ctx.fillStyle = Number(p.lever) === 1 ? 'rgba(130,86,176,0.12)' : 'rgba(58,123,213,0.10)';
                    const x0 = u.valToPos(p.lo * (1 - wg), 'x', true), x1 = u.valToPos(p.hi * (1 + wg), 'x', true);
                    ctx.fillRect(x0, u.bbox.top, x1 - x0, u.bbox.height);
                });
                ctx.restore();
            }],
            draw: [u => {
                if (!(hgNowRpm > 0) || hgNowRpm < hgMapData.xlo || hgNowRpm > hgMapData.xhi) return;
                const ctx = u.ctx; ctx.save();
                const x = u.valToPos(hgNowRpm, 'x', true);
                ctx.strokeStyle = 'rgba(192,127,47,0.9)'; ctx.lineWidth = 1.5; ctx.setLineDash([5, 4]);
                ctx.beginPath(); ctx.moveTo(x, u.bbox.top); ctx.lineTo(x, u.bbox.top + u.bbox.height); ctx.stroke();
                ctx.setLineDash([]);
                ctx.fillStyle = 'rgba(192,127,47,0.95)'; ctx.font = '11px sans-serif'; ctx.textAlign = 'left';
                ctx.fillText('now', x + 5, u.bbox.top + 14);
                hgNowDrawnRpm = hgNowRpm;
                ctx.restore();
            }],
        },
    };
    hgMapU = new uPlot(opts, [xs, profile, kept, rest, dkept, abrt], el);
    new ResizeObserver(() => {
        if (hgMapU) hgMapU.setSize({ width: plotFitWidth(el, 280), height: 200 });
    }).observe(el);
}

// Clear System: pockets + episode record + any test in flight, all together, on the device.
// Arm-gated on the firmware side like every other mutation — a locked dashboard gets a 403.
async function clearHuntSystem() {
    if (!await xConfirm('Permanently erase everything the Oscillation Damper has learned — the speed map AND the episode record? Gain returns to 100% everywhere until a new wobble is verified. This cannot be undone.')) return;
    const status = document.getElementById('hgClearStatus');
    fetch(buildURL('/huntclear'), { method: 'POST' })
        .then(r => {
            if (!r.ok) {
                if (status) status.textContent = (r.status === 403)
                    ? 'Rejected — dashboard locked. Unlock first.'
                    : ('Rejected — HTTP ' + r.status);
                return;
            }
            if (status) status.textContent = 'Cleared.';
            setTimeout(() => { if (status) status.textContent = ''; }, 4000);
            fetchHuntLedger();
        })
        .catch(() => { if (status) status.textContent = 'Send failed.'; });
}

function commitCVTuningScore() {
    const btn = document.getElementById('commitCVTuningBtn');
    const status = document.getElementById('cvTuningCommitStatus');
    if (btn) btn.disabled = true;
    if (status) status.textContent = 'Sending…';
    // Note: r.ok must be checked — firmware returns 403 while settings are
    // locked before the commit flag is ever set.
    fetch(buildURL('/get?commitCVTuningScore=1'))
        .then(r => {
            if (!r.ok) {
                if (btn) btn.disabled = false;
                if (status) status.textContent = (r.status === 403)
                    ? 'Rejected — dashboard locked. Unlock first.'
                    : ('Rejected — HTTP ' + r.status);
                return;
            }
            if (status) status.textContent = 'Committed — check Score Log.';
            setTimeout(() => { if (status) status.textContent = ''; }, 4000);
            fetchCVTuningLog();
        })
        .catch(() => {
            if (btn) btn.disabled = false;
            if (status) status.textContent = 'Send failed.';
        });
}

function restartCVTest() {
    const status = document.getElementById('cvTuningCommitStatus');
    if (status) status.textContent = 'Restarting…';
    fetch(buildURL('/get?restartCVTest=1'))
        .then(r => {
            if (!r.ok) {
                if (status) status.textContent = (r.status === 403)
                    ? 'Rejected — dashboard locked. Unlock first.'
                    : ('Rejected — HTTP ' + r.status);
                return;
            }
            if (status) status.textContent = 'Restarted.';
            setTimeout(() => { if (status) status.textContent = ''; }, 3000);
            fetchCVTuningLog();
        })
        .catch(() => {
            if (status) status.textContent = 'Send failed.';
        });
}

// Boat loading splash: the inline script in index.html shows it immediately on a
// Capacitor cold launch (themed, flash-free). It hides on the first CSVData packet
// (CSVData listener below) or when demo mode starts. hideWaitingForRegulator() is
// idempotent and fades the overlay out. The safety timeout below guarantees it can
// never stick if neither real nor demo telemetry ever arrives.
window._firstCsvPacketReceived = false;
function hideWaitingForRegulator() {
    const el = document.getElementById('waiting-for-regulator');
    if (!el || el._wfrHidden) return;
    el._wfrHidden = true;
    el.classList.add('wfr-hiding');
    setTimeout(() => { el.style.display = 'none'; }, 480);
}

// Delay applied to the Diag fast-scope kick when Diag is entered by the cold-open landing (below),
// so first paint and telemetry wiring finish before the waveform/flipbook fetches start. Consumed
// (and cleared) by the one showSubTab('livedata','diag') that follows.
let diagScopeKickDelayMs = 0;
const COLD_OPEN_SCOPE_DELAY_MS = 4000;

// Phone-sized screens only: coarse pointer rules out a laptop in a narrow window, and the SHORTER
// viewport edge catches a phone held either way (landscape width is ~850, its height ~400).
// Tablets sit well above this (iPad portrait's short edge is 768) and are not nudged.
function _isPhoneSizedScreen() {
    try {
        const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
        return !!coarse && Math.min(window.innerWidth, window.innerHeight) <= 600;
    } catch (e) { return false; }
}

// Recommendation, never a gate: setup is a long form plus a wizard with tables and plots, and it is
// done once. Fires only on the incomplete-vessel-info landing, so it cannot reach a set-up boat.
// The address is quoted live — API_BASE_URL in the app (discovered IP, else alternator.local), the
// page's own origin in a browser — so the user has something to type rather than "this address".
function smallScreenSetupMsg() {
    let addr = '';
    try { addr = IS_CAPACITOR ? API_BASE_URL : window.location.origin; } catch (e) { addr = ''; }
    if (!addr || addr.indexOf('demo.invalid') >= 0) addr = 'http://alternator.local';
    return 'First-time setup goes much easier on a laptop or desktop browser than on a phone.\n\n'
        + 'Vessel Info is a long form, and the commissioning that follows it shows tables and plots '
        + 'that need room to read.\n\n'
        + 'On a laptop joined to the same network, browse to:\n' + addr + '\n\n'
        + 'Everyday monitoring is fine on a phone — it is the one-time setup that wants the bigger screen.';
}

// Landing tab, applied once on open: always Live Data → Diag, so Charging System Health is the
// first thing seen (fixed destination — the field state must not decide what the user sees first).
// Vessel Info incomplete overrides to Setup.
function applyLandingTab() {
    try {
        if (!vesselInfoComplete) {
            showMainTab('settings');
            showSubTab('settings', 'vessel-info');
            if (_isPhoneSizedScreen()) xAlert(smallScreenSetupMsg(), 'Recommended: Set Up On A Laptop', { okText: 'Continue anyway' });
            return;
        }
        showMainTab('livedata');
        // Diag's fast scope pulls a waveform + the flipbook the moment the tab shows; on a cold
        // open that competes with the rest of the app coming up. Hand showSubTab a delay for this
        // one entry only — manual Diag clicks stay immediate.
        diagScopeKickDelayMs = COLD_OPEN_SCOPE_DELAY_MS;
        showSubTab('livedata', 'diag');
    } catch (err) {}
}

// Hold until both signals are ready: first telemetry packet (device is talking, splash gone) and
// the vessel-info fetch (vesselInfoComplete). Guards the fetch-vs-packet race; runs once.
window._vesselInfoLoaded = false;
window._landingApplied = false;
function maybeApplyLanding() {
    if (window._landingApplied) return;
    if (!window._firstCsvPacketReceived || !window._vesselInfoLoaded) return;
    window._landingApplied = true;
    applyLandingTab();
    checkRecommissionPrompt().catch(() => { });   // once per app open; self-suppresses when nothing is due
}
document.addEventListener('DOMContentLoaded', () => {
    // The splash is visible by default (see index.html) and hides on the first
    // CSVData packet or when demo mode starts. This safety net guarantees it can
    // never stick if neither ever arrives. In a normal browser the page is served
    // by the device, so the first packet clears it almost immediately.
    setTimeout(() => { if (!window._firstCsvPacketReceived) hideWaitingForRegulator(); }, 20000);
});

// Poll while the tuning score section is open
document.addEventListener('DOMContentLoaded', () => {
    const section = document.getElementById('tuningScoreSection');
    if (!section) return;
    section.addEventListener('toggle', e => {
        if (e.target.open) {
            fetchTuningLog();
            _tuningLogPollTimer = setInterval(fetchTuningLog, 1000);
        } else {
            clearInterval(_tuningLogPollTimer);
            _tuningLogPollTimer = null;
        }
    });
});

// ── CV Tuning Log ──────────────────────────────────────────────────────────
let _cvTuningLogPollTimer = null;

function fetchCVTuningLog() {
    fetch(buildURL('/cvtuninglog'))
        .then(r => r.ok ? r.json() : null)
        .then(data => { if (data) renderCVTuningLog(data); })
        .catch(() => {});
}

// Shared s/m/h formatter for the Control Accuracy panel + its diagnostics expander.
function fmtT(s) {
    return !(s > 0) ? '0s' : (s < 90 ? Math.round(s) + 's'
        : (s < 5400 ? (s / 60).toFixed(1) + 'm' : (s / 3600).toFixed(1) + 'h'));
}

// Control Accuracy cell writer with render-stamp caching. Dash rule keys on `observedS`
// (the metric's own denominator), NOT the value: 0 observed → "—" ("not observed" is never
// shown as "perfect"). higherBetter=true colors green ABOVE the first threshold (tracking %);
// false colors green BELOW it (recovery time).
function accCell(elId, txt, v, t1, t2, higherBetter, observedS) {
    const el = document.getElementById(elId);
    if (!el) return;
    let color;
    if (!(observedS > 0)) { txt = '—'; color = 'var(--text-muted)'; }
    else if (higherBetter) color = v >= t1 ? '#21c25e' : (v >= t2 ? '#f08c1d' : '#ef4444');
    else color = v < t1 ? '#21c25e' : (v < t2 ? '#f08c1d' : '#ef4444');
    const stamp = txt + '|' + color;
    if (el.dataset.stamp === stamp) return;
    el.dataset.stamp = stamp;
    el.textContent = txt;
    el.style.color = color;
}

// Coverage sub-line under each Control Accuracy row.
function accCovLine(elId, txt) {
    const el = document.getElementById(elId);
    if (!el) return;
    if (el.dataset.stamp === txt) return;
    el.dataset.stamp = txt;
    el.textContent = txt;
}

function renderCVTuningLog(data) {
    // CV live accuracy mirror: data.live = [Tracking % (in-band of challenged time),
    // worst over-voltage (mV 12V-equiv), 0, 0]. The always-on panel is fed off CSV2.
    const live = data.live || [];
    {
        const el0 = document.getElementById('cvLiveScore0');
        if (el0) el0.textContent = 'Tracking: ' + (live[0] > 0 ? live[0].toFixed(1) + ' %' : '—');
        const el1 = document.getElementById('cvLiveScore1');
        if (el1) el1.textContent = 'Peak: ' + (live[1] > 0 ? Math.round(live[1]) + ' mV' : '—');
    }

    const testRow = document.getElementById('cvTestScoreRow');
    if (testRow) {
        if (data.ta) {
            testRow.style.display = '';
            const tsel = document.getElementById('cvCurrentTestScore');
            const ttgl = document.getElementById('cvTestCycleCount');
            if (tsel) tsel.textContent = data.ts > 0 ? data.ts.toFixed(2) : '—';
            if (ttgl) ttgl.textContent = data.tc;
            // Push cycle count into the floating test panel (phase slot is used for Δ voltage)
            if (_testPanelCurrentTest === 'cv') {
                updateTestPanelScore(undefined, (data.tc || 0) + ' cycles', undefined);
            }
        } else {
            testRow.style.display = 'none';
        }
    }

    // Commit section: show when Waveform Generator is active, enable button when ≥1 scored HIGH cycle
    const cvCommitSection = document.getElementById('cvTuningCommitSection');
    if (cvCommitSection) {
        cvCommitSection.style.display = data.ta ? '' : 'none';
        if (data.ta) {
            const countEl = document.getElementById('cvScoredHighCount');
            const btnEl   = document.getElementById('commitCVTuningBtn');
            if (countEl) countEl.textContent = data.tc || 0;
            if (btnEl)   btnEl.disabled = !((data.tc || 0) >= 1);
        }
    }

    // Current settings for row highlighting — read from echo spans
    const curVkp = parseFloat(document.getElementById('VoltageKp_echo')?.textContent);
    const curVki = parseFloat(document.getElementById('VoltageKi_echo')?.textContent);
    // curVkd removed — D term removed
    const curWa  = parseFloat(document.getElementById('cvWaveAmplitudeV_echo')?.textContent);
    const curWp  = parseInt(document.getElementById('cvWavePeriodSec_echo')?.textContent);
    const curCr  = parseInt(document.getElementById('cvConsecutiveReads_echo')?.textContent);

    const records = (data.rec || []).slice();
    const tbody = document.getElementById('cvTuningLogBody');
    if (!tbody) return;

    tbody.innerHTML = records.map(r => {
        const scoreColor = r.s < 10 ? '#22c55e' : r.s < 20 ? '#eab308' : '#ef4444';   // CV loop: good < 10
        const isMatch = !isNaN(curVkp) &&
            Math.abs(r.vkp - curVkp) < 0.001 &&
            Math.abs(r.vki - curVki) < 0.001 &&
            Math.abs(r.wa  - curWa)  < 0.005 &&
            r.wp === curWp && r.cr === curCr;
        const rowStyle = isMatch ? 'background:rgba(99,102,241,0.18);' : '';

        const lowScoreColor = (r.ls || 0) < 10 ? '#22c55e' : (r.ls || 0) < 20 ? '#eab308' : '#ef4444';   // CV loop: good < 10
        return `<tr style="${rowStyle}">
            <td style="padding:2px 4px;">${r.n}</td>
            <td style="padding:2px 4px;color:${scoreColor};font-weight:bold;">${r.s.toFixed(2)}</td>
            <td style="padding:2px 4px;">${r.st.toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.wo.toFixed(3)}</td>
            <td style="padding:2px 4px;">${r.io.toFixed(4)}</td>
            <td style="padding:2px 4px;color:${lowScoreColor};font-weight:bold;">${(r.ls || 0).toFixed(2)}</td>
            <td style="padding:2px 4px;">${(r.lst || 0).toFixed(1)}</td>
            <td style="padding:2px 4px;">${(r.lwo || 0).toFixed(3)}</td>
            <td style="padding:2px 4px;">${(r.lio || 0).toFixed(4)}</td>
            <td style="padding:2px 4px;">${(r.lus || 0).toFixed(3)}</td>
            <td style="padding:2px 4px;">${r.vkp.toFixed(3)}</td>
            <td style="padding:2px 4px;">${r.vki.toFixed(3)}</td>
            <td style="padding:2px 4px;">${r.srr.toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.sfr.toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.abl.toFixed(2)}</td>
            <td style="padding:2px 4px;">${r.arl.toFixed(3)}</td>
            <td style="padding:2px 4px;">${r.asp}</td>
            <td style="padding:2px 4px;">${r.irf.toFixed(2)}</td>
            <td style="padding:2px 4px;">${r.ks.toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.kh.toFixed(1)}</td>
            <td style="padding:2px 4px;">${(r.iefr * 100).toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.ietau.toFixed(0)}</td>
            <td style="padding:2px 4px;">${r.iekb.toFixed(2)}</td>
            <td style="padding:2px 4px;">${r.lddt.toFixed(0)}</td>
            <td style="padding:2px 4px;">${r.ldt1.toFixed(0)}</td>
            <td style="padding:2px 4px;">${r.ldt3.toFixed(0)}</td>
            <td style="padding:2px 4px;">${r.wa.toFixed(2)}</td>
            <td style="padding:2px 4px;">${r.wp}</td>
            <td style="padding:2px 4px;">${r.ko.toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.cr}</td>
            <td style="padding:2px 4px;">${r.fov}</td>
            <td style="padding:2px 4px;">${r.iex}</td>
            <td style="padding:2px 4px;">${r.ld}</td>
            <td style="padding:2px 4px;">${r.hoc}</td>
            <td style="padding:2px 4px;">${r.rpm.toFixed(0)}</td>
            <td style="padding:2px 4px;">${r.tmp.toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.bv.toFixed(2)}</td>
            <td style="padding:2px 4px;">${r.soc.toFixed(1)}</td>
            <td style="padding:2px 4px;">${r.cvt.toFixed(2)}</td>
            <td style="padding:2px 4px;">${stageLabel(r.cs)}</td>
            <td style="padding:2px 4px;white-space:nowrap;">${fmtTuningTs(r.ts)}</td>
            <td style="padding:2px 4px;">${(r.p2p == null || r.p2p < 0) ? 'n/a' : r.p2p.toFixed(3)}</td>
            <td style="padding:2px 4px;">${(r.note || '').replace(/&/g, '&amp;')}</td>
        </tr>`;
    }).join('');
}

// Non-blocking warning when the CV wave period is set below the point where the high phase can
// still fit the steady-state peak-to-peak window (settle + 1s skip + 3s eval ≈ a 14s period).
// The value is always sent (returns true); the warning just tells the user P2P may read n/a.
function warnCvPeriod(form) {
    const v = parseInt(form.cvWavePeriodSec?.value, 10);
    if (v >= 8 && v < 14) {
        xAlert('At a ' + v + 's period the high phase may be too short to fit settling plus the 4s steady-state window — the Peak-to-Peak (P2P) column can read n/a. Settling, overshoot and score still work.', 'Short wave period');
    }
    return true;
}

async function resetCVTuningLog() {
    if (!await xConfirm('Reset all CV tuning records?')) return;
    fetch(buildURL('/resetcvtuninglog'), { method: 'POST' })
        .then(() => fetchCVTuningLog())
        .catch(() => {});
}

