async function factoryReset() {
    if (!settingsUnlocked) {
        xAlert("You must be logged in to perform a factory reset.");
        return;
    }
    const confirmation = await xConfirm(
        "FACTORY RESET WARNING\n\n" +
        "This will restore settings to factory defaults.\n" +
        "Device will restart.\n" +
        "All your settings will be lost.\n\n" +
        "Are you sure you want to continue?"
    );
    if (!confirmation) return;

    const button = document.getElementById('factory-reset-btn');
    button.disabled = true;
    button.textContent = 'Resetting...';
    button.style.backgroundColor = '#6c757d';

    const formData = new FormData();

    fetchWithTimeout(buildURL("/factoryReset"), {
        method: "POST",
        body: formData
    }, 10000)
        .then(response => {
            if (!response.ok) {
                throw new Error(`Server returned ${response.status}: ${response.statusText}`);
            }
            return response.text();
        })
        .then(text => {
            if (text.trim() === "OK") {
                xAlert("Factory reset complete!\n\nThe device will restart.\nPage will reload in 5 seconds.");
                setTrackedTimeout(() => {
                    window.location.reload();
                }, 5000);
            } else {
                throw new Error("Unexpected response: " + text);
            }
        })
        .catch(err => {
            diagError("Factory reset error:", err);

            // Timeout or network error means the device is resetting (expected behavior).
            // TypeError covers every engine's network-failure message: Chrome 'Failed to
            // fetch', WebKit/iOS 'Load failed', Firefox 'NetworkError...'.
            if (err.message === 'Request timeout' || err instanceof TypeError) {
                xAlert("Factory reset complete!\n\nThe device is restarting.\n\nPage will reload in some seconds.");
                setTrackedTimeout(() => {
                    window.location.reload();
                }, 8000);
            } else {
                xAlert("Error during factory reset:\n\n" + err.message);
                button.disabled = false;
                button.textContent = 'Restore Defaults';
                button.style.backgroundColor = '#555555';
            }
        });
}

// Drives every .conn-dot instance (one leads the collapsed strip, one sits by the
// wordmark) — replaced the old WIFI CONNECTED/DISCONNECTED corner pill. While the user
// has chosen offline mode the dot stays orange, so the staleness watchdog's repeating
// updateInlineStatus(false) must not repaint it red.
function updateInlineStatus(isConnected) {
    document.querySelectorAll('.conn-dot').forEach(d => {
        d.classList.toggle('conn-dot--offline', !isConnected && isOfflineMode);
        d.classList.toggle('conn-dot--down', !isConnected && !isOfflineMode);
    });
    if (!isConnected) {
        // Kill the "WiFi off in M:SS" countdown — once the radio drops, no more updates
        // arrive to tick it to zero, so it would otherwise freeze on screen as a stale artifact
        const wifiWakeStatus = document.getElementById('wifi-wake-status');
        if (wifiWakeStatus) wifiWakeStatus.style.display = 'none';
    }
}


// ── Live-feed stall notice ───────────────────────────────────────────────────────────────────────
// The page had exactly one threshold: nine seconds of silence, then the connection dot turns red and
// every reading greys out. Below nine seconds nothing moved and nothing said why, which reads as the
// regulator having stopped rather than the connection to it having dropped — and a stall of a few
// seconds is the common case. This is the earlier, softer tier, and it is strictly live-display: it
// says what is happening now and leaves as soon as it is over. The permanent record of an outage is
// the console (the backfill marker) and the regulator's own log — not this.
const STALL_NOTICE_MS = 3500;   // silence before the overlay appears
const STALL_GREY_MS = 9000;     // unchanged tier: dot red + markAllReadingsStale()
const STALL_CLEAR_MS = 4000;    // how long "flowing again" lingers — same dwell as fileToast
let stallState = { on: false, startMs: 0, hideTimer: null };

// Fixed overlay, built on demand, exactly like fileToast — nothing here may take layout space or the
// page would jump every time the link hiccups. No dismiss control on purpose: it is not interactive
// (pointer-events:none), it leaves on its own, and a tap target that moves under your finger during
// commissioning is worse than the notice itself.
function stallNoticeText(html) {
    let t = document.getElementById('stall-toast');
    if (!t) { t = document.createElement('div'); t.id = 'stall-toast'; document.body.appendChild(t); }
    t.innerHTML = html;
    t.classList.add('show');
}

function hideStallNotice() {
    const t = document.getElementById('stall-toast');
    if (t) t.classList.remove('show');
    if (stallState.hideTimer) { clearTrackedTimeout(stallState.hideTimer); stallState.hideTimer = null; }
}

// gapMs is the age of the last packet received, so the number is the true age of what is on screen —
// not the time since this overlay appeared.
function renderStallNotice(gapMs) {
    let t = 'No data from the regulator for <b>' + Math.round(gapMs / 1000) + ' s</b>. '
        + 'It keeps running on its own &mdash; this is the connection, not the regulator.';
    if (gapMs > STALL_GREY_MS) t += ' Readings are greyed out because they are that old.';
    stallNoticeText(t);
}

// First packet back. startMs is the last packet BEFORE the outage and handleCSVData has already moved
// lastEventTime to now, so this reports the real length of the gap, then gets out of the way.
function endStallNotice() {
    if (!stallState.on) return;
    stallState.on = false;
    stallNoticeText('Data flowing again after a <b>' + Math.round((Date.now() - stallState.startMs) / 1000) + ' s</b> gap.');
    if (stallState.hideTimer) clearTrackedTimeout(stallState.hideTimer);
    stallState.hideTimer = setTrackedTimeout(hideStallNotice, STALL_CLEAR_MS);
}

function resetParameter(parameterName) {
    if (!settingsUnlocked) {
        xAlert("Please unlock settings first");
        return;
    }


    const hiddenInput = document.getElementById(parameterName);
    const button = document.getElementById(parameterName + '_button');

    if (!hiddenInput || !button) {
        diagError(`Reset elements not found for parameter: ${parameterName}`);
        return;
    }

    hiddenInput.value = '1';
    button.closest('form').submit();
    submitMessage();
}

// Force the charge stage machine back to Bulk (CC) and re-run the whole bulk→absorption→float cycle.
// Firmware only honors it while an auto charge stage owns the field (the button is disabled otherwise
// in the CSV2 handler); a full pack climbs back to target and the tail logic returns it to float/idle
// within seconds. Does NOT fix a stuck-forever absorption caused by a broken tail exit (steady load /
// no shunt) — call that out in the warning so the button isn't mistaken for that fix.
async function restartChargeCycle() {
    if (!settingsUnlocked) {
        xAlert("Please unlock settings first");
        return;
    }
    if (!await xConfirm(
        "Restart the charge cycle?\n\n" +
        "The regulator drops back to the bulk (CC) phase and runs a fresh bulk → absorption → float " +
        "cycle. The battery is driven back up to the bulk/absorption target and held there for another " +
        "full absorption period.\n\n" +
        "If the pack is already full it passes through in seconds. If absorption was stuck because the " +
        "tail current never tapered (a steady house load, or no battery shunt), this will NOT fix it — " +
        "it will re-enter absorption. In that case adjust Tail Current or the Absorption Timeout instead."
    )) return;
    submitSimpleParam('RestartChargeCycle', 1);
}

let consolePaused = false;

// ── Console buffer (persistent, coalesced) ───────────────────────────────────
// Every line is kept in a 1000-entry ring
// (window.consoleLog) so Download Logs and the remote log relay can export the
// whole session. Consecutive identical messages coalesce into one line with a
// (xN) count instead of flooding the log (e.g. repeated integrator resets).
// Persisted to localStorage (throttled) so a page refresh or a backgrounded
// Capacitor app keeps the history. Each entry stores an epoch so the live view
// shows time-only while the export shows date + time.
const CONSOLE_MAX_LINES = 1000;
const CONSOLE_LS_KEY = 'xreg_console_v1';
window.consoleLog = window.consoleLog || [];   // [{ t: epochMs, msg, count }]
let consoleLsDirty = false;

function loadConsoleLog() {
    try {
        const raw = localStorage.getItem(CONSOLE_LS_KEY);
        if (!raw) return;
        const arr = JSON.parse(raw);
        if (Array.isArray(arr)) window.consoleLog = arr.slice(-CONSOLE_MAX_LINES);
    } catch (e) { /* corrupt/absent — start empty */ }
}

function saveConsoleLogNow() {
    try { localStorage.setItem(CONSOLE_LS_KEY, JSON.stringify(window.consoleLog)); } catch (e) { }
    consoleLsDirty = false;
}

// Render one buffer entry to a string. withDate = full date+time (export); else time-only (live view).
function formatConsoleEntry(e, withDate) {
    const d = new Date(e.t);
    const stamp = withDate ? d.toLocaleString() : d.toLocaleTimeString();
    const suffix = (e.count > 1) ? ` (x${e.count})` : '';
    return `[${stamp}] ${e.msg}${suffix}`;
}

// Append one raw firmware message (no timestamp). updateDisplay=false while paused —
// the line is still buffered so the export stays complete; the screen catches up on resume.
function appendConsoleLine(msg, updateDisplay) {
    const buf = window.consoleLog;
    const last = buf[buf.length - 1];
    const coalesced = (last && last.msg === msg);

    if (coalesced) {
        last.count++;
        last.t = Date.now();
    } else {
        buf.push({ t: Date.now(), msg: msg, count: 1 });
        while (buf.length > CONSOLE_MAX_LINES) buf.shift();
    }
    consoleLsDirty = true;

    if (!updateDisplay) return;
    const consoleDiv = document.getElementById("consoleOutput");
    if (!consoleDiv) return;
    const cur = buf[buf.length - 1];
    if (coalesced && consoleDiv.lastElementChild) {
        consoleDiv.lastElementChild.textContent = formatConsoleEntry(cur, false);
    } else {
        const line = document.createElement("div");
        line.textContent = formatConsoleEntry(cur, false);
        consoleDiv.appendChild(line);
        while (consoleDiv.children.length > CONSOLE_MAX_LINES) {
            consoleDiv.removeChild(consoleDiv.firstChild);
        }
    }
    // Defer scroll to avoid forced synchronous reflow on every message
    requestAnimationFrame(() => { consoleDiv.scrollTop = consoleDiv.scrollHeight; });
}

// Full session as text — used by Download Logs and the remote relay (date + time + counts).
function getConsoleText() {
    return window.consoleLog.map(e => formatConsoleEntry(e, true)).join('\n');
}

// Repaint the on-screen console from the buffer (after a localStorage restore or un-pause).
function renderConsoleFromBuffer() {
    const consoleDiv = document.getElementById("consoleOutput");
    if (!consoleDiv) return;
    consoleDiv.innerHTML = "";
    for (const e of window.consoleLog) {
        const line = document.createElement("div");
        line.textContent = formatConsoleEntry(e, false);
        consoleDiv.appendChild(line);
    }
    requestAnimationFrame(() => { consoleDiv.scrollTop = consoleDiv.scrollHeight; });
}

// The regulator keeps its own 200-line console ring (/consolehist.txt) with device timestamps, and it
// keeps writing to it while this browser's event stream is down — the stream itself discards anything
// it cannot deliver the moment it has no listener. So after a reconnect, splice what the regulator said
// during the gap back into the on-screen log instead of leaving a silent hole in it. Bounded by the
// ring: an outage longer than 200 messages recovers only the tail.
// Returns the number of lines spliced back in, or -1 if the regulator could not be asked.
async function consoleBackfillFromDevice(gapStartMs, gapEndMs) {
    if (DEMO_MODE) return -1;
    let raw;
    try {
        const r = await fetchWithTimeout(buildURL('/consolehist.txt'), {}, 8000);
        if (!r.ok) return -1;
        raw = await r.text();
    } catch (e) { return -1; }
    const from = gapStartMs - 1500;   // a second of overlap either side: both paths can carry the boundary line
    const recovered = [];
    for (const line of raw.split('\n')) {
        const i1 = line.indexOf('\t'), i2 = line.indexOf('\t', i1 + 1);
        if (i1 < 0 || i2 < 0) continue;
        const epoch = parseInt(line.slice(0, i1), 10);
        if (!(epoch > 1577836800)) continue;   // device clock never synced — the line cannot be placed in time
        const t = epoch * 1000;
        if (t < from || t > gapEndMs) continue;
        recovered.push({ t: t, msg: line.slice(i2 + 1), count: 1 });
    }
    // Same text within 2 s of a line already held = the boundary duplicate, not a repeat. Text alone is
    // not enough: these messages legitimately repeat many times a minute.
    const tail = window.consoleLog.slice(-60);
    const add = recovered.filter(e => !tail.some(h => h.msg === e.msg && Math.abs(h.t - e.t) < 2000));
    const secs = Math.round((gapEndMs - gapStartMs) / 1000);
    window.consoleLog.push({ t: gapStartMs, msg: `--- stream down ${secs}s, ${add.length} line(s) recovered from the regulator ---`, count: 1 });
    for (const e of add) window.consoleLog.push(e);
    window.consoleLog.sort((a, b) => a.t - b.t);
    while (window.consoleLog.length > CONSOLE_MAX_LINES) window.consoleLog.shift();
    consoleLsDirty = true;
    if (!consolePaused) renderConsoleFromBuffer();
    return add.length;
}

// Throttled persistence: flush at most every 3s, plus on tab hide / unload.
loadConsoleLog();
// Device reports "<random NVS install ID>|<firmware version>". Either part changing
// (NVS erase / factory reset, or a reflash) means old history is stale — drop it.
// Called from the SSE open handler, NOT at script parse: in Capacitor the base URL isn't
// resolved until discovery finishes, so a parse-time fetch silently never reached the device.
// SSE open is also the moment new console lines start arriving, and re-running per reconnect
// catches a mid-session reflash.
function checkInstallIdFreshness() {
    fetch(buildURL('/installid')).then(r => r.text()).then(id => {
        id = (id || '').trim();
        if (!id) return;
        const prev = localStorage.getItem('xreg_install_id');
        if (prev && prev !== id) clearConsole();
        localStorage.setItem('xreg_install_id', id);
    }).catch(() => { });
}
setInterval(() => { if (consoleLsDirty) saveConsoleLogNow(); }, 3000);
document.addEventListener('visibilitychange', () => { if (document.hidden && consoleLsDirty) saveConsoleLogNow(); });
window.addEventListener('pagehide', () => { if (consoleLsDirty) saveConsoleLogNow(); });
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', renderConsoleFromBuffer);
} else {
    renderConsoleFromBuffer();
}

function copyConsole() {
    const consoleDiv = document.getElementById("consoleOutput");
    if (!consoleDiv) {
        return;
    }

    const text = Array.from(consoleDiv.children)
        .map(div => div.textContent)
        .join('\n');

    if (!text) {
        return;
    }

    // Try modern clipboard API first
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => {
        }).catch(err => {
            console.error('Clipboard error:', err);
            fallbackCopy(text);
        });
    } else {
        // Fallback for older browsers or non-HTTPS
        fallbackCopy(text);
    }
}

function fallbackCopy(text) {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    document.body.appendChild(textarea);
    textarea.select();
    try {
        document.execCommand('copy');
    } catch (err) {
    }
    document.body.removeChild(textarea);
}


function clearConsole() {
    window.consoleLog = [];
    consoleLsDirty = false;
    try { localStorage.removeItem(CONSOLE_LS_KEY); } catch (e) { }
    const el = document.getElementById("consoleOutput");
    if (el) el.innerHTML = "";
}

function toggleConsolePause() {
    consolePaused = !consolePaused;
    const btn = document.getElementById("pauseConsoleBtn");
    if (btn) {
        btn.textContent = consolePaused ? "Resume" : "Pause";
        btn.style.backgroundColor = consolePaused ? "#ff6b6b" : "";
    }
    if (!consolePaused) renderConsoleFromBuffer();  // catch the display up with anything buffered while paused
}

function updateAlarmStatus(data) {
    const alarmLed = document.getElementById('alarm-led');
    const alarmText = document.getElementById('alarm-status-text');

    if (!alarmLed || !alarmText) return;

    const isAlarming = data.Alarm_Status === 1;

    if (isAlarming) {
        alarmLed.style.backgroundColor = '#ff0000';
        alarmLed.style.boxShadow = '0 0 15px rgba(255, 0, 0, 0.8)';
        alarmText.textContent = 'Alarming!';
        alarmText.style.color = '#ff0000';
    } else {
        alarmLed.style.backgroundColor = '#00a19a';
        alarmLed.style.boxShadow = '0 0 10px rgba(0, 161, 154, 0.5)';
        alarmText.textContent = 'Silent';
        alarmText.style.color = '#00a19a';
    }
}

//Graying when wifi disconnects
function markAllReadingsStale() {
    document.querySelectorAll('.reading span, .reading-value').forEach(element => {
        element.style.opacity = "0.4";
        element.style.color = "#999999";
        element.style.fontStyle = "italic";
    });
}

function initPlotDataStructures() {
    const intervalMs = window._lastKnownInterval || 200;
    liveWindowSec = window._lastKnownTimeWindow || 8; // visible span (SECONDS)
    const timeWindowMs = LIVE_BUFFER_SEC * 1000; // buffer always 5 min
    const maxPoints = Math.ceil(timeWindowMs / intervalMs);
    const intervalSec = intervalMs / 1000;
    if (useTimestamps) {
        // TIMESTAMP MODE
        const now = Math.floor(Date.now() / 1000);
        xAxisData = [];
        for (let i = 0; i < maxPoints; i++) {
            xAxisData[i] = now - (maxPoints - 1 - i) * intervalSec;
        }
    } else {
        // RELATIVE TIME MODE
        xAxisData = [];
        for (let i = 0; i < maxPoints; i++) {
            xAxisData[i] = -(maxPoints - 1 - i) * intervalSec;
        }
    }

    // null, not 0: the buffer spans 5 min but starts empty, and a zero prefill renders as a
    // flat 0 A / 0 V trace the device never reported. uPlot draws nothing for null.
    currentTempData = [
        [...xAxisData],
        new Array(maxPoints).fill(null),
        new Array(maxPoints).fill(null),
        new Array(maxPoints).fill(null),
        new Array(maxPoints).fill(null),  // Field% (duty cycle)
        new Array(maxPoints).fill(null)   // Alt current filtered (off by default)
    ];

    voltageData = [
        [...xAxisData],
        new Array(maxPoints).fill(null),
        new Array(maxPoints).fill(null),
        new Array(maxPoints).fill(null)  // Field% (duty cycle)
    ];

    rpmData = [
        [...xAxisData],
        new Array(maxPoints).fill(null),
        new Array(maxPoints).fill(null)  // Field% (duty cycle)
    ];

    temperatureData = [
        [...xAxisData],
        new Array(maxPoints).fill(null),
        new Array(maxPoints).fill(null)  // Field% (duty cycle)
    ];

    // Marker arrays are index-aligned to these buffers — wipe them together, or stale gap /
    // protection bands paint at meaningless positions after a time-axis-mode toggle.
    protEventData = new Array(maxPoints).fill(0);
    gapMarkData = new Array(maxPoints).fill(0);
}

// Splits factory for scales whose range can be user-pinned (manual). Auto mode
// reproduces uPlot's default numeric splits exactly (multiples of the increment
// it chose for the space), so autoscale look and perf are unchanged. Manual mode
// keeps those nice interior ticks but labels the EXACT min/max at the plot
// corners, dropping any interior tick that would crowd an endpoint label — the
// printed corner values are always the user's pinned bounds, i.e. exactly what
// the click-to-edit boxes (attachYAxisEdit) read and write.
function edgeLabeledSplits(isManual) {
    return (u, axisIdx, mn, mx, incr) => {
        const ticks = [];
        for (let i = Math.ceil(mn / incr - 1e-9); i * incr <= mx + incr * 1e-9; i++)
            ticks.push(+(i * incr).toFixed(12));
        if (!isManual || !isManual()) return ticks;
        const guard = incr * 0.5;   // half a tick step keeps endpoint labels readable
        return [mn, ...ticks.filter(v => v - mn >= guard && mx - v >= guard), mx];
    };
}

// =====================================================================
// On-plot Y-axis editing — makes each Y axis's extreme tick labels
// directly editable. uPlot draws tick labels on canvas, so they can't
// take click handlers themselves; instead an invisible click zone sits
// over each axis's min and max label. Clicking it summons an edit box
// in place, prefilled with the current bound. Enter (or tap away)
// applies, Escape cancels, and where the chart supports automatic
// ranging, clearing the value and pressing Enter returns it to auto.
// cfgs: [{ scale, apply(min,max), auto() optional, decimals optional }]
function attachYAxisEdit(u, cfgs) {
    if (!u || !u.over) return;
    const wrap = u.over.parentElement;   // .u-wrap — contains plot area AND axis strips
    if (!wrap) return;
    wrap.querySelectorAll('.yaxis-hot, .yaxis-edit').forEach(n => n.remove());

    const fmt = (v, cfg) => {
        if (v == null || !isFinite(v)) return '';
        let d = cfg.decimals;
        if (d === undefined) {
            const sc = u.scales[cfg.scale];
            const span = (sc && isFinite(sc.max - sc.min)) ? Math.abs(sc.max - sc.min) : 0;
            d = span >= 100 ? 0 : span >= 10 ? 1 : 2;
        }
        return String(parseFloat(v.toFixed(d)));
    };

    // Touch: taller tap targets and a wider edit box (the box also gets a
    // 16px font from CSS — anything smaller makes iOS auto-zoom the page)
    const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
    const HOT_H = coarse ? 28 : 18, HOT_W = 46, INP_W = coarse ? 76 : 58;
    const zones = [];

    // One shared edit box, summoned to whichever label was clicked
    const inp = document.createElement('input');
    inp.type = 'number';
    inp.step = 'any';
    inp.className = 'yaxis-edit';
    ['mousedown', 'mouseup', 'touchstart', 'click', 'dblclick'].forEach(ev =>
        inp.addEventListener(ev, e => e.stopPropagation()));
    wrap.appendChild(inp);
    let editing = null;   // active zone, null while the box is hidden

    const hideInput = () => { editing = null; inp.style.display = 'none'; };

    const commit = () => {
        if (!editing) return;
        const z = editing;
        const sc = u.scales[z.cfg.scale];
        const raw = inp.value.trim();
        if (raw === '' && z.cfg.auto) { z.cfg.auto(); hideInput(); return; }
        const v = parseFloat(raw);
        if (isFinite(v) && sc) {
            const mn = z.isMax ? sc.min : v;
            const mx = z.isMax ? v : sc.max;
            if (mx > mn) z.cfg.apply(mn, mx);
        }
        hideInput();
    };

    inp.addEventListener('keydown', e => {
        e.stopPropagation();
        if (e.key === 'Enter') { e.preventDefault(); commit(); }
        else if (e.key === 'Escape') hideInput();
    });
    inp.addEventListener('blur', () => commit());

    cfgs.forEach(cfg => {
        const axis = u.axes.find(a => a.scale === cfg.scale);
        if (!axis) return;
        const onRight = axis.side === 1;

        [true, false].forEach(isMax => {
            const hot = document.createElement('div');
            hot.className = 'yaxis-hot';
            hot.title = 'Click to edit axis ' + (isMax ? 'maximum' : 'minimum')
                + (cfg.auto ? ' — clear + Enter for auto' : '');
            // Keep clicks/drags away from uPlot's cursor + zoom handling
            ['mousedown', 'touchstart', 'dblclick', 'click'].forEach(ev =>
                hot.addEventListener(ev, e => e.stopPropagation()));
            const zone = { cfg, isMax, onRight, hot };
            // Open on mouseup, NOT click: uPlot installs a capture-phase click
            // listener on .u-wrap (its drag-end click suppressor) whose moved-cursor
            // check is always true over the axis strip, so it swallows every click
            // before it can reach this element — a click handler here never fires.
            // The armed flag ignores mouseups from drags that started elsewhere
            // (e.g. releasing a plot-area zoom drag on top of an axis label).
            let armed = false;
            hot.addEventListener('mousedown', () => { armed = true; });
            hot.addEventListener('mouseleave', () => { armed = false; });
            hot.addEventListener('mouseup', e => {
                e.stopPropagation();
                if (!armed) return;
                armed = false;
                const sc = u.scales[cfg.scale];
                if (!sc) return;
                editing = zone;
                inp.value = fmt(isMax ? sc.max : sc.min, cfg);
                const w = Math.max(INP_W, hot.offsetWidth);
                inp.style.width = w + 'px';
                inp.style.left = (onRight ? hot.offsetLeft : (hot.offsetLeft + hot.offsetWidth - w)) + 'px';
                inp.style.top = hot.offsetTop + 'px';
                inp.style.display = 'block';
                inp.focus();
                inp.select();
            });
            wrap.appendChild(hot);
            zones.push(zone);
        });
    });

    // Place the zones over the extreme tick labels: vertically centered on the
    // plot area's top/bottom edge (where uPlot centers those labels), anchored
    // to the plot-edge side of the axis strip so a rotated axis title at the
    // strip's far edge stays unclickable. Re-run every draw — offsets move on
    // resize and axis-width changes.
    const position = () => {
        const oL = u.over.offsetLeft, oT = u.over.offsetTop,
            oW = u.over.offsetWidth, oH = u.over.offsetHeight;
        zones.forEach(z => {
            const strip = z.onRight ? (wrap.clientWidth - oL - oW) : oL;
            const w = Math.min(HOT_W, Math.max(30, strip - 2));
            z.hot.style.width = w + 'px';
            z.hot.style.height = HOT_H + 'px';
            z.hot.style.left = (z.onRight ? (oL + oW + 1) : (oL - w - 1)) + 'px';
            z.hot.style.top = Math.max(0, (z.isMax ? oT : oT + oH) - HOT_H / 2) + 'px';
        });
    };

    (u.hooks.draw = u.hooks.draw || []).push(position);
    position();
}

// Persist a Y-axis range to the regulator (same params the settings forms use).
// Settings writes are arm-gated — while the dashboard is locked the new range
// still applies, it just stays local to this browser session.
function sendYAxisSetting(params) {
    if (!settingsUnlocked) return;
    const q = new URLSearchParams(params);
    fetchWithTimeout(buildURL('/get?' + q.toString()), {}, 5000).catch(() => { });
}

function initCurrentTempPlot() {
    const plotEl = document.getElementById('current-temp-plot');
    if (!plotEl) {
        diagError("Current & Temperature plot element not found");
        return;
    }

    const opts = {
        width: plotFitWidth(plotEl, 600, 800),  // fallback 600 (viewport-clamped): never born 0-wide if built hidden
        height: 300,
        title: "Current History",
        series: [
            { label: null, points: { show: false }, stroke: "transparent", width: 0 },
            {
                label: "Battery Current (A)",
                stroke: "#4CAF50",
                width: 2,
                scale: "current"
            },
            {
                label: "Alternator Current (A)",
                stroke: "#2196F3",
                width: 2,
                scale: "current"
            },
            {
                label: "Field Current (A)",
                stroke: "#9C27B0",
                width: 2,
                scale: "current"
            },
            {
                label: "Field %",
                stroke: "#9E9E9E",
                width: 2,
                scale: "pct",
                dash: [4, 2]
            },
            {
                // The exact process variable the CC current PID acts on in AdjustFieldLearnMode — the
                // OutputPIDSigSrc-selected signal (default EMA at OutputPIDFilterTC, or MA(N), or raw).
                // Off by default — toggle via legend. Dashed because at the ~34 ms default TC it sits
                // almost exactly on the raw blue trace at this plot's sample rate; the dash is what
                // makes it visible when overlapping. Diverges from raw during fast ripple/resonance.
                label: "Alt Current filtered (A)",
                stroke: "#009688",
                width: 1,
                dash: [6, 3],
                scale: "current",
                show: false
            }
        ],
        scales: useTimestamps ? {
            x: { time: true, range: (u, dMin, dMax) => [dMax - liveWindowSec, dMax] },
            current: { auto: false, range: () => [Ymin1, Ymax1] },   // fn, not array: re-read each redraw so Y edits survive setData re-ranging
            pct: { auto: false, range: () => [pctMin1, pctMax1] }     // fn so click-to-edit Field % range survives redraws
        } : {
            x: { time: false, range: (u, dMin, dMax) => [-liveWindowSec, 0] },
            current: { auto: false, range: () => [Ymin1, Ymax1] },   // fn, not array: re-read each redraw so Y edits survive setData re-ranging
            pct: { auto: false, range: () => [pctMin1, pctMax1] }     // fn so click-to-edit Field % range survives redraws
        },
        axes: useTimestamps ? [
            { grid: { show: true } },
            {
                scale: "current",
                label: "Amperes",
                grid: { show: true },
                side: 3,
                splits: edgeLabeledSplits(() => !autoScaleCurrent)
            },
            {
                scale: "pct",
                label: "Field %",
                grid: { show: false },
                side: 1,
                values: (u, ticks) => ticks.map(v => Math.round(v) + '%')
            }
        ] : [
            {
                label: "Seconds Ago",
                grid: { show: true }
            },
            {
                scale: "current",
                label: "Amperes",
                grid: { show: true },
                side: 3,
                splits: edgeLabeledSplits(() => !autoScaleCurrent)
            },
            {
                scale: "pct",
                label: "Field %",
                grid: { show: false },
                side: 1,
                values: (u, ticks) => ticks.map(v => Math.round(v) + '%')
            }
        ],
        legend: {
            show: false
        },
        plugins: [{
            hooks: {
                init: [
                    (u) => {
                        createCustomLegend('current-temp-plot', [
                            { label: "Battery Current (A)", color: "#4CAF50", reqBattCurrent: true },
                            { label: "Alternator Current (A)", color: "#2196F3" },
                            { label: "Field Current (A)", color: "#9C27B0" },
                            { label: "Field %", color: "#9E9E9E" },
                            // off:true → default hidden, matching the series show:false above (filtered = the CC PID's PV)
                            { label: "Alt Current filtered (A)", color: "#009688", off: true }
                        ], u);

                        const resizePlot = debounce(() => {
                            const plotEl = document.getElementById("current-temp-plot");
                            if (plotEl && currentTempPlot) {
                                currentTempPlot.setSize({ width: plotEl.clientWidth, height: 300 });
                            }
                        }, 150);

                        if (currentTempResizeObserver) {
                            currentTempResizeObserver.disconnect();
                        }
                        currentTempResizeObserver = new ResizeObserver(resizePlot);
                        currentTempResizeObserver.observe(plotEl);
                    }
                ],
                draw: [(u) => drawProtectionMarkers(u), (u) => drawGapMarkers(u)]
            }
        }]
    };

    currentTempPlot = new uPlot(opts, currentTempData, plotEl);

    // Autoscale checkbox + lock button — re-injected on each init so re-inits stay clean
    plotEl.style.position = 'relative';
    const existingAs = plotEl.querySelector('.autoscale-ctrl');
    if (existingAs) existingAs.remove();
    autoScaleCurrentLocked = false;
    const asDiv = document.createElement('div');
    asDiv.className = 'autoscale-ctrl';
    asDiv.style.cssText = 'position:absolute;top:6px;right:8px;z-index:10;display:flex;flex-direction:column;align-items:flex-end;gap:2px;font-size:11px;';
    asDiv.innerHTML = '<div style="display:flex;align-items:center;gap:3px;opacity:0.6;"><input type="checkbox" id="autoscale-current-cb" style="cursor:pointer;width:12px;height:12px;margin:0;"><label for="autoscale-current-cb" style="cursor:pointer;user-select:none;">auto</label></div><button id="lock-current-btn" style="display:none;font-size:10px;padding:0 5px;cursor:pointer;border:1px solid #999;border-radius:2px;background:transparent;opacity:0.6;line-height:16px;">lock</button>';
    plotEl.appendChild(asDiv);
    const asCb = document.getElementById('autoscale-current-cb');
    const lockBtnC = document.getElementById('lock-current-btn');
    asCb.checked = autoScaleCurrent;
    if (autoScaleCurrent) lockBtnC.style.display = 'block';
    lockBtnC.addEventListener('click', () => {
        autoScaleCurrentLocked = !autoScaleCurrentLocked;
        lockBtnC.textContent = autoScaleCurrentLocked ? 'unlock' : 'lock';
        lockBtnC.style.opacity = autoScaleCurrentLocked ? '1' : '0.6';
    });
    asCb.addEventListener('change', e => {
        autoScaleCurrent = e.target.checked;
        localStorage.setItem('autoScaleCurrent', autoScaleCurrent);
        lockBtnC.style.display = autoScaleCurrent ? 'block' : 'none';
        if (!autoScaleCurrent) {
            autoScaleCurrentLocked = false;
            lockBtnC.textContent = 'lock';
            lockBtnC.style.opacity = '0.6';
            _autoScaleCurrentLeft = null;
            _autoScaleCurrentRight = null;
            currentTempPlot.setScale('current', { min: Ymin1, max: Ymax1 });
            pctMin1 = 0; pctMax1 = 100;
            currentTempPlot.setScale('pct', { min: 0, max: 100 });
        } else {
            recomputeAutoScales(true);  // fit to the visible window now, don't wait for the next data frame
        }
    });

    // Click-to-edit Y limits, saved to the regulator as Ymin1/Ymax1
    attachYAxisEdit(currentTempPlot, [{
        scale: 'current', decimals: 0,
        apply: (mn, mx) => {
            Ymin1 = Math.round(mn); Ymax1 = Math.round(mx);
            if (asCb.checked) { asCb.checked = false; asCb.dispatchEvent(new Event('change')); }
            else currentTempPlot.setScale('current', { min: Ymin1, max: Ymax1 });
            sendYAxisSetting({ Ymin1: Ymin1, Ymax1: Ymax1 });
        }
    }, {
        // Field % (right axis) — local-only, clear + Enter returns to 0-100
        scale: 'pct', decimals: 0,
        apply: (mn, mx) => { pctMin1 = mn; pctMax1 = mx; currentTempPlot.setScale('pct', { min: mn, max: mx }); },
        auto: () => { pctMin1 = 0; pctMax1 = 100; currentTempPlot.setScale('pct', { min: 0, max: 100 }); }
    }]);
}

