function updateLearningTableHighlight(data) {
    document.querySelectorAll('.learning-table-row-active').forEach(row => {
        row.classList.remove('learning-table-row-active');
    });
    document.querySelectorAll('.history-row-active').forEach(row => {
        row.classList.remove('history-row-active');
    });

    if (_commPrepRpmActive) return;   // wizard deep-link: no live row highlight while editing

    // Highlight 3 rows: lower RPM point, bucket, upper RPM point
    if (data.currentRPMTableIndex >= 0 && data.currentRPMTableIndex <= 9) {
        const allRows = document.querySelectorAll('#learning-table-body tr');
        const bucketIndex = data.currentRPMTableIndex;

        // Calculate row indices (accounting for history rows between data rows)
        const lowerDataRowIndex = bucketIndex * 2;
        const historyRowIndex = bucketIndex * 2 + 1;
        const upperDataRowIndex = (bucketIndex + 1) * 2;

        if (allRows[lowerDataRowIndex]) {
            allRows[lowerDataRowIndex].classList.add('learning-table-row-active');
        }
        if (allRows[historyRowIndex]) {
            allRows[historyRowIndex].classList.add('history-row-active');
        }
        if (allRows[upperDataRowIndex]) {
            allRows[upperDataRowIndex].classList.add('learning-table-row-active');
        }
    }
}

function updatePidInitializedDisplay(data) {
    const element = document.getElementById('pidInitialized_display');
    if (element && data.pidInitialized !== undefined) {
        element.textContent = data.pidInitialized === 1 ? 'Yes' : 'No';
        element.style.color = data.pidInitialized === 1 ? 'var(--accent)' : '#999';
    }
}

// uPlot sizes itself to clientWidth at construction. All six live charts are built once at load
// (initCurrentTempPlot()... near startInterpLoop()) while their tab is display:none, i.e. at width 0.
// Each has a ResizeObserver that fixes this when the element gains size, but that's debounced, so the
// chart shows squished until the observer fires. Call this the moment a chart's tab/sub-tab becomes
// visible to size it immediately. The clientWidth>0 guard makes it a no-op for any chart whose
// sub-tab is still hidden, so it's safe to call for the whole Plots/Tuning family unconditionally.
// Backstop for live plots built at width 0 while their tab is hidden: if resize-on-show and the
// ResizeObserver both miss, the plot stays 0-wide and uPlot draws a blank box. Called per frame from
// the interp loop only while the owning tab is visible; steady-state cost is one property compare
// (setSize fires only on a real width mismatch).
function healPlotWidth(plot, elId, height) {
    if (!plot) return;
    const el = document.getElementById(elId);
    if (!el) return;
    const w = el.clientWidth;
    if (w > 0 && plot.width !== w) plot.setSize({ width: w, height });
}

// Chart width for every uPlot build/resize: the live container width when visible; when the
// container is hidden (clientWidth 0) fall back to `fallback` CLAMPED TO THE VIEWPORT, so a
// chart built under a hidden tab can never be born wider than a phone screen.
function plotFitWidth(el, fallback, cap) {
    const avail = Math.max(240, document.documentElement.clientWidth - 40);
    const w = (el && el.clientWidth) ? el.clientWidth : Math.min(fallback, avail);
    return cap ? Math.min(w, cap) : w;
}

function resizeLivePlotsOnShow() {
    const fix = (plot, elId, height) => {
        if (!plot) return;
        const el = document.getElementById(elId);
        if (el && el.clientWidth > 0) plot.setSize({ width: el.clientWidth, height });
    };
    fix(currentTempPlot, 'current-temp-plot', 300);
    fix(voltagePlot,     'voltage-plot',      300);
    fix(rpmPlot,         'rpm-plot',          300);
    fix(temperaturePlot, 'temperature-plot',  300);
    fix(pidTuningPlot,   'pid-tuning-plot',   400);
    fix(cvTuningPlot,    'cv-tuning-plot',    350);
    fix(cvPidPlot,       'cv-pid-plot',       300);
}

function showMainTab(tabName) {
    if (tabName === 'cloudfeatures' && !settingsUnlocked) {
        xAlert('Please unlock settings first to access Cloud Features');
        return;
    }

    // Block all tabs except Setup until vessel info complete
    if (tabName !== 'settings' && !vesselInfoComplete) {
        // Only alert if user is actively trying to switch (not on initial load)
        if (document.getElementById(tabName)) {
            xAlert('Please complete Vessel Info in Setup tab first');
        }
        showMainTab('settings');
        showSubTab('settings', 'vessel-info');
        return;
    }

    const tabContents = document.querySelectorAll('.tab-content');
    tabContents.forEach(tab => tab.classList.remove('active'));

    const mainTabs = document.querySelectorAll('.main-tab');
    mainTabs.forEach(tab => tab.classList.remove('active'));

    document.getElementById(tabName).classList.add('active');

    // Charts in this tab were built at width 0 while it was hidden — size them now (no debounce wait).
    if (tabName === 'plots' || tabName === 'tuning') resizeLivePlotsOnShow();

    mainTabs.forEach(tab => {
        if (tab.getAttribute('onclick').includes(tabName)) {
            tab.classList.add('active');
        }
    });

    // Initialize My Profile when Cloud Features tab is opened
    if (tabName === 'cloudfeatures') {
        setTrackedTimeout(() => {
            if (typeof initializeProfileTab === 'function') {
                initializeProfileTab();
            }
        }, 100);
    }

    if (tabName === 'livedata') {
        // Ensure a sub-tab is always visible; on first visit none may be active yet.
        // Same destination as applyLandingTab() so an early manual click isn't yanked
        // to another sub-tab when the landing finally applies.
        if (!document.querySelector('#livedata .sub-tab-content.active')) {
            showSubTab('livedata', 'diag');
        }
    }

    // Control sticky header based on active tab
    const header = document.querySelector('.permanent-header');
    if (header) {
        if (tabName === 'plots') {
            header.classList.remove('permanent-header-sticky');
        } else {
            header.classList.add('permanent-header-sticky');
        }
    }

    // Main-tab clicks that don't re-enter showSubTab (sub-tab already active) would otherwise
    // keep the previous tab's scroll offset; reset to the top.
    window.scrollTo(0, 0);

    // Usage tracking: attribute dwell to the sub-tab that is actually visible (a main-tab
    // switch often reveals a previously-active sub-tab without re-entering showSubTab).
    const usageActiveSub = document.querySelector('#' + tabName + ' .sub-tab-content.active');
    usageSetPage(usageActiveSub ? usageActiveSub.id : tabName);
}


function showRegistrationRequiredModal(featureName) {
    const message = `Please complete Registration first to access ${featureName}.  If you've already registered, try waiting a few seconds for the Registration info to populate before switching subtabs`;
    xAlert(message);
}

function showSubTab(parentTab, subTabName, evt = null) {

    // Block all subtabs except Setup > Vessel Info until vessel info complete
    if (!vesselInfoComplete && !(parentTab === 'settings' && subTabName === 'vessel-info')) {
        xAlert('Please complete Vessel Info in Setup tab first');
        showMainTab('settings');
        showSubTab('settings', 'vessel-info');
        return;
    }

    // Block access to Cloud Features subtabs if not registered.
    // 'mydashboard' (Statistics) lives in Live Data → Statistics; local data, so the gate doesn't apply.
    if (parentTab === 'cloudfeatures' && subTabName !== 'myprofile' && !isDeviceRegistered) {
        const featureNames = {
            'leaderboards': 'Leaderboards',
            'fleetstats': 'Fleet Stats',
            'configsharing': 'Config Sharing',
            'softwareupdate': 'Software Update'
        };
        showRegistrationRequiredModal(featureNames[subTabName] || 'this feature');
        return;
    }

    const subTabContents = document.querySelectorAll(`#${parentTab} .sub-tab-content`);
    subTabContents.forEach(tab => tab.classList.remove('active'));

    const subTabs = document.querySelectorAll(`#${parentTab} .sub-tab`);
    subTabs.forEach(tab => tab.classList.remove('active'));

    const contentEl = document.getElementById(`${parentTab}-${subTabName}`);
    if (contentEl) {
        contentEl.classList.add('active');
    }
    // Reset to the top on every sub-tab switch; otherwise the window keeps the prior scroll
    // offset (a cross-link low on a long page would land you at the destination's bottom).
    window.scrollTo(0, 0);

    // A chart revealed by this sub-tab switch (e.g. Tuning > Current/Voltage) was built at width 0
    // while hidden — size it immediately instead of waiting on its debounced ResizeObserver.
    if (parentTab === 'plots' || parentTab === 'tuning') resizeLivePlotsOnShow();

    // Add active class to clicked sub-tab, or find matching button if called programmatically
    if (evt && evt.target) {
        evt.target.classList.add('active');
    } else {
        subTabs.forEach(tab => {
            const onclick = tab.getAttribute('onclick') || '';
            if (onclick.includes(`showSubTab('${parentTab}', '${subTabName}'`) ||
                onclick.includes(`showSubTab("${parentTab}", "${subTabName}"`)) {
                tab.classList.add('active');
            }
        });
    }


    // Initialize / refresh the barometer panel whenever the Weather/Solar tab is opened (baro lives there now)
    if (parentTab === 'livedata' && subTabName === 'weathersolar') {
        if (typeof window.initBaroPanel === 'function') window.initBaroPanel();
        // Draw the Wind Trend plot now it's visible (it needs a non-zero width to size).
        if (typeof windTrendRender === 'function') setTimeout(() => { try { windTrendRender(); } catch (e) { } }, 60);
    }
    // Solar ledger plots live on the Integrations sub-tab; solarLedgerRender bails while its container is hidden.
    if (parentTab === 'livedata' && subTabName === 'integrations') {
        if (typeof solarLedgerTabOpened === 'function') setTimeout(() => { try { solarLedgerTabOpened(); } catch (e) { } }, 60);
    }

    // Probe registry polls only while its sub-tab is on screen — fetch once on entry.
    if (parentTab === 'settings' && subTabName === 'temperature' && typeof owPollNow === 'function') owPollNow();

    // Resume the Fast Alt-Current scope only if its Waveforms section is expanded and on-screen
    if (parentTab === 'livedata' && subTabName === 'diag') {
        const kickFastDiag = () => {
            if (typeof fastDiagIsVisible === 'function' && fastDiagIsVisible()
                && typeof fastDiagOnOpen === 'function') fastDiagOnOpen();
        };
        if (diagScopeKickDelayMs) { setTrackedTimeout(kickFastDiag, diagScopeKickDelayMs); diagScopeKickDelayMs = 0; }
        else kickFastDiag();
        // Ripple heatmap draws once at load and skips while hidden; its <details> is open by
        // default so ontoggle never fires. Redraw now the Diag tab is actually on-screen.
        if (typeof drawRippleMap === 'function') setTimeout(drawRippleMap, 60);
    }

    if (parentTab === 'cloudfeatures' && subTabName === 'myprofile') {
        if (typeof initializeProfileTab === 'function') {
            initializeProfileTab();
        }
    }

    // Native Long Term Plots — lazy-init on first open of Plots → Long Term sub-tab.
    if (parentTab === 'plots' && subTabName === 'longterm' && typeof initLongTermPlots === 'function') {
        initLongTermPlots();
    }

    // Redirect to Vercel for Fleet Stats
    if (parentTab === 'cloudfeatures' && subTabName === 'fleetstats') {
        loadFleetStatsInIframe();
    }

    // Redirect to Vercel for Leaderboards
    if (parentTab === 'cloudfeatures' && subTabName === 'leaderboards') {
        loadLeaderboardsInIframe();
    }

    // Redirect to Vercel for Config Sharing
    if (parentTab === 'cloudfeatures' && subTabName === 'configsharing') {
        loadConfigSharingInIframe();
    }

    const header = document.querySelector('.permanent-header');
    if (header && parentTab === 'cloudfeatures') {
        header.classList.add('permanent-header-sticky');
    }

    updateFlushPillVisibility(parentTab, subTabName);

    usageSetPage(parentTab + '-' + subTabName);
}

// Inner Alternator/Battery panel switch inside Live Data -> Diag. Dedicated to avoid the
// generic showSubTab() querySelectors clobbering these nested panels on outer tab switches.
function showDiagPanel(panelName, evt = null) {
    document.querySelectorAll('#livedata-diag .diag-panel').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#livedata-diag .diag-panel-tab').forEach(b => b.classList.remove('active'));
    const panel = document.getElementById('diag-panel-' + panelName);
    if (panel) panel.classList.add('active');
    if (evt && evt.target) {
        evt.target.classList.add('active');
    } else {
        // deep link (goToAltHealthDisplay): no event to mark, so match the pill by its handler —
        // otherwise every pill is left inactive and the tab strip reads as broken
        document.querySelectorAll('#livedata-diag .diag-panel-tab').forEach(b => {
            if ((b.getAttribute('onclick') || '').includes(`showDiagPanel('${panelName}'`)) b.classList.add('active');
        });
    }
    // Battery Health canvas was sized at width 0 while hidden — refresh once it's visible.
    if (panelName === 'battery') {
        updateBattHealthChemNote();
        if (typeof pollBatteryHealth === 'function') setTimeout(pollBatteryHealth, 60);
    }
}

// Capacity trend needs a rested-voltage curve to anchor SoC. Known chemistries get one from the
// Vessel-Info populator; type "other" gets none, so prompt the user to enter their own. Unknown
// (vessel info not yet loaded) shows no note so it never flashes on boot. DCIR is unaffected either way.
function updateBattHealthChemNote() {
    const note = document.getElementById('capChemNote');
    if (!note) return;
    const bt = window.vesselInfo && String(window.vesselInfo.battery_type || '').toLowerCase();
    note.style.display = (bt === 'other') ? '' : 'none';
}

// Inner Charge Settings / Battery Monitor switch inside Setup -> Battery. Dedicated (NOT showAltTab,
// which is hardcoded to #settings-alternator) so it can't clobber the alternator panels.
function showBatteryPanel(panelName, evt = null) {
    document.querySelectorAll('#settings-battery .diag-panel').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#settings-battery .diag-panel-tab').forEach(b => b.classList.remove('active'));
    const panel = document.getElementById('battery-panel-' + panelName);
    if (panel) panel.classList.add('active');
    if (evt && evt.target) evt.target.classList.add('active');
}

// Floating Cloud Upload pill — only visible on the cloud iframe sub-tabs.
const FLUSH_PILL_TABS = new Set(['leaderboards', 'fleetstats']);
function updateFlushPillVisibility(parentTab, subTabName) {
    const pill = document.getElementById('cloud-flush-pill');
    if (!pill) return;
    const visible = (parentTab === 'cloudfeatures' && FLUSH_PILL_TABS.has(subTabName));
    pill.style.display = visible ? 'block' : 'none';
    closeFlushPillConfirm();  // always reset to collapsed state on tab switch
}
function openFlushPillConfirm() {
    const c = document.getElementById('cloud-flush-pill-confirm');
    if (c) c.style.display = 'block';
}
function closeFlushPillConfirm() {
    const c = document.getElementById('cloud-flush-pill-confirm');
    if (c) c.style.display = 'none';
}

function showAltTab(group, panelId) {
    document.querySelectorAll('#settings-alternator .alt-panel-' + group)
        .forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#settings-alternator .alt-tab-btn-' + group)
        .forEach(t => t.classList.remove('active'));
    const panel = document.getElementById(panelId);
    if (panel) panel.classList.add('active');
    document.querySelectorAll('#settings-alternator .alt-tab-btn-' + group)
        .forEach(t => {
            // data-alt-panel is authoritative; the onclick fallback serves the secondary rows,
            // whose buttons still call showAltTab(...) inline.
            const declared = t.dataset.altPanel;
            const match = declared
                ? declared === panelId
                : (t.getAttribute('onclick') || '').includes(panelId);
            if (match) t.classList.add('active');
        });

}

// Dedicated switcher for the Tuning alt-panel's inner tabs. NOT showSubTab: #tuning is
// nested under Setup > Alternator, so the generic showSubTab('settings',...) querySelectors would
// clobber these panels — the same reason showBatteryPanel/showDiagPanel exist. Uses private
// .tuning-tab/.tuning-panel classes so the outer sub-tab machinery can never reach them.
function showTuningPanel(name, evt = null) {
    document.querySelectorAll('#tuning .tuning-panel').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('#tuning .tuning-tab').forEach(b => b.classList.remove('active'));
    const panel = document.getElementById('tuning-' + name);
    if (panel) panel.classList.add('active');
    if (evt && evt.target) {
        evt.target.classList.add('active');
    } else {
        document.querySelectorAll('#tuning .tuning-tab').forEach(b => {
            if ((b.getAttribute('onclick') || '').includes(`showTuningPanel('${name}'`)) b.classList.add('active');
        });
    }
    window.scrollTo(0, 0);
    resizeLivePlotsOnShow();   // charts in the revealed panel were built at width 0 while hidden
}

// Tuning is an alt-tab inside Setup > Alternator (id="tuning", .alt-panel). Route every
// deep-link through here so the main tab, sub-tab, and alt-tab are all set before the inner panel.
function goToTuning(subTab) {
    if (!subTab) {
        const active = document.querySelector('#tuning .tuning-panel.active');
        subTab = active ? active.id.replace('tuning-', '') : 'plant-delay';
    }
    showMainTab('settings');
    showSubTab('settings', 'alternator');
    showAltTab('primary', 'tuning');
    showTuningPanel(subTab);
}

// Paired shortcuts for the CV-Mode voltage setpoint and the Voltage-loop tuning tab,
