// Frozen page response stuff
function showRecoveryOptions() {
    // Don't show multiple recovery dialogs.
    // querySelector (not getElementById) so the load-time MISSING-ELEMENT debug
    // shim doesn't false-flag this pre-creation existence check.
    if (document.querySelector('#recoveryDialog')) return;

    // App: Retry reloads → discovery re-scans the network, so a moved IP heals.
    // Browser: it can't scan, and after a hotspot bounce the regulator usually
    // has a NEW address — say so plainly instead of letting Retry spin forever.
    let addressHint;
    if (IS_CAPACITOR && phoneIsOffline()) {
        // The phone, not the regulator, is the problem — say so instead of sending
        // the user off to power-cycle hardware that is probably fine.
        addressHint = `This phone reports <b>no network connection</b>. Turn WiFi on, or rejoin the boat's network, and the app will reconnect on its own.`;
    } else if (IS_CAPACITOR) {
        const lastBase = localStorage.getItem('xregDeviceBase') || 'http://alternator.local';
        // The unit name is user text — placeholder here, textContent after insertion.
        addressHint = `Last reached <b id="recoveryUnitName"></b> at <b>${lastBase}</b>. Retry re-scans the network in case the regulator came back at a different address.`;
    } else {
        addressHint = `This browser can't scan the network for the regulator. If it reconnected at a new address, <b>http://alternator.local</b> usually finds it; otherwise look up its IP in your router or phone-hotspot device list (hotspots assign 172.20.10.2&ndash;14). With two regulators on one network, <b>alternator.local</b> can land on either one &mdash; each also answers at its own <b>xreg-&lt;id&gt;.local</b> address, shown under Setup &#9656; System.`;
    }

    // Access-point users have no router to fall back on: offer the one-tap join
    // instead of sending them out to Settings > Wi-Fi. The SSID is written with
    // textContent after insertion — it is user-editable text, never markup.
    const joinBlock = wifiJoinPlugin() ? `
      <button onclick="joinRegulatorHotspot('recoveryJoinStatus')" style="width:100%; margin-top:10px; background:#2b3f4a; border:1px solid #3f6070; color:#9fd8e8; border-radius:5px; padding:9px 16px; cursor:pointer; font-size:13px;">Join Regulator WiFi</button>
      <p style="font-size:11px; color:#777; margin:6px 0 0;">Asks this phone to join <b id="recoveryJoinSsid"></b>, the hotspot the regulator broadcasts in access-point mode. Its name and password live under Setup &#9656; System.</p>
      <p id="recoveryJoinStatus" style="font-size:11px; color:#8fd9d3; margin:6px 0 0; min-height:13px;"></p>` : '';

    // A boat can carry more than one regulator, and a lost connection is exactly when the app
    // may have been following the wrong one. Offer the choice instead of re-racing for it.
    const switchBlock = IS_CAPACITOR ? `
      <button onclick="closeRecovery(); switchRegulator();" style="width:100%; margin-top:10px; background:#2b3f4a; border:1px solid #3f6070; color:#9fd8e8; border-radius:5px; padding:9px 16px; cursor:pointer; font-size:13px;">Switch Regulator</button>
      <p style="font-size:11px; color:#777; margin:6px 0 0;">Lists every regulator answering on this network and lets you pick the one the app follows.</p>` : '';

    const recoveryDiv = document.createElement('div');
    recoveryDiv.id = 'recoveryDialog';
    recoveryDiv.innerHTML = `
<div style="position:fixed; inset:0; background:rgba(0,0,0,0.55); z-index:10000; display:flex; align-items:center; justify-content:center;">
  <div style="background:#1e1e1e; color:#ddd; width:430px; max-width:calc(100vw - 40px); border-radius:8px; box-shadow:0 6px 32px rgba(0,0,0,0.8); border:1px solid #444; box-sizing:border-box;">
    <div style="padding:10px 16px 9px; border-bottom:1px solid #333; display:flex; align-items:center; justify-content:space-between; background:#252525; border-radius:8px 8px 0 0;">
      <span style="font-weight:600; font-size:13px; color:#aaa; letter-spacing:0.03em;">Connection Lost</span>
      <button onclick="closeRecovery()" style="background:none; border:none; color:#888; cursor:pointer; font-size:18px; padding:0 4px; line-height:1;">&#10005;</button>
    </div>
    <div style="padding:18px 20px 20px; font-size:0.92em; line-height:1.5;">
      <p style="margin:0 0 10px; color:#bbb;">Lost connection to the alternator regulator.</p>
      <p style="margin:0 0 14px; color:#888; font-size:0.92em;">${addressHint}</p>
      <div style="display:flex; gap:10px;">
        <button onclick="retryConnection()" style="flex:1; background:linear-gradient(180deg,#35d6c7,#23a99c); color:#06302d; font-weight:700; font-size:13px; border:none; border-radius:5px; padding:9px 16px; cursor:pointer;">Retry Connection</button>
        <button onclick="enterOfflineMode()" style="flex:1; background:#3a3a3a; border:1px solid #555; color:#ddd; border-radius:5px; padding:9px 16px; cursor:pointer; font-size:13px;">Continue Offline</button>
      </div>
      ${joinBlock}
      ${switchBlock}
      <p style="font-size:11px; color:#777; margin:12px 0 0;">If the problem persists, the device may need to be power-cycled.</p>
    </div>
  </div>
</div>
`;
    document.body.appendChild(recoveryDiv);
    const ssidEl = document.getElementById('recoveryJoinSsid');
    if (ssidEl) ssidEl.textContent = getRegulatorApCreds().ssid;
    const unitEl = document.getElementById('recoveryUnitName');
    if (unitEl) unitEl.textContent = localStorage.getItem('xregDeviceName') || 'the regulator';
}
function retryConnection() {
    closeRecovery();
    location.reload();
}
function closeRecovery() {
    const dialog = document.getElementById('recoveryDialog');
    if (dialog) {
        dialog.remove();
    }
}
function enterOfflineMode() {
    closeRecovery();
    if (isOfflineMode) return;
    isOfflineMode = true;
    // Disable all form controls and buttons except reconnect and tab navigation
    document.querySelectorAll('input[type="submit"], button, input[type="checkbox"], input[type="number"], input[type="text"], input[type="password"], select').forEach(el => {
        // Skip the dark mode toggle, reconnect buttons, and tab navigation
        if (!el.id.includes('DarkMode') &&
            !el.onclick?.toString().includes('location.reload') &&
            !el.classList.contains('main-tab') &&
            !el.classList.contains('sub-tab')) {
            el.disabled = true;
            el.style.opacity = '0.5';
            el.style.cursor = 'not-allowed';
        }
    });
    document.querySelectorAll('.switch input').forEach(el => {
        el.disabled = true;
        el.style.opacity = '0.5';
    });
    document.querySelectorAll('.conn-dot').forEach(d => {
        d.classList.remove('conn-dot--down');
        d.classList.add('conn-dot--offline');
    });
}

// Called from the SSE 'open' handler when a reconnect succeeds after the user
// had clicked "Continue Offline". Mirrors enterOfflineMode's selectors so the
// same set of elements is re-enabled. The connection dot itself is reset by
// updateInlineStatus(true) which the 'open' handler already calls.
function exitOfflineMode() {
    if (!isOfflineMode) return;
    isOfflineMode = false;
    document.querySelectorAll('input[type="submit"], button, input[type="checkbox"], input[type="number"], input[type="text"], input[type="password"], select').forEach(el => {
        if (!el.id.includes('DarkMode') &&
            !el.onclick?.toString().includes('location.reload') &&
            !el.classList.contains('main-tab') &&
            !el.classList.contains('sub-tab')) {
            el.disabled = false;
            el.style.opacity = '';
            el.style.cursor = '';
        }
    });
    document.querySelectorAll('.switch input').forEach(el => {
        el.disabled = false;
        el.style.opacity = '';
    });
}


function validateSettings() {
    const validations = [
        {
            inputs: ['FloatVoltage', 'BulkVoltage'],
            check: (float, bulk) => !isNaN(float) && !isNaN(bulk) && float >= bulk,
            error: 'Float voltage must be less than bulk voltage'
        },
        {
            inputs: ['MinDuty', 'MaxDuty'],
            check: (min, max) => !isNaN(min) && !isNaN(max) && min >= max,
            error: 'Minimum duty cycle must be less than maximum duty cycle'
        }
    ];

    document.querySelectorAll('.input-error').forEach(el => {
        el.classList.remove('input-error');
        el.title = '';
    });

    validations.forEach(validation => {
        const [input1Name, input2Name] = validation.inputs;
        const input1 = document.querySelector(`input[name="${input1Name}"]`);
        const input2 = document.querySelector(`input[name="${input2Name}"]`);

        if (!input1 || !input2) return;

        const value1 = input1.valueAsNumber;
        const value2 = input2.valueAsNumber;
        const button1 = input1.closest('form')?.querySelector('input[type="submit"]');
        const button2 = input2.closest('form')?.querySelector('input[type="submit"]');

        if (validation.check(value1, value2)) {
            input1.classList.add('input-error');
            input2.classList.add('input-error');
            input1.title = validation.error;
            input2.title = validation.error;

            if (button1) {
                button1.disabled = true;
                button1.title = validation.error;
            }
            if (button2) {
                button2.disabled = true;
                button2.title = validation.error;
            }
        } else {
            if (button1) {
                button1.disabled = false;
                button1.title = '';
            }
            if (button2) {
                button2.disabled = false;
                button2.title = '';
            }
        }
    });
}


// Reads the ten breakpoint rows as the firmware does: row 0 always counts, later rows only
// while RPM is non-zero, and the first zero ends the table (5_functions.ino fuelRate_GPH).
// Burn values come back in the DISPLAY unit, not gallons — for the curve and the row
// highlight only. The gallons truth is _fuelGphShadow.
function readFuelTablePoints() {
    const pts = [];
    for (let i = 0; i < 10; i++) {
        const rpmInput = document.getElementById(`fuelTableRPM${i}_input`);
        const gphInput = document.getElementById(`fuelTableGPH${i}_input`);
        if (!rpmInput || !gphInput) break;
        const rpm = parseFloat(rpmInput.value) || 0;
        if (i > 0 && rpm <= 0) break;
        pts.push([rpm, parseFloat(gphInput.value) || 0]);
    }
    return pts;
}

// Burn curve under the table. Draws exactly what the firmware interpolates — straight between
// points, first and last value held flat past the ends — so a mistyped breakpoint reads as a
// kink. Colours come from .fc-* CSS classes so a dark-mode flip needs no redraw.
function drawFuelCurve() {
    const svg = document.getElementById('fuelCurveSvg');
    if (!svg) return;
    const pts = readFuelTablePoints();
    if (pts.length < 2) { svg.innerHTML = ''; return; }

    const W = 320, H = 110, L = 34, R = 6, T = 8, B = 20;
    const maxR = pts[pts.length - 1][0] || 1;
    const maxG = Math.max(...pts.map(p => p[1]), 0.1);
    const X = r => L + (r / maxR) * (W - L - R);
    const Y = g => H - B - (g / maxG) * (H - T - B);

    let d = `M ${X(0)} ${Y(pts[0][1])} `;          // flat clamp below the first breakpoint
    pts.forEach(p => { d += `L ${X(p[0])} ${Y(p[1])} `; });

    let out = `<line class="fc-grid" x1="${L}" y1="${H - B}" x2="${W - R}" y2="${H - B}"/>`
            + `<line class="fc-grid" x1="${L}" y1="${T}" x2="${L}" y2="${H - B}"/>`
            + `<path class="fc-line" d="${d}"/>`;
    pts.forEach(p => { out += `<circle class="fc-dot" cx="${X(p[0])}" cy="${Y(p[1])}" r="2.6"/>`; });
    out += `<text class="fc-lbl" x="${L - 4}" y="${T + 8}" text-anchor="end">${maxG.toFixed(1)}</text>`
         + `<text class="fc-lbl" x="${L - 4}" y="${H - B + 3}" text-anchor="end">0</text>`
         + `<text class="fc-lbl" x="${L}" y="${H - 6}">0 rpm</text>`
         + `<text class="fc-lbl" x="${W - R}" y="${H - 6}" text-anchor="end">${maxR} rpm</text>`;
    svg.innerHTML = out;
}

// Tints the fuel row bracketing live engine RPM. Own class, not the cap table's
// .learning-table-row-active — updateLearningTableHighlight() clears that one document-wide.
let _fuelHighlightRow = -1;
function updateFuelTableHighlight(data) {
    if (data.RPM === undefined) return;
    const rpm = Number(data.RPM);
    const pts = readFuelTablePoints();

    let row = -1;
    if (pts.length >= 2 && rpm > 0) {
        for (let i = pts.length - 1; i >= 0; i--) {
            if (rpm >= pts[i][0]) { row = i; break; }
        }
    }
    if (row === _fuelHighlightRow) return;

    const prev = document.getElementById(`fuelRow${_fuelHighlightRow}`);
    if (prev) prev.classList.remove('fuel-table-row-active');
    const next = document.getElementById(`fuelRow${row}`);
    if (next) next.classList.add('fuel-table-row-active');
    _fuelHighlightRow = row;
}

function validateFuelTable() {
    const errors = [];
    const rpmValues = [];
    const gphValues = [];

    for (let i = 0; i < 10; i++) {
        const rpmInput = document.getElementById(`fuelTableRPM${i}_input`);
        const gphInput = document.getElementById(`fuelTableGPH${i}_input`);

        if (rpmInput && gphInput) {
            rpmValues[i] = parseFloat(rpmInput.value) || 0;
            gphValues[i] = parseFloat(gphInput.value) || 0;
        }
    }

    // Check that RPM values are strictly increasing (ignoring trailing zeros)
    let lastNonZeroIndex = -1;
    for (let i = 9; i >= 0; i--) {
        if (rpmValues[i] !== 0) {
            lastNonZeroIndex = i;
            break;
        }
    }

    // Validate RPM increases up to last non-zero entry
    for (let i = 0; i <= lastNonZeroIndex; i++) {
        if (i > 0 && rpmValues[i] <= rpmValues[i - 1]) {
            errors.push(`RPM values must increase. Row ${i + 1} (${rpmValues[i]}) must be greater than Row ${i} (${rpmValues[i - 1]})`);
            break;
        }
    }

    // Check that zeros only appear at the end (but allow first row to be 0,0)
    let foundNonZero = false;
    for (let i = 9; i >= 1; i--) {  // Start at i=1 to skip first row
        if (rpmValues[i] !== 0) {
            foundNonZero = true;
        } else if (foundNonZero) {
            errors.push(`Zero RPM values are only allowed at the end of the table. Found zero at row ${i + 1}`);
            break;
        }
    }

    if (errors.length > 0) {
        xAlert('Fuel Table Validation Error:\n\n' + errors.join('\n'));
        return false;
    }

    return true;
}
function validateLearningTable() {
    const errors = [];
    const rpmValues = [];

    for (let i = 0; i < 10; i++) {
        const rpmInput = document.getElementById(`rpmTableRPMPoints${i}_input`);
        if (rpmInput) {
            rpmValues[i] = parseFloat(rpmInput.value) || 0;
        }
    }

    let lastNonZeroIndex = -1;
    for (let i = 9; i >= 0; i--) {
        if (rpmValues[i] !== 0) {
            lastNonZeroIndex = i;
            break;
        }
    }

    // Validate RPM strictly increases up to last non-zero entry
    for (let i = 0; i <= lastNonZeroIndex; i++) {
        if (i > 0 && rpmValues[i] <= rpmValues[i - 1]) {
            errors.push(`RPM values must increase. Row ${i + 1} (${rpmValues[i]}) must be greater than Row ${i} (${rpmValues[i - 1]})`);
            break;
        }
    }

    // Check that zeros only appear at the end
    let foundNonZero = false;
    for (let i = 9; i >= 0; i--) {
        if (rpmValues[i] !== 0) {
            foundNonZero = true;
        } else if (foundNonZero) {
            errors.push(`Zero RPM values are only allowed at the end of the table. Found zero at row ${i + 1}`);
            break;
        }
    }

    if (errors.length > 0) {
        xAlert('Learning Table Validation Error:\n\n' + errors.join('\n'));
        return false;
    }
    return true;
}

// Calculate and display RPM ranges below each breakpoint
function updateRPMRangeDisplays(data) {
    if (!document.querySelector('#rpm-range-0')) return;
    for (let i = 0; i < 10; i++) {
        const rangeSpan = document.querySelector(`#rpm-range-${i}`);
        if (rangeSpan) {
            if (i < 9) {
                const nextRPM = data[`rpmTableRPMPoints${i + 1}`];
                rangeSpan.textContent = nextRPM || '-';
            } else {
                rangeSpan.textContent = '∞';
            }
        }
    }
}
//  validation called in the window load event, for client side checking of input values
function setupInputValidation() {
    const settingsInputs = ["FloatVoltage", "BulkVoltage", "MinDuty", "MaxDuty"];

    settingsInputs.forEach(name => {
        const input = document.querySelector(`input[name="${name}"]`);
        if (input) {
            input.addEventListener("input", validateSettings);
            input.addEventListener("blur", validateSettings);
        } else {
            diagWarn(`Validation input not found: ${name}`);
        }
    });
    setTrackedTimeout(() => {
        validateSettings();
    }, 100); // Small delay to ensure all data is loaded
}
