// Small cloud-state badge on the Charging System Health + Speed (boat performance) panels. Uses signals the
// dashboard already has — currentMode (AP=1) and the CloudFeatures toggle. Local-only states are grey;
// cloud-on is green. (A "synced N ago" upgrade would need a firmware sync-timestamp — not wired yet.)
function updateCloudStatus() {
    const ap = (window._lastKnownMode === 1);   // 1 = Access Point
    const cb = document.getElementById('CloudFeatures_checkbox');
    const on = cb ? !!cb.checked : false;
    const fmtAgo = (s) => {                       // seconds since last successful sync (this boot); <0 = none
        if (s == null || s < 0) return '';
        if (s < 90)   return ', synced just now';
        if (s < 5400) return ', synced ' + Math.round(s / 60) + 'm ago';
        return ', synced ' + Math.round(s / 3600) + 'h ago';
    };
    const set = (id, agoS) => {
        const el = document.getElementById(id);
        if (!el) return;
        if (ap)       { el.textContent = '· AP mode (local only)';   el.style.color = '#888'; }
        else if (!on) { el.textContent = '· cloud off (local only)'; el.style.color = '#888'; }
        else          { el.textContent = '· cloud on' + fmtAgo(agoS); el.style.color = '#5cb85c'; }
    };
    set('alt-cloud-status',  (typeof altLive  !== 'undefined') ? altLive.syncAgoS  : null);
    set('perf-cloud-status', (typeof perfLive !== 'undefined') ? perfLive.syncAgoS : null);
}

// Cloud off used to HIDE this tab, which read as "my regulator doesn't have that feature".
// It now stays visible and greyed; body.cloud-off swaps its panels for the .gate-note-cloud
// explanation (styles.css), so landing on it is informative instead of a wall of failing iframes.
function updateCloudFeaturesTabVisibility(enabled) {
    document.body.classList.toggle('cloud-off', !enabled);
    const cloudTab = document.querySelector('.main-tab[onclick*="cloudfeatures"]');
    if (cloudTab) cloudTab.classList.toggle('gate-cloud', !enabled);
}
function updateCloudFeaturesToggleState(currentMode) {
    const checkbox = document.getElementById("CloudFeatures_checkbox");
    const isAPMode = (currentMode === 1); // 1 = Access Point mode

    if (checkbox) {
        // The row's greying comes from body.ap-mode + .gate-ap; only the disabled state and the
        // forced-off value belong here.
        checkbox.disabled = isAPMode;
        if (isAPMode) {
            checkbox.checked = false;
            updateCloudFeaturesTabVisibility(false);
        }
    }

    updateUploadNowButtonState(currentMode);
}

// "Upload Now" (forceCloudFlush) is a dead button unless cloud uploads can actually happen:
// the loop() drain is gated behind CloudFeatures==1 + client mode + WiFi. So gray it out in
// AP mode (no internet) OR when Cloud Features is OFF. Records keep buffering either way and
// upload automatically once on WiFi with cloud on; "Clear" stays enabled (purely local wipe).
// mode is optional — falls back to the last known currentMode for cloud-toggle/CSV callers.
function updateUploadNowButtonState(mode) {
    const uploadBtn = document.getElementById('cloudUploadNowBtn');
    if (!uploadBtn) return;
    const isAPMode = ((mode !== undefined ? mode : window._lastKnownMode) === 1); // 1 = MODE_AP
    const cb = document.getElementById('CloudFeatures_checkbox');
    const cloudOn = cb ? !!cb.checked : false;
    const blocked = isAPMode || !cloudOn;
    if (!uploadBtn.dataset.titleDefault) uploadBtn.dataset.titleDefault = uploadBtn.title;
    uploadBtn.disabled = blocked;
    uploadBtn.style.opacity = blocked ? '0.5' : '1';
    uploadBtn.style.cursor = blocked ? 'not-allowed' : '';
    uploadBtn.title = isAPMode
        ? 'Cloud upload is unavailable in AP mode (no internet). Records keep buffering and upload automatically once the regulator is on WiFi.'
        : (!cloudOn
            ? 'Cloud upload requires Cloud Features ON (Setup). Records keep buffering locally; turn Cloud Features on and they upload automatically.'
            : uploadBtn.dataset.titleDefault);
}


